31	/* ---------------------------------------------------------------- validator */
32	// 支持 draft-07 子集：type(含数组)/required/properties/additionalProperties/
33	// enum/pattern/minLength/maxLength/minimum/maximum/items/minItems/maxItems
34	function matchType(t, v) {
35	  switch (t) {
36	    case "string": return typeof v === "string";
37	    case "integer": return Number.isInteger(v);
38	    case "number": return typeof v === "number" && Number.isFinite(v);
39	    case "boolean": return typeof v === "boolean";
40	    case "array": return Array.isArray(v);
41	    case "object": return v !== null && typeof v === "object" && !Array.isArray(v);
42	    case "null": return v === null;
43	    default: return false;
44	  }
45	}
46	function describe(v) {
47	  if (v === null) return "null";
48	  if (Array.isArray(v)) return "array";
49	  return typeof v;
50	}
51	function validateNode(schema, value, path, errs) {
52	  const types = Array.isArray(schema.type) ? schema.type : [schema.type].filter(Boolean);
53	  if (types.length && !types.some((t) => matchType(t, value))) {
54	    errs.push(`${path}: 期望类型 ${types.join("|")}，实际 ${describe(value)}`);
55	    return;
56	  }
57	  if (schema.enum && !schema.enum.includes(value)) {
58	    errs.push(`${path}: 必须是 ${schema.enum.join(" / ")}，实际 ${JSON.stringify(value)}`);
59	  }
60	  if (typeof value === "string") {
61	    if (schema.minLength != null && value.length < schema.minLength)
62	      errs.push(`${path}: 长度 ${value.length} < minLength ${schema.minLength}`);
63	    if (schema.maxLength != null && value.length > schema.maxLength)
64	      errs.push(`${path}: 长度 ${value.length} > maxLength ${schema.maxLength}`);
65	    if (schema.pattern && !new RegExp(schema.pattern).test(value))
66	      errs.push(`${path}: "${value}" 不匹配 /${schema.pattern}/`);
67	  }
68	  if (typeof value === "number") {
69	    if (schema.minimum != null && value < schema.minimum)
70	      errs.push(`${path}: ${value} < minimum ${schema.minimum}`);
71	    if (schema.maximum != null && value > schema.maximum)
72	      errs.push(`${path}: ${value} > maximum ${schema.maximum}`);
73	  }
74	  if (Array.isArray(value)) {
75	    if (schema.minItems != null && value.length < schema.minItems)
76	      errs.push(`${path}: ${value.length} 项 < minItems ${schema.minItems}`);
77	    if (schema.maxItems != null && value.length > schema.maxItems)
78	      errs.push(`${path}: ${value.length} 项 > maxItems ${schema.maxItems}`);
79	    if (schema.items) value.forEach((v, i) => validateNode(schema.items, v, `${path}[${i}]`, errs));
80	  }
81	  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
82	    for (const req of schema.required ?? []) {
83	      if (!(req in value)) errs.push(`${path}: 缺少必填字段 "${req}"`);
84	    }
85	    for (const [k, v] of Object.entries(value)) {
86	      const ps = schema.properties?.[k];
87	      if (ps) validateNode(ps, v, `${path}.${k}`, errs);
88	      else if (schema.additionalProperties === false)
89	        errs.push(`${path}: 未知字段 "${k}"（schema additionalProperties=false）`);
90	    }
91	  }
92	}
93	const validateBrief = (schema, brief) => {
