function freePort() {
  return new Promise((resolve, reject) => {
    const probe = (attempt) => {
      const candidate = 8900 + Math.floor(Math.random() * 200);
      const srv = tcpProbe();
      srv.once("error", () => { if (attempt < 20) probe(attempt + 1); else reject(new Error("no free port")); });
      srv.listen(candidate, () => srv.close(() => resolve(candidate)));
    };
    probe(0);
  });
}
