// 挂载真实皮肤 + 真实 deploy-ready/app.js 并启动 —— 全部皮肤测试共用的 boot 序列。
//
// 流程与被替换前的单文件版本逐字等价：
//   1. 动态 import deploy-ready/themes/<skinId>/skin.js（真实皮肤模块）
//   2. 以 __MYTHIC_SKINS__ 预置皮肤（app.js 走 presetSkins() 路径，不发 HEAD 探测）
//   3. 用 new Function 执行真实 app.js 源码（无构建、无 DOM 触碰，渲染在 bind 时才发生）
//   4. 等待 80ms 让 boot 的异步链（loadSkin → content fetch）走完
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { sleep } from "./suite.mjs";

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
export const DEPLOY = join(ROOT, "deploy-ready");

export async function bootSkinApp(skinId) {
  const skinModule = await import(pathToFileURL(join(DEPLOY, "themes", skinId, "skin.js")).href);
  globalThis.__MYTHIC_SKINS__ = { [skinId]: skinModule.default };
  const appSource = readFileSync(join(DEPLOY, "app.js"), "utf8");
  new Function("module", "exports", appSource)({ exports: {} }, {});
  await sleep(80);
  return readFileSync(join(DEPLOY, "themes", skinId, "skin.css"), "utf8");
}

export function unbootSkinApp() {
  delete globalThis.__MYTHIC_SKINS__;
}

