// 微型测试套件 — check/assert/sleep + 汇总打印。
// 输出格式与被替换前的单文件测试保持一致，方便和旧基线输出对照。
export const assert = (condition, message) => { if (!condition) throw new Error(message); };
export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export function createSuite(title) {
  const results = [];
  const check = (name, fn) => {
    try {
      const d = fn();
      if (d && typeof d.then === "function") {
        return d.then((detail) => results.push({ ok: true, name, d: detail }),
          (e) => results.push({ ok: false, name, d: e.message }));
      }
      results.push({ ok: true, name, d: d });
    } catch (e) {
      results.push({ ok: false, name, d: e.message });
    }
    return Promise.resolve();
  };
  const report = () => {
    const failures = results.filter((r) => !r.ok);
    console.log(`\n${title}\n`);
    for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
    console.log(`\n${results.length - failures.length}/${results.length} passed`);
    process.exit(failures.length ? 1 : 0);
  };
  return { results, check, report };
}

