// 皮肤 CSS/JS 审计 — 防止皮肤越界的三项静态检查。
//
// 1. assertScopedCss：皮肤 css 必须完全罩在 body[data-skin=…] 下，花括号平衡，
//    且不得出现其他产品的类前缀（跨产品泄漏）。
// 2. assertClassesCovered：skin.js 模板里用到的 `<prefix>-*` 类必须在 skin.css
//    里有定义（hooks 是 app.js 注入、不需要皮肤自设的例外类名）。
// 3. assertExpressionOnlySkin：skin.js 只许做表达，禁止评分/网络/内容文件逻辑。
//
// 默认值即历史单文件版本共用的那一套；主题专属差异通过参数传入。
export function assertScopedCss(css, { foreignPrefixes = [] } = {}) {
  const stripped = css.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") && opens === 1) {
      if (!/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  if (depth !== 0) throw new Error("unbalanced braces in skin css");
  for (const foreign of foreignPrefixes) {
    if (css.includes(foreign)) throw new Error(`skin css must not reference ${foreign} (cross-product leak)`);
  }
  return "scoped, no cross-product selectors";
}

export function assertClassesCovered({ js, css, prefix, hooks = [] }) {
  if (!prefix) throw new Error("assertClassesCovered: prefix 必填（如 \"cp-\"）");
  const used = new Set(
    [...js.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/))
      .flatMap((c) => c.match(new RegExp(`${prefix}[a-z0-9-]+`, "g")) || [])
  );
  const hookSet = new Set(hooks);
  const defined = new Set([...css.matchAll(new RegExp(`\\.(${prefix}[a-z0-9-]+)`, "g"))].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c) && !hookSet.has(c));
  if (missing.length > 0) throw new Error(`classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
}

export function assertExpressionOnlySkin(js, banned = []) {
  const defaults = ["normalization_bounds", "selectWinner", "quiz_content_upgrade", "fetch("];
  for (const word of [...defaults, ...banned]) {
    if (js.includes(word)) throw new Error(`skin must not contain ${word}`);
  }
  return "expression only";
}

