/* 猫咪角色皮肤 · 端到端流程测试。
 *
 * 真实 deploy-ready/app.js + 真实 themes/cat-personas/skin.js 驱动完整流程：
 * 入场（兑换码）→ 封面 → 16 题作答 → 服务端评分（真实 server/scoring.mjs）
 * → 结果页（原创短句，不得伪造出处）→ 保存/重测。另附 8 结果可达性采样
 * 与跨产品隔离检查。
 *
 * 公共设施（DOM 桩 / API 桩 / boot / 可达性 / CSS 审计）在 tools/lib/，
 * 本文件只保留猫咪主题专属的断言。
 *
 * Run: node tools/test-cat-skin.mjs
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { installDom } from "./lib/dom-stub.mjs";
import { installApiStub } from "./lib/api-stub.mjs";
import { bootSkinApp, unbootSkinApp, DEPLOY, ROOT } from "./lib/boot-app.mjs";
import { createSuite, assert, sleep } from "./lib/suite.mjs";
import { reachableResults } from "./lib/reachability.mjs";
import { assertScopedCss, assertClassesCovered, assertExpressionOnlySkin } from "./lib/css-audit.mjs";
import { selectWinner } from "../server/scoring.mjs";
import { productThemes } from "../server/products.mjs";

const PRODUCT = "cat-personas";
const SKIN_PREFIX = "cp-";
const CODE = "CATSMOKETEST01";
const SECRET = "[REDACTED:SECRET_ASSIGNMENT]";
const CAT_THEMES = productThemes(PRODUCT);

const { appEl, bodyEl, canvas } = installDom({ pathname: `/t/${PRODUCT}` });
installApiStub({ productId: PRODUCT, productName: "你是哪一种猫咪", themes: CAT_THEMES, code: CODE, secret: SECRET });
const { check, report } = createSuite("猫咪角色皮肤 · 流程测试");

const skinCss = await bootSkinApp(PRODUCT);
const appSource = readFileSync(join(DEPLOY, "app.js"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the cat entrance skin, not the default gate", () => {
  assert(appEl.querySelector(".cp-title"), "cat gate title missing");
  assert(appEl.querySelector(".cp-gate-form"), "gate form missing");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
  assert(bodyEl.attributes["data-skin"] === PRODUCT, "body data-skin not set");
  assert(globalThis.document.title === "假如你是一只猫，会是哪一种？", `skin title wrong: ${globalThis.document.title}`);
  return "entrance";
});

await check("a valid code unlocks the cover with the 8-color cast row", async () => {
  const input = appEl.querySelector("#cp-gate-code");
  const submit = appEl.querySelector("#cp-gate-submit");
  input.value = CODE.toLowerCase();
  submit.click();
  await sleep(120);
  assert(appEl.querySelector(".cp-cover"), "cat cover missing after redeem");
  assert(appEl.querySelector(".cp-cover .cp-title").textContent.includes("一只猫"), "cover title wrong");
  assert(appEl.querySelector(".cp-cover").textContent.includes("假设你就是一只猫"), "opening premise missing");
  assert(appEl.querySelectorAll(".cp-cast-dot").length === 8, "cast row must show 8 personas");
  assert(appEl.querySelector("#cp-start"), "start button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
  return "cover";
});

await check("starting shows question 1 of 16 with three options and a progress bar", async () => {
  appEl.querySelector("#cp-start").click();
  await sleep(80);
  assert(appEl.querySelector(".cp-q-count").textContent.includes("第 1 题"), `expected Q1, got ${appEl.querySelector(".cp-q-count")?.textContent}`);
  assert(appEl.querySelectorAll(".cp-option").length === 3, "three options expected");
  assert(appEl.querySelector(".cp-progress i"), "progress bar missing");
  assert(appEl.querySelector(".cp-top").textContent.includes("1 / 16"), "topbar counter wrong");
  return "Q1";
});

await check("picking an option colors it and advances", async () => {
  appEl.querySelectorAll(".cp-option")[1].click();
  await sleep(60);
  assert(appEl.querySelectorAll(".cp-option")[1].classList.contains("picked"), "option must be picked before advancing");
  await sleep(340);
  assert(appEl.querySelector(".cp-q-count").textContent.includes("第 2 题"), "did not advance to Q2");
  appEl.querySelector("#cp-prev").click();
  await sleep(50);
  assert(appEl.querySelector(".cp-q-count").textContent.includes("第 1 题"), "上一题 failed");
  assert(appEl.querySelectorAll(".cp-option")[1].classList.contains("picked"), "returning must show the recorded pick");
  return "pick + back";
});

await check("a full 16-question run lands on a named result page", async () => {
  for (let i = 0; i < 16; i += 1) {
    const count = appEl.querySelector(".cp-q-count");
    assert(count, `question ${i + 1} missing`);
    appEl.querySelectorAll(".cp-option")[0].click();
    await sleep(340);
  }
  const name = appEl.querySelector(".cp-name");
  assert(name, "result name missing");
  const quote = appEl.querySelector(".cp-quote");
  assert(quote && quote.textContent.includes("「") && quote.textContent.trim().length > 5, "quoted short line missing");
  assert(!appEl.querySelector(".cp-blurb") && !appEl.querySelector(".cp-supplement"), "blurb/supplement must be gone in v2");
  assert(appEl.querySelector(".cp-top").textContent.trim().endsWith("你是哪一种猫咪？"), "result topbar right label must be empty");
  assert(!appEl.querySelector(".cp-name-en"), "english subname must be gone in v2");
  assert(appEl.querySelector("#cp-share"), "save button missing");
  for (const id of ["#cp-copy", "#cp-again", "#cp-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  assert(!appEl.querySelector(".cp-more"), "no long report section allowed");
  return `角色：${name.textContent}`;
});

await check("result page carries the persona accent color and artwork slot", () => {
  const section = appEl.querySelector(".cp-result");
  assert(section.attributes.style && section.attributes.style.includes("--cp-accent"), "accent color not set on result");
  assert(appEl.querySelector(".cp-portrait"), "portrait slot missing");
  return "accent + portrait";
});

await check("share and copy actions work inside the skin", async () => {
  canvas.created = 0;
  appEl.querySelector("#cp-share").click();
  appEl.querySelector("#cp-copy").click();
  await sleep(60);
  const copy = appEl.querySelector("#cp-copy");
  assert(copy.textContent.includes("已复制"), `copy feedback wrong: ${copy.textContent}`);
  assert(canvas.created >= 1, "share must build a canvas image");
  return "share + copy";
});

await check("again restarts at Q1, exit returns to the cover", async () => {
  appEl.querySelector("#cp-again").click();
  await sleep(60);
  assert(appEl.querySelector(".cp-q-count").textContent.includes("第 1 题"), "再测一次 failed");
  appEl.querySelector("#cp-exit").click();
  await sleep(60);
  assert(appEl.querySelector(".cp-cover"), "回封面 failed");
  return "again + exit";
});

/* ------------------------------------------------------- 可达性 ---- */
check("all 8 personas are reachable, not via tie-break", () => {
  const theme = CAT_THEMES[0];
  assert(theme.results.length === 8, `expected 8 results, got ${theme.results.length}`);
  return reachableResults({ theme, selectWinner, seed: 84848, threshold: 0.8, label: "personas" });
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped and does not touch other products", () => {
  assertScopedCss(skinCss, { foreignPrefixes: ["pp-", "ggw-", "dp-"] });
  return "scoped, no cross-product selectors";
});

check("skin classes used by skin.js all exist in skin.css", () => {
  const js = readFileSync(join(DEPLOY, "themes", PRODUCT, "skin.js"), "utf8");
  return assertClassesCovered({ js, css: skinCss, prefix: SKIN_PREFIX, hooks: ["cp-top-right", "cp-option-text", "cp-q"] });
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(DEPLOY, "themes", PRODUCT, "skin.js"), "utf8");
  assertExpressionOnlySkin(js, ["cat_personas.json", "disney_princess"]);
  return "expression only";
});

check("the content file is this product's own private matrix", () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", PRODUCT, "product.json"), "utf8"));
  assert(manifest.name === "假如你是一只猫", "product name must be v2");
  assert(manifest.content_file === "../../cat_personas.json", "must own its private content file");
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "cat_personas.json"), "utf8"));
  assert(raw.themes.length === 1 && raw.themes[0].id === PRODUCT, "private file must hold only this theme");
  assert(raw.themes[0].questions.length === 16, "16 questions");
  assert(!appSource.includes("cp-"), "default templates must not reference cp- classes");
  return "own matrix, own file";
});

unbootSkinApp();
report();

