export function reachableResults({ theme, selectWinner, runs = 200, seed = 84848, leanProbability = 0.8, threshold = 0.8, label = "results", strictMargin = 0 }) {
  const ids = theme.results.map((r) => r.id);
  const rand = (() => {
    let s = seed;
    return () => {
      s = (s * 1103515245 + 12345) & 0x7fffffff;
      return s / 0x7fffffff;
    };
  })();

  const verdicts = [];
  const lows = [];
  for (const id of ids) {
    let wins = 0;
    for (let run = 0; run < runs; run += 1) {
      const answers = theme.questions.map((question) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < leanProbability) return topOptions[Math.floor(rand() * topOptions.length)];
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId, scores } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
      if (run === 0) {
        const full = theme.questions.map((question) =>
          question.options
            .map((o, i) => ({ i, s: o.scores[id] || 0 }))
            .sort((a, b) => b.s - a.s)[0].i);
        const verdict = selectWinner(theme, full);
        if (verdict.winnerId !== id) {
          throw new Error(`full-leaning run elects ${verdict.winnerId} for ${id}`);
        }
        if (strictMargin > 0) {
          // full-leaning run 必须以严格正的归一化边际获胜（不是压线平局）
          const bounds = theme.scoring.normalization_bounds;
          const norm = (raw, id2) => (100 * (raw[id2] - bounds[id2].minimum)) / (bounds[id2].maximum - bounds[id2].minimum);
          const mine = norm(verdict.scores, id);
          const bestOther = Math.max(...ids.filter((x) => x !== id).map((x) => norm(verdict.scores, x)));
          if (mine - bestOther < strictMargin) lows.push(`${id} margin ${(mine - bestOther).toFixed(1)}`);
        }
      }
    }
    const rate = wins / runs;
    if (rate < threshold) {
      throw new Error(`${id} leaning win-rate ${(rate * 100).toFixed(1)}% < ${threshold * 100}%`);
    }
    verdicts.push(`${id}:${(rate * 100).toFixed(0)}%`);
  }
  let summary = `${ids.length}/${ids.length} ${label} reachable`;
  if (strictMargin > 0) summary += `; strict margins${lows.length ? " (thin: " + lows.join(", ") + ")" : ` all ≥${strictMargin} pts`}`;
  return summary;
}

