/* 迪士尼公主皮肤 · 端到端流程测试。
 *
 * 真实 deploy-ready/app.js + 真实 themes/disney-princess/skin.js 驱动完整流程：
 * 入场（兑换码）→ 封面（13 位公主色卡）→ 24 题作答 → 服务端评分
 * （真实 server/scoring.mjs）→ 结果页（引文 + 出处 + blurb，出处必须诚实）
 * → 分享/复制/重测。另附 13 结果可达性采样（含严格边际）与跨产品隔离检查。
 *
 * 公共设施（DOM 桩 / API 桩 / boot / 可达性 / CSS 审计）在 tools/lib/，
 * 本文件只保留迪士尼主题专属的断言。
 *
 * Run: node tools/test-disney-skin.mjs
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { installDom } from "./lib/dom-stub.mjs";
import { installApiStub } from "./lib/api-stub.mjs";
import { bootSkinApp, unbootSkinApp, DEPLOY, ROOT } from "./lib/boot-app.mjs";
import { createSuite, assert, sleep } from "./lib/suite.mjs";
import { reachableResults } from "./lib/reachability.mjs";
import { assertScopedCss, assertClassesCovered, assertExpressionOnlySkin } from "./lib/css-audit.mjs";
import { selectWinner } from "../server/scoring.mjs";
import { productThemes } from "../server/products.mjs";

const PRODUCT = "disney-princess";
const SKIN_PREFIX = "dp-";
const CODE = "DPNOTESMOKE001";
const SECRET = "[REDACTED:SECRET_ASSIGNMENT]";
const DP_THEMES = productThemes(PRODUCT);

const { appEl, bodyEl, canvas } = installDom({ pathname: `/t/${PRODUCT}` });
installApiStub({ productId: PRODUCT, productName: "你是哪位迪士尼公主", themes: DP_THEMES, code: CODE, secret: SECRET });
const { check, report } = createSuite("迪士尼公主皮肤 · 流程测试");

const skinCss = await bootSkinApp(PRODUCT);
const appSource = readFileSync(join(DEPLOY, "app.js"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the princess entrance skin, not the default gate", () => {
  assert(appEl.querySelector(".dp-title"), "princess gate title missing");
  assert(appEl.querySelector(".dp-gate-form"), "gate form missing");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
  assert(bodyEl.attributes["data-skin"] === PRODUCT, "body data-skin not set");
  assert(globalThis.document.title === "你是哪位迪士尼公主？", `skin title wrong: ${globalThis.document.title}`);
  return "entrance";
});

await check("a valid code unlocks the cover with the 13-color cast row", async () => {
  const input = appEl.querySelector("#dp-gate-code");
  const submit = appEl.querySelector("#dp-gate-submit");
  input.value = CODE.toLowerCase();
  submit.click();
  await sleep(120);
  assert(appEl.querySelector(".dp-cover"), "princess cover missing after redeem");
  assert(appEl.querySelector(".dp-cover .dp-title").textContent.includes("迪士尼公主"), "cover title wrong");
  assert(appEl.querySelectorAll(".dp-cast-dot").length === 13, "cast row must show 13 princess colors");
  assert(appEl.querySelector("#dp-start"), "start button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
  return "cover";
});

await check("starting shows question 1 of 24 with three options and a progress bar", async () => {
  appEl.querySelector("#dp-start").click();
  await sleep(80);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 1 题"), `expected Q1, got ${appEl.querySelector(".dp-q-count")?.textContent}`);
  assert(appEl.querySelectorAll(".dp-option").length === 3, "three options expected");
  assert(appEl.querySelector(".dp-progress i"), "progress bar missing");
  assert(appEl.querySelector(".dp-top").textContent.includes("1 / 24"), "topbar counter wrong");
  return "Q1";
});

await check("picking an option colors it and advances", async () => {
  appEl.querySelectorAll(".dp-option")[1].click();
  await sleep(60);
  assert(appEl.querySelectorAll(".dp-option")[1].classList.contains("picked"), "option must be picked before advancing");
  await sleep(340);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 2 题"), "did not advance to Q2");
  appEl.querySelector("#dp-prev").click();
  await sleep(50);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 1 题"), "上一题 failed");
  assert(appEl.querySelectorAll(".dp-option")[1].classList.contains("picked"), "returning must show the recorded pick");
  return "pick + back";
});

await check("a full 24-question run lands on a named result page", async () => {
  for (let i = 0; i < 24; i += 1) {
    const count = appEl.querySelector(".dp-q-count");
    assert(count, `question ${i + 1} missing`);
    appEl.querySelectorAll(".dp-option")[0].click();
    await sleep(340);
  }
  const name = appEl.querySelector(".dp-name");
  assert(name, "result name missing");
  assert(appEl.querySelector(".dp-name-en"), "english name missing");
  assert(appEl.querySelector(".dp-quote").textContent.trim().length > 2, "short quote missing");
  assert(appEl.querySelector(".dp-quote-source"), "quote source line missing");
  assert(appEl.querySelector(".dp-blurb").textContent.trim().length > 10, "two-sentence blurb missing");
  assert(appEl.querySelector("#dp-share"), "save button must sit before the fold content");
  assert(!appEl.querySelector(".dp-more"), "collapsed detail section must be gone");
  assert(!appEl.querySelector(".dp-disclaimer"), "result-page disclaimer must be gone (kept on cover/share)");
  for (const id of ["#dp-copy", "#dp-again", "#dp-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  return `角色：${name.textContent}`;
});

await check("result page carries the princess accent color and artwork slot", () => {
  const section = appEl.querySelector(".dp-result");
  assert(section.attributes.style && section.attributes.style.includes("--dp-accent"), "accent color not set on result");
  assert(appEl.querySelector(".dp-portrait"), "portrait slot missing");
  return "accent + portrait";
});

await check("share and copy actions work inside the skin", async () => {
  canvas.created = 0;
  appEl.querySelector("#dp-share").click();
  appEl.querySelector("#dp-copy").click();
  await sleep(60);
  const copy = appEl.querySelector("#dp-copy");
  assert(copy.textContent.includes("已复制"), `copy feedback wrong: ${copy.textContent}`);
  assert(canvas.created >= 1, "share must build a canvas image");
  return "share + copy";
});

await check("again restarts at Q1, exit returns to the cover", async () => {
  appEl.querySelector("#dp-again").click();
  await sleep(60);
  assert(appEl.querySelector(".dp-q-count").textContent.includes("第 1 题"), "再测一次 failed");
  appEl.querySelector("#dp-exit").click();
  await sleep(60);
  assert(appEl.querySelector(".dp-cover"), "回封面 failed");
  return "again + exit";
});

/* ------------------------------------------------------- 可达性 ---- */
check("all 13 princesses are reachable, not via tie-break", () => {
  const theme = DP_THEMES[0];
  assert(theme.results.length === 13, `expected 13 results, got ${theme.results.length}`);
  return reachableResults({ theme, selectWinner, seed: 424242, threshold: 0.8, strictMargin: 3 });
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped and does not touch other products", () => {
  assertScopedCss(skinCss, { foreignPrefixes: ["pp-", "ggw-"] });
  return "scoped, no cross-product selectors";
});

check("skin classes used by skin.js all exist in skin.css", () => {
  const js = readFileSync(join(DEPLOY, "themes", PRODUCT, "skin.js"), "utf8");
  return assertClassesCovered({ js, css: skinCss, prefix: SKIN_PREFIX, hooks: ["dp-top-right", "dp-option-text", "dp-q"] });
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(DEPLOY, "themes", PRODUCT, "skin.js"), "utf8");
  assertExpressionOnlySkin(js, ["disney_princess.json"]);
  return "expression only";
});

check("every princess carries a quote and a blurb, sources honest", () => {
  const theme = DP_THEMES[0];
  assert(theme.results.length === 13, "13 results");
  for (const r of theme.results) {
    assert(r.quote && r.quote.text, `${r.id} quote missing`);
    assert(r.quote.source_short, `${r.id} quote source missing`);
    if (r.quote.kind === "film") {
      assert(r.quote.original && r.quote.scene, `${r.id} film quote needs original + scene`);
    } else {
      assert(r.quote.kind === "original", `${r.id} quote kind must be film|original`);
      assert(r.quote.source_short.includes("原创"), `${r.id} original quote must be labelled 原创`);
    }
    assert(r.blurb && r.blurb.length >= 20 && r.blurb.length <= 90, `${r.id} blurb length off: ${r.blurb && r.blurb.length}`);
  }
  const distinct = new Set(theme.results.map((r) => r.blurb.slice(0, 6)));
  assert(distinct.size >= 12, "blurbs must not share one opening formula");
  return "13 quotes + 13 blurbs, film quotes carry original + scene";
});

check("the content file is this product's own private matrix", () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", PRODUCT, "product.json"), "utf8"));
  assert(manifest.content_file === "../../disney_princess.json", "must own its private content file");
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "disney_princess.json"), "utf8"));
  assert(raw.themes.length === 1 && raw.themes[0].id === PRODUCT, "private file must hold only this theme");
  assert(raw.themes[0].questions.length === 24, "24 questions");
  assert(!appSource.includes("dp-"), "default templates must not reference dp- classes");
  return "own matrix, own file";
});

unbootSkinApp();
report();

