});

check("the content file is this product's own private matrix", () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", "weather-station", "product.json"), "utf8"));
  assert(manifest.name === "情绪气象台：你的内心天气观测报告", "product name must be weather-station");
  assert(manifest.content_file === "../../weather_station.json", "must own its private content file");
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "weather_station.json"), "utf8"));
  assert(raw.themes.length === 1 && raw.themes[0].id === "weather-station", "private file must hold only this theme");
  assert(raw.themes[0].questions.length === 14, "14 questions");
  assert(raw.themes[0].results.length === 7, "7 results");
  assert(!appSource.includes("wx-"), "default templates must not reference wx- classes");
  return "own matrix, own file";
});

delete globalThis.__MYTHIC_SKINS__;

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n情绪气象台皮肤 · 流程测试\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
