// API 桩 — 与 server/server.mjs 的四个前端可见端点同语义。
//
// 覆盖：/api/redeem、/api/verify-license、/api/content、/api/score。
// 评分不是桩的：/api/score 调真实 server/scoring.mjs 的 selectWinner，
// 和线上服务器一样只回 winnerId + 完整结果对象。
//
// 响应形状必须跟随 server.mjs；server 改接口，先改这里。
import { selectWinner } from "../../server/scoring.mjs";
import { sanitizeTheme } from "../../server/sanitize.mjs";

export function jsonResponse(status, body) {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}

export function installApiStub({ productId, productName, themes, code, secret }) {
  if (!productId || !productName || !themes || !code || !secret) {
    throw new Error("installApiStub: productId/productName/themes/code/secret 必填");
  }
  let activated = false;
  let lastScoredTheme = null;
  const norm = (c) => String(c || "").toUpperCase().replace(/[\s-]+/g, "");

  globalThis.fetch = async (url, options = {}) => {
    const body = options.body ? JSON.parse(options.body) : {};
    const path = String(url).split("?")[0];
    if (path === "/api/redeem") {
      if (norm(body.code) !== norm(code)) return jsonResponse(404, { ok: false, error: "invalid_code" });
      if (!activated) {
        activated = true;
        return jsonResponse(200, { ok: true, secret, firstUse: true, product_id: productId, product_name: productName });
      }
      if (body.secret === secret) return jsonResponse(200, { ok: true, secret, firstUse: false, product_id: productId, product_name: productName });
      return jsonResponse(403, { ok: false, error: "already_bound" });
    }
    if (path === "/api/verify-license") {
      if (norm(body.code) === norm(code) && body.secret === secret && activated) {
        return jsonResponse(200, { ok: true, product_id: productId, product_name: productName });
      }
      return jsonResponse(403, { ok: false, error: "already_bound" });
    }
    if (path === "/api/content") {
      // 与线上一致：服务端发货前做清洗。调用方传原始题库即可。
      return jsonResponse(200, { product: { product_id: productId, name: productName }, themes: themes.map(sanitizeTheme) });
    }
    if (path === "/api/score") {
      const theme = themes.find((t) => t.id === body.theme);
      if (!theme) return jsonResponse(404, { ok: false, error: "invalid_theme" });
      if (norm(body.code) !== norm(code) || body.secret !== secret) return jsonResponse(403, { ok: false, error: "already_bound" });
      const { winnerId } = selectWinner(theme, body.answers);
      const result = theme.results.find((r) => r.id === winnerId);
      return jsonResponse(200, { ok: true, winnerId, result });
    }
    throw new Error(`unexpected fetch: ${url}`);
  };

  return {
    get activated() { return activated; },
    // 预置"已激活"状态（模拟二次进入）
    activate() { activated = true; },
  };
}

