}

/* --------------------------------------------- 挂载真实皮肤并启动 ---- */
const skinModule = await import(pathToFileURL(join(ROOT, "deploy-ready", "themes", "pride-prejudice", "skin.js")).href);
globalThis.__MYTHIC_SKINS__ = { "pride-prejudice": skinModule.default };

const appSource = readFileSync(join(ROOT, "deploy-ready", "app.js"), "utf8");
new Function("module", "exports", appSource)({ exports: {} }, {});
await sleep(80);

const skinCss = readFileSync(join(ROOT, "deploy-ready", "themes", "pride-prejudice", "skin.css"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the P.P. R.S.V.P. skin, not the default gate", () => {
  assert(appEl.querySelector(".pp-display"), "PP gate title missing");
  assert(appEl.querySelector(".pp-display").textContent.includes("呈递回执"), "gate title copy wrong");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
  assert(!appEl.querySelector(".ggw-gate-title"), "garden gate leaked into PP flow");
  assert(bodyEl.attributes["data-skin"] === "pride-prejudice", "body data-skin not set");
  assert(globalThis.document.title.includes("傲慢与偏见"), "skin title not adopted");
  return "R.S.V.P.";
});

await check("a valid code unlocks the invitation cover", async () => {
  const input = appEl.querySelector("#pp-gate-code");
  const submit = appEl.querySelector("#pp-gate-submit");
  assert(input && submit, "gate form missing");
  input.value = CODE.toLowerCase();
  submit.click();
  await sleep(120);
  assert(appEl.querySelector(".pp-invite-title"), "invitation cover missing after redeem");
  assert(appEl.querySelector(".pp-invite-title").textContent.includes("傲慢与偏见"), "cover title wrong");
  assert(appEl.querySelector("#pp-accept"), "accept button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
  return "invitation";
});

await check("accepting starts at occasion I with 18 ledger marks and 3 replies", async () => {
  appEl.querySelector("#pp-accept").click();
  await sleep(80);
  assert(appEl.querySelector(".pp-q-kicker").textContent.includes("Occasion I of XVIII"), `expected occasion I, got ${appEl.querySelector(".pp-q-kicker")?.textContent}`);
  assert(appEl.querySelectorAll(".pp-mark").length === 18, "ledger must show 18 occasions");
  assert(appEl.querySelectorAll(".pp-reply").length === 3, "three replies expected");
  assert(appEl.querySelector(".pp-top").textContent.includes("第 I 场"), `topbar numbering wrong: ${appEl.querySelector(".pp-top").textContent}`);
  return "occasion I";
});

await check("inking a reply advances after the ink beat, previous walks back", async () => {
  appEl.querySelectorAll(".pp-reply")[1].click();
  await sleep(50);
  const inked = appEl.querySelectorAll(".pp-reply")[1];
  assert(inked.classList.contains("inked"), "reply must be inked before advancing");
  await sleep(400);
  assert(appEl.querySelector(".pp-q-kicker").textContent.includes("Occasion II"), "did not advance to occasion II");
  appEl.querySelector("#pp-prev").click();
  await sleep(50);
  assert(appEl.querySelector(".pp-q-kicker").textContent.includes("Occasion I"), "回看上一场 failed");
  assert(appEl.querySelectorAll(".pp-reply")[1].classList.contains("inked"), "returning must show the recorded ink");
  return "ink + back";
});

await check("a full 18-occasion run lands on the calling card page", async () => {
  for (let i = 0; i < 18; i += 1) {
    const kicker = appEl.querySelector(".pp-q-kicker");
    assert(kicker, `occasion ${i + 1} missing`);
    appEl.querySelectorAll(".pp-reply")[0].click();
    await sleep(400);
  }
  const name = appEl.querySelector(".pp-card-name");
  assert(name, "calling card name missing");
  assert(appEl.querySelector(".pp-card"), "calling card frame missing");
  assert(appEl.querySelector(".pp-letter"), "private letter missing");
  assert(appEl.querySelector(".pp-vignette svg"), "vignette missing");
  assert(appEl.querySelector(".pp-verse").textContent.trim().length > 0, "verse empty");
  assert(appEl.querySelector(".pp-reading").textContent.length > 50, "reading missing");
  for (const id of ["#pp-copy", "#pp-share", "#pp-again", "#pp-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  assert(appEl.querySelector(".pp-disclaimer"), "disclaimer missing");
  return `名帖：${name.textContent}`;
});

await check("share and copy actions work inside the skin", async () => {
  appEl.querySelector("#pp-share").click();
  appEl.querySelector("#pp-copy").click();
  await sleep(60);
  const copy = appEl.querySelector("#pp-copy");
  assert(copy.textContent.includes("已抄录"), `copy feedback wrong: ${copy.textContent}`);
  return "share + copy";
});

await check("again returns to occasion I, exit returns to the invitation", async () => {
  appEl.querySelector("#pp-again").click();
  await sleep(60);
  assert(appEl.querySelector(".pp-q-kicker").textContent.includes("Occasion I"), "再赴一场 failed");
  appEl.querySelector("#pp-exit").click();
  await sleep(60);
  assert(appEl.querySelector(".pp-invite-title"), "告辞 failed");
  return "again + exit";
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped to body[data-skin]", () => {
  const stripped = skinCss.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") && opens === 1) {
      if (!/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  assert(depth === 0, "unbalanced braces in skin.css");
  return "every selector carries the scope prefix";
});

check("skin classes used by skin.js all exist in skin.css", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "pride-prejudice", "skin.js"), "utf8");
  const used = new Set(
    [...js.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/))
      .flatMap((c) => c.match(/pp-[a-z0-9-]+/g) || [])
  );
  const hooks = new Set(["pp-top-right", "pp-q"]);
  const defined = new Set([...skinCss.matchAll(/\.(pp-[a-z0-9-]+)/g)].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c) && !hooks.has(c));
  assert(missing.length === 0, `classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
});

