  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "pride-prejudice", "skin.js"), "utf8");
  for (const banned of ["scores", "normalization_bounds", "selectWinner", "quiz_content_upgrade", "fetch("]) {
    assert(!js.includes(banned), `skin must not contain ${banned}`);
  }
  return "expression only";
});

check("greek and garden skins are untouched by this product", () => {
  assert(!appSource.includes("pp-"), "default templates must not reference PP classes");
  const gardenCss = readFileSync(join(ROOT, "deploy-ready", "themes", "grand-view-garden", "skin.css"), "utf8");
  assert(!gardenCss.includes("pp-"), "garden skin must not reference PP classes");
  const gardenJs = readFileSync(join(ROOT, "deploy-ready", "themes", "grand-view-garden", "skin.js"), "utf8");
  assert(!gardenJs.includes("pride-prejudice"), "garden skin must not reference PP");
  return "isolated";
});

delete globalThis.__MYTHIC_SKINS__;

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n傲慢与偏见皮肤 · 流程测试\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
process.exit(failures.length ? 1 : 0);

