check("skin.css is fully scoped and does not touch other products", () => {
  const stripped = skinCss.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") && opens === 1) {
      if (!/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  assert(depth === 0, "unbalanced braces in skin.css");
  for (const foreign of ["lw-", "gg-", "wx-", "pp-", "dp-", "cat-"]) {
    assert(!skinCss.includes(foreign), `skin.css must not reference ${foreign} (cross-product leak)`);
  }
  return "scoped, no cross-product selectors";
});

check("skin classes used by skin.js all exist in skin.css", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "cuteanimal", "skin.js"), "utf8");
  const used = new Set(
    [...js.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/))
      .flatMap((c) => c.match(/ca-[a-z0-9-]+/g) || [])
  );
  const hooks = new Set(["ca-top-right", "ca-option-text", "ca-q"]);
  const defined = new Set([...skinCss.matchAll(/\.(ca-[a-z0-9-]+)/g)].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c) && !hooks.has(c));
  assert(missing.length === 0, `classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "cuteanimal", "skin.js"), "utf8");
  for (const banned of ["normalization_bounds", "selectWinner", "quiz_content_upgrade", "cuteanimal.json", "fetch("]) {
    assert(!js.includes(banned), `skin must not contain ${banned}`);
  }
  return "expression only";
});

check("the content file is this product's own private matrix", () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", "cuteanimal", "product.json"), "utf8"));
  assert(manifest.name === "测测更像是哪种可爱动物", "product name must be cuteanimal");
  assert(manifest.content_file === "../../cuteanimal.json", "must own its private content file");
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "cuteanimal.json"), "utf8"));
  assert(raw.themes.length === 1 && raw.themes[0].id === "cuteanimal", "private file must hold only this theme");
  assert(raw.themes[0].questions.length === 16, "16 questions");
  assert(raw.themes[0].results.length === 8, "8 results");
  assert(!appSource.includes("ca-"), "default templates must not reference ca- classes");
  return "own matrix, own file";
});

delete globalThis.__MYTHIC_SKINS__;

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n可爱动物图鉴皮肤 · 流程测试\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
process.exit(failures.length ? 1 : 0);

