* { box-sizing: border-box; }
body {
  margin: 0;
  min-width: 320px;
  color: var(--text);
  background: var(--bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  transition: background-color .3s ease, color .3s ease;
}

body[data-theme] {
  color: var(--text);
  background-color: var(--bg);
  background-image: none;
}

body[data-theme="liaozhai-women"] {
  color: #F4F0E6 !important;
  background-color: #102C2C !important;
}

body[data-theme="urban-relations"],
body[data-theme="eileen-chang-city"] {
  color: #F8EDE5 !important;
  background-color: #27212A !important;
}

button { font: inherit; }
.shell { width: min(100%, 680px); min-height: 100vh; margin: auto; padding: 22px 18px 42px; }
.topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 28px; color: var(--muted); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; }
.brand { color: var(--ink); font-weight: 700; }
.hero { padding: 28px 2px 18px; }
.eyebrow { color: var(--accent); font-size: 12px; letter-spacing: .18em; text-transform: uppercase; }
h1 { margin: 10px 0 12px; font-family: Georgia, "Songti SC", serif; font-size: clamp(38px, 11vw, 72px); line-height: .98; letter-spacing: -.05em; }
h2 { margin: 0 0 10px; font-family: Georgia, "Songti SC", serif; font-size: 30px; }
.lead { max-width: 520px; color: var(--muted); line-height: 1.7; }
.grid { display: grid; gap: 12px; margin-top: 26px; }
.theme-card, .option, .result-panel { border: 1px solid var(--line); border-radius: 16px; background: var(--surface); box-shadow: 0 4px 16px rgba(0,0,0,.07); opacity: 0.95; }
.theme-card { position: relative; overflow: hidden; min-height: 174px; padding: 22px; text-align: left; color: var(--text); cursor: pointer; }
.theme-card::after { content: ""; position: absolute; width: 80px; height: 80px; right: 12px; bottom: 12px; border: 1px solid var(--accent); opacity: 0.12; border-radius: 8px; }
.theme-card:hover, .option:hover { border-color: var(--accent); transform: translateY(-1px); opacity: 1; }
.option.selected { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, var(--surface)); }
.option.selected b { background: var(--accent); color: var(--surface); }
.theme-card, .option { transition: transform .2s ease, border-color .2s ease; }
.theme-card h3 { margin: 8px 0; font-family: Georgia, serif; font-size: 24px; }
.theme-card p { max-width: 82%; margin: 0; color: var(--muted); line-height: 1.55; }
.theme-card .count { position: absolute; top: 22px; right: 22px; color: var(--accent); font-size: 12px; }
.theme-card { transition: transform .2s ease, border-color .2s ease; }
.notice { margin-top: 22px; color: #9f96a8; font-size: 12px; line-height: 1.6; }
.progress { height: 4px; margin: 12px 0 28px; overflow: hidden; border-radius: 9px; background: color-mix(in srgb, var(--muted) 20%, transparent); }
.progress i { display: block; height: 100%; border-radius: inherit; background: var(--accent); transition: width .25s ease; }
.question-number { color: var(--accent); font-size: 13px; letter-spacing: .12em; }
.question { margin: 12px 0 24px; font-family: Georgia, "Songti SC", serif; font-size: 29px; line-height: 1.3; }
.options { display: grid; gap: 12px; }
