#!/usr/bin/env node
// p3-shots.mjs — Chrome headless CDP 驱动，为默认模板截全流程页面图。
// 用法: node tools/p3-shots.mjs <outdir> <code>
// 依赖: 本地 server(8917) + Chrome headless(--remote-debugging-port=9223)。零 npm 依赖（Node 22 WebSocket）。
import { writeFileSync } from "node:fs";
import { join } from "node:path";

const OUT = process.argv[2];
const CODE = process.argv[3];
const BASE = "http://127.0.0.1:8917";
const CDP_HTTP = "http://127.0.0.1:9223";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- minimal CDP client ----
async function getPageWs() {
  for (let i = 0; i < 30; i += 1) {
    try {
      const list = await (await fetch(`${CDP_HTTP}/json/list`)).json();
      const page = list.find((t) => t.type === "page" && !/devtools/.test(t.url));
      if (page) return page.webSocketDebuggerUrl;
    } catch { /* chrome not up yet */ }
    await sleep(300);
  }
  throw new Error("no CDP page target");
}

let seq = 0;
const pending = new Map();
function send(ws, method, params = {}) {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

const ws = new WebSocket(await getPageWs());
ws.onmessage = (evt) => {
  const msg = JSON.parse(evt.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(`${msg.error.message}`)) : resolve(msg.result);
  }
};
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

async function evaluate(expression) {
  const r = await send(ws, "Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || "evaluate failed");
  return r.result.value;
}
async function shot(name) {
  await sleep(350);
  const r = await send(ws, "Page.captureScreenshot", { format: "png" });
  writeFileSync(join(OUT, name), Buffer.from(r.data, "base64"));
  console.log(`  + ${name}`);
}
async function navigate(url) {
  await send(ws, "Page.navigate", { url });
  // 轮询 readyState，别用固定长睡
  for (let i = 0; i < 40; i += 1) {
    await sleep(250);
    try { if (await evaluate("document.readyState") === "complete") break; } catch { /* navigating */ }
  }
  await sleep(600);
}

await send(ws, "Page.enable");
await send(ws, "Emulation.setDeviceMetricsOverride", { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });

console.log("gate:");
await navigate(`${BASE}/t/jane-eyre`);
await shot("01-gate.png");

console.log("activate + cover:");
const redeem = JSON.parse(await evaluate(`(async () => {
  const res = await fetch('/api/redeem', { method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ code: ${JSON.stringify(CODE)}, fingerprint: 'p3-shots' }) });
  return res.text();
})()`));
if (!redeem.ok) throw new Error(`redeem failed: ${JSON.stringify(redeem)}`);
await evaluate(`localStorage.setItem('mythic.license.v1', JSON.stringify({ code: ${JSON.stringify(CODE)}, secret: ${JSON.stringify(redeem.secret)} }))`);
await navigate(`${BASE}/t/jane-eyre`);
await shot("02-cover.png");

console.log("question:");
await evaluate(`document.querySelector('#cover-start').click()`);
await sleep(500);
await shot("03-question.png");

console.log("answering 18 questions…");
for (let i = 0; i < 18; i += 1) {
  await evaluate(`document.querySelectorAll('.option')[${i % 3}].click()`);
  await sleep(220);
  await evaluate(`document.querySelector('#next').click()`);
  await sleep(320);
}
console.log("result:");
for (let i = 0; i < 20; i += 1) {
  if (await evaluate(`!!document.querySelector('.result-card')`)) break;
  await sleep(400);
}
await sleep(900); // 等落卡动画结束
await shot("04-result-front.png");
await evaluate(`document.querySelector('.flip-card').click()`);
await sleep(1000);
await shot("05-result-back.png");

ws.close();
console.log("done.");

