.theme-card { position: relative; overflow: hidden; min-height: 174px; padding: 22px; text-align: left; color: var(--text); cursor: pointer; }
.theme-card::after { content: ""; position: absolute; width: 80px; height: 80px; right: 12px; bottom: 12px; border: 1px solid var(--accent); opacity: 0.12; border-radius: 8px; }
