.option.selected { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, var(--surface)); box-shadow: 0 0 0 1px var(--accent) inset; }
.option.selected b { background: var(--accent); border-color: var(--accent); color: var(--surface); }
.theme-card, .option { transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease, background-color .18s ease; }
