.progress i { display: block; height: 100%; border-radius: inherit; background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 72%, var(--accent-2)), var(--accent)); transition: width .3s cubic-bezier(.2,.7,.2,1); }
.question-number { color: var(--accent); font-size: 12px; font-weight: 600; letter-spacing: .18em; }
