.art-card { width: 150px; height: 92px; left: 17%; top: 46px; padding: 18px; border: 1px solid #a46c62; background: #fff6e9; color: #884c4d; font: 22px/1.3 Georgia, serif; transform: rotate(-7deg); }
.art-fruit { width: 66px; height: 66px; right: 18%; bottom: 28px; border-radius: 50%; background: #a64e4d; box-shadow: inset 12px 8px 0 rgba(255,255,255,.16); }
.art-shadow { width: 190px; height: 20px; right: 10%; bottom: 23px; border-radius: 50%; background: rgba(85,48,47,.18); transform: rotate(-8deg); }
