.art-door { width: 155px; height: 190px; left: 29%; bottom: 0; border: 10px solid #536956; border-bottom: 0; background: #f4ead6; }
.art-cup { width: 34px; height: 30px; bottom: 25px; border: 3px solid #536956; border-radius: 0 0 12px 12px; background: #f4ead6; }
