.art-path { width: 190px; height: 5px; left: 34%; bottom: 30px; background: #c7a86b; transform-origin: left; }
.art-path-one { transform: rotate(-30deg); }.art-path-two { transform: rotate(-2deg); }.art-path-three { transform: rotate(27deg); }
.art-lamp { width: 30px; height: 42px; left: 42%; bottom: 54px; border: 3px solid #e6c778; border-radius: 45% 45% 35% 35%; box-shadow: 0 0 34px 16px rgba(230,199,120,.3); }
