.art-sprout::before, .art-sprout::after { position: absolute; width: 26px; height: 14px; border-radius: 100% 0; background: #7d9862; content: ""; }
.art-sprout::before { left: -20px; top: 20px; transform: rotate(-25deg); }.art-sprout::after { left: 1px; top: 4px; transform: rotate(25deg); }
