.art-bowl-one { left: 18%; }.art-bowl-two { left: 42%; }
.art-list { width: 82px; height: 115px; right: 12%; top: 30px; border: 1px solid #956b48; background: repeating-linear-gradient(#fff5d9 0 20px, #d5ba83 21px 22px); transform: rotate(8deg); }
.result-medea .visual-art { background: #40302e; }
.art-contract { width: 200px; height: 118px; left: 12%; top: 34px; border: 2px solid #d0a663; background: #e8d2a3; transform: rotate(-8deg); }
.art-seam { width: 3px; height: 145px; left: 49%; top: 21px; background: #754447; transform: rotate(17deg); }
.art-folder { width: 105px; height: 76px; right: 10%; bottom: 25px; border: 3px solid #d0a663; background: #614548; transform: rotate(7deg); }
.result-atalanta .visual-art { background: #c9d7dc; }
.art-road { width: 280px; height: 210px; left: 20%; bottom: -135px; border-radius: 50%; border: 18px solid #b45e4d; transform: rotate(-12deg); }
.art-bib { left: 14%; top: 28px; padding: 13px 17px; background: #f3e1b0; color: #a94e40; font: 700 27px Georgia, serif; transform: rotate(12deg); }
.art-sign { right: 14%; top: 52px; color: #536b78; font-size: 58px; transform: rotate(-12deg); }
.result-symbol { display: grid; width: 88px; height: 88px; margin-bottom: 18px; place-items: center; border: 2px solid var(--accent); border-radius: 12px; color: var(--accent); font-family: Georgia, serif; font-size: 32px; }
.result-type { color: var(--accent); letter-spacing: .08em; font-size: 13px; }
.result-copy { color: var(--text); line-height: 1.8; font-size: 15px; }
.tags { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0; }
.tag { padding: 7px 11px; border: 1px solid var(--line); border-radius: 99px; color: var(--muted); font-size: 12px; }
.quote { margin: 22px 0; padding: 17px; border-left: 2px solid var(--accent); color: var(--text); line-height: 1.7; }
.visual-note { margin: 20px 0 0; padding-top: 14px; border-top: 1px solid color-mix(in srgb, var(--line) 45%, transparent); color: var(--muted); font-size: 13px; line-height: 1.6; }
.visual-note span { display: block; margin-bottom: 4px; color: var(--accent); font-size: 11px; letter-spacing: .14em; text-transform: uppercase; }
.mythic-trace { margin-top: 18px; border-top: 1px solid color-mix(in srgb, var(--line) 45%, transparent); color: var(--muted); font-size: 13px; line-height: 1.7; }
.mythic-trace summary { padding-top: 14px; color: var(--accent); cursor: pointer; }
.mythic-trace p { margin: 8px 0 0; }
.result-disclaimer { margin: 12px 2px 0; }
.actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-top: 20px; }
.primary, .secondary { border-radius: 99px; padding: 13px 20px; cursor: pointer; transition: transform .15s ease, box-shadow .18s ease, border-color .18s ease, background-color .18s ease; }
.primary { display: inline-block; border: 0; background: linear-gradient(145deg, color-mix(in srgb, var(--accent) 88%, #ffffff), var(--accent)); color: #271b16; font-weight: 700; letter-spacing: .02em; box-shadow: 0 2px 6px color-mix(in srgb, var(--accent) 30%, transparent), 0 8px 20px color-mix(in srgb, var(--accent) 22%, transparent); }
.primary:hover { transform: translateY(-1px); box-shadow: 0 3px 8px color-mix(in srgb, var(--accent) 34%, transparent), 0 12px 26px color-mix(in srgb, var(--accent) 26%, transparent); }
.primary:active { transform: translateY(0) scale(.98); box-shadow: 0 1px 4px color-mix(in srgb, var(--accent) 28%, transparent); }
.primary:disabled { background: var(--accent); opacity: .38; box-shadow: none; }
.secondary { border: 1px solid color-mix(in srgb, var(--line) 45%, transparent); background: transparent; color: var(--text); }
.secondary:hover { border-color: var(--accent); color: var(--accent); }
.small { color: var(--muted); font-size: 12px; line-height: 1.6; }
.actions .back { width: 100%; margin-top: 4px; padding: 0; text-align: left; }
@media (min-width: 600px) { .grid { grid-template-columns: repeat(3, 1fr); } .theme-card { min-height: 250px; } .theme-card p { max-width: 100%; } }

/* Reusable result-card treatment */
.result-card { overflow: hidden; padding: 18px; border-color: color-mix(in srgb, var(--accent) 42%, var(--line)); box-shadow: 0 14px 34px rgba(38, 43, 35, .10); }
.result-card .visual-art { margin: -18px -18px 22px; height: 188px; }
.result-heading-copy { min-width: 0; }
.result-type { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; margin-bottom: 5px; }
.result-type > span:first-child { color: var(--accent); font-size: 12px; font-weight: 700; letter-spacing: .12em; }
.result-name-en { color: var(--muted); font-size: 12px; letter-spacing: .04em; }
.result-heading h2 { font-size: clamp(30px, 8vw, 42px); letter-spacing: -.04em; }
.result-subtitle { max-width: 38em; margin-top: 7px; color: var(--text); font-size: 15px; line-height: 1.55; }
.result-reading { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 6; margin: 20px 0 0; }
.result-card .tags { margin: 17px 0 0; }
.result-card .quote { margin: 20px 0 0; background: color-mix(in srgb, var(--accent) 5%, transparent); }
.visual-art-fallback { display: grid; place-items: center; background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 20%, var(--surface)), var(--surface)); }
.visual-art-fallback span { position: static; color: var(--accent); font: 700 68px Georgia, serif; opacity: .65; }
.visual-art-fallback-hera { background: linear-gradient(135deg, #ead7cf, #fff6ed); }
.visual-art-fallback-hestia { background: linear-gradient(135deg, #eadfc7, #fffaf0); }
.visual-art-fallback-nike { background: linear-gradient(135deg, #d9e4e6, #f8f2dd); }
.visual-art-fallback-circe { background: linear-gradient(135deg, #d9d2df, #f5eadb); }
.mythic-trace { margin-top: 20px; }

/* 双面结果卡 —— 严格照 `hecate-flip-card.html` / `athena-double-card-test-v2.html`：
   · 正反面各自独立 rotateY，父容器不旋转（否则背面文字会镜像）；
   · .card 需要 min-height 撑住高度，因为两个面都是 position:absolute；
   · 每面只有「艺术图 4:5 + 姓名 + 一行标题 + 一段正文」；
   · 整张卡点击翻面，支持 Enter / 空格。
   正面正面图 assets/<theme>/<id>-front.png，背面 <id>-back.png。
   任何一面缺图只影响那一面，会退回符号化美术（.visual-art），不会破图。 */
.result-hero .scene { perspective: 1400px; }
.flip-card {
  position: relative;
  min-height: 720px;
  overflow: visible;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  cursor: pointer;
}
.flip-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

.flip-card .face {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border: 2px solid #cfc4b8;
  border-radius: 16px;
  background: var(--surface);
  box-shadow: 0 18px 36px rgba(85, 72, 59, .15);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  transform: rotateY(0deg);
  transition: transform .7s cubic-bezier(.2, .7, .2, 1), opacity .22s ease;
}
.flip-card .front { position: relative; }
.flip-card .back {
  transform: rotateY(180deg);
  background: #17243B;
  color: #efe6d7;
  border-color: #60708c;
  box-shadow: 0 22px 28px rgba(0, 0, 0, .53);
}
.flip-card.is-back .front { transform: rotateY(-180deg); pointer-events: none; }
.flip-card.is-back .back { transform: rotateY(0deg); pointer-events: auto; }

/* 4:5 艺术图区 */
.flip-card .art {
  position: relative;
  aspect-ratio: 4 / 5;
  overflow: hidden;
  background: #eee4d6;
  border-bottom: 1px solid #cfc4b8;
}
.flip-card .back .art { background: #8c493d; border-color: #60708c; }
.flip-card .art img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: center center; }
.flip-card .back .art img { filter: saturate(.9) contrast(1.04); }

.flip-fallback { position: absolute; inset: 0; }
.flip-fallback[hidden] { display: none; }
.flip-fallback .visual-art { height: 100%; margin: 0; }

.flip-card .body { padding: 18px 22px 16px; }
.flip-card .eyebrow { display: flex; align-items: baseline; gap: 9px; color: var(--ink); font: 600 25px/1.15 Georgia, serif; }
.flip-card .eyebrow small { color: #344A68; font: 400 15px/1 Georgia, serif; letter-spacing: .04em; }
.flip-card .back .eyebrow, .flip-card .back .eyebrow small { color: #c5a36b; }

.flip-card h2 { margin: 11px 0 9px; color: #a85d48; font: 500 16px/1.35 system-ui, sans-serif; }
.flip-card .back h2 { color: #c98b72; }

.flip-card .reading { margin: 0; color: #514940; font-size: 14px; line-height: 1.7; -webkit-line-clamp: none; display: block; overflow: visible; }
.flip-card .back .reading { color: #e0d5c6; }

/* 缺图：符号化美术接管这一面的图区 */
.flip-card .face.art-missing .art { background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 22%, var(--surface)), var(--surface)); }

/* 减少运动偏好：prefers-reduced-motion 的语义是「不要位移/缩放/旋转」，
   而不是「取消一切状态变化的可见反馈」。所以这里保留一次不位移的交叉淡入，
   而不是硬切 —— 否则在关闭了系统动画的机器上（Windows MinAnimate=0）
   翻面看起来像「没反应」。 */
@media (prefers-reduced-motion: reduce) {
  .flip-card .face {
    transition: transform 0s linear, opacity .22s ease;
  }
  .flip-card .front { opacity: 1; }
  .flip-card.is-back .front { opacity: 0; }
  .flip-card .back { opacity: 0; }
  .flip-card.is-back .back { opacity: 1; }
}

/* ------------------------------------------------------------- 封面页 ----
   一个测试一个网址：单主题产品的入口页，只有标题、引言和开始按钮。 */
.cover-hero { max-width: 460px; }
.cover-actions { margin: 30px 0 4px; }
.cover-actions .primary { padding: 14px 38px; font-size: 15px; }

/* ------------------------------------------------------------- 兑换码门 ----
   激活页与结果加载态，沿用现有 hero/notice 语言，不引入新视觉体系。 */
.gate-hero { max-width: 420px; }
.gate-form { display: flex; gap: 10px; margin: 24px 0 6px; }
.gate-input {
  flex: 1; min-width: 0; padding: 13px 15px;
  border: 1px solid color-mix(in srgb, var(--line) 45%, transparent); border-radius: 14px;
  background: var(--surface); color: var(--ink);
  font: 600 15px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .06em; text-transform: uppercase;
  transition: border-color .18s ease, box-shadow .18s ease;
}
.gate-input:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent); }
.gate-error { min-height: 20px; margin: 6px 0 0; color: #a04b3c; font-size: 13px; }
.result-loading { padding: 40px 0 30px; }

@media (max-width: 420px) {
  .flip-card { min-height: 660px; }
  .flip-card .body { padding: 16px; }
  .flip-card .eyebrow { font-size: 22px; }
  .result-card { padding: 16px; }
  .result-card .visual-art { margin: -16px -16px 20px; height: 164px; }
  .result-reading { -webkit-line-clamp: 7; }
}

/* ============================================================ 卡片微交互（V2 CARD_MOTION）====
   卡是物理收藏品，不是 UI 面板：落卡（入场）、倾角（悬停）、探视（邀请翻面）、
   升力（翻面）、按压（active）。邀请最多两次，之后永远安静 —— 动效只负责
   教会「翻面」这一件事。所有动作只用 transform / opacity / box-shadow，
   不触发 layout；flavor 挂在既有的 result-<id> 类上。                          */

/* 落卡：结果渲染时，卡片像被放到桌面上 */
@keyframes card-arrive {
  0% { transform: translateY(16px) rotateX(6deg); opacity: 0; }
  100% { transform: translateY(0) rotateX(0); opacity: 1; }
}
.flip-card.card-arrive { animation: card-arrive .52s cubic-bezier(.2,.7,.2,1) both; will-change: transform; }

/* 探视一（3 秒无触碰）：向左轻侧 8°，像有人掀卡角示意还有另一面 */
@keyframes card-peek-1 {
  0% { transform: rotateY(0) rotateZ(0); }
  38% { transform: rotateY(-8deg) rotateZ(.35deg); }
  58% { transform: rotateY(-6deg) rotateZ(-.2deg); }
  100% { transform: rotateY(0) rotateZ(0); }
}
.flip-card.card-peek-1 { animation: card-peek-1 1.15s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }

/* 探视二（7.5 秒仍无触碰）：幅度更大并轻微离桌，然后就此打住 */
@keyframes card-peek-2 {
  0% { transform: rotateY(0) rotateZ(0) translateY(0); }
  40% { transform: rotateY(-12deg) rotateZ(-.5deg) translateY(-5px); }
  62% { transform: rotateY(-9.5deg) rotateZ(.3deg) translateY(-4px); }
  100% { transform: rotateY(0) rotateZ(0) translateY(0); }
}
.flip-card.card-peek-2 { animation: card-peek-2 1.3s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }

/* 升力：翻面瞬间卡片离桌一点再落回，与 0.7s 面旋转同步 */
@keyframes card-flip-lift {
  0% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-10px) scale(1.012); }
  100% { transform: translateY(0) scale(1); }
}
.flip-card.is-flipping { animation: card-flip-lift .7s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }

/* 悬停倾角与按压：物体被手触碰时的物理反馈 */
.flip-card { transition: transform .18s ease; }
@media (hover:hover) and (pointer:fine) {
  .flip-card:not(.is-back):hover { transform: rotateX(1deg) rotateY(-2deg); }
  .flip-card.is-back:hover { transform: rotateX(1deg) rotateY(2deg); }
}
.flip-card:active { transform: scale(.985); }

/* ---- 每位一缕风（flavor）----
   Hestia 火光：影染炭橙，探视放慢，像炉火的节拍；       */
.result-hestia.flip-card .front { box-shadow: 0 18px 36px rgba(150,74,20,.24); }
.result-hestia.flip-card .back { box-shadow: 0 22px 30px rgba(66,30,8,.5); }
.result-hestia.card-peek-1 { animation-duration: 1.45s; }
.result-hestia.card-peek-2 { animation-duration: 1.6s; }
/* Nike 风息：悬停倾角更大、探视更轻快，像翼下有风； */
@media (hover:hover) and (pointer:fine) {
  .result-nike.flip-card:not(.is-back):hover { transform: rotateX(1.2deg) rotateY(-3.2deg); }
}
.result-nike.card-peek-1 { animation-duration: .95s; }
.result-nike.card-peek-2 { animation-duration: 1.05s; }
/* Hera 凝视：不旋转，缓缓向你压近一寸，影染钴青。 */
@keyframes card-gaze {
  0% { transform: scale(1); }
  45% { transform: scale(1.02); }
  100% { transform: scale(1); }
}
.result-hera.card-peek-1 { animation-name: card-gaze; animation-duration: 1.7s; }
.result-hera.card-peek-2 { animation-name: card-gaze; animation-duration: 2s; }
.result-hera.flip-card .front { box-shadow: 0 18px 36px rgba(34,48,74,.26); }
.result-hera.flip-card .back { box-shadow: 0 22px 30px rgba(10,16,32,.55); }
/* Athena 冷静：影偏冷灰，标准节拍 */
.result-athena.flip-card .front { box-shadow: 0 18px 36px rgba(52,62,80,.22); }
/* Aphrodite 温柔：影染玫瑰，探视放缓 */
.result-aphrodite.flip-card .front { box-shadow: 0 18px 36px rgba(148,74,96,.22); }
.result-aphrodite.card-peek-1 { animation-duration: 1.4s; }
.result-aphrodite.card-peek-2 { animation-duration: 1.55s; }
/* Artemis 警觉：影染橄榄，探视轻快 */
.result-artemis.flip-card .front { box-shadow: 0 18px 36px rgba(74,90,58,.22); }
.result-artemis.card-peek-1 { animation-duration: 1.05s; }
.result-artemis.card-peek-2 { animation-duration: 1.15s; }
/* Hecate 夜行：影最深，探视最慢（夜的节拍） */
.result-hecate.flip-card .front { box-shadow: 0 18px 36px rgba(16,22,40,.34); }
.result-hecate.card-peek-1 { animation-duration: 1.5s; }
.result-hecate.card-peek-2 { animation-duration: 1.65s; }
/* Persephone 两界：影染酒色，中速 */
.result-persephone.flip-card .front { box-shadow: 0 18px 36px rgba(90,42,66,.24); }
/* Demeter 沉稳：影染赭金，慢而稳 */
.result-demeter.flip-card .front { box-shadow: 0 18px 36px rgba(140,96,36,.24); }
.result-demeter.card-peek-1 { animation-duration: 1.4s; }
.result-demeter.card-peek-2 { animation-duration: 1.5s; }
/* Medea 决断：影染深酒，探视利落 */
.result-medea.flip-card .front { box-shadow: 0 18px 36px rgba(64,24,38,.28); }
.result-medea.card-peek-1 { animation-duration: .9s; }
.result-medea.card-peek-2 { animation-duration: 1s; }
/* Atalanta 冲刺：全套最快 */
.result-atalanta.flip-card .front { box-shadow: 0 18px 36px rgba(96,104,50,.2); }
.result-atalanta.card-peek-1 { animation-duration: .85s; }
.result-atalanta.card-peek-2 { animation-duration: .95s; }
/* Circe 岛时：影染螺紫，慢 */
.result-circe.flip-card .front { box-shadow: 0 18px 36px rgba(78,48,92,.26); }
.result-circe.card-peek-1 { animation-duration: 1.5s; }
.result-circe.card-peek-2 { animation-duration: 1.65s; }

/* 减少运动：一切位移归零；翻面沿用上面的透明度交叉淡入，提示文案静态出现 */
@media (prefers-reduced-motion: reduce) {
  .flip-card { transition: none; }
  .flip-card.card-arrive,
  .flip-card.card-peek-1,
  .flip-card.card-peek-2,
  .flip-card.is-flipping { animation: none; }
}

