const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
import("node:fs").then(async ({ writeFileSync }) => {
  const list = await (await fetch("http://127.0.0.1:9224/json/list")).json();
  const page = list.find((t) => t.type === "page");
