// License store — node:sqlite (built into Node >= 22.5), zero external deps.
//
// Schema notes:
//   licenses.code          canonical plaintext code, PRIMARY KEY (the DB file is
//                          private infrastructure; keep it out of any web root)
//   licenses.device_hash   sha256(device secret). The secret itself exists only
//                          in the buyer's browser; the server never stores it.
//   licenses.fingerprint_hash  sha256 of the auxiliary client fingerprint. Only
//                          used to *count* mismatches — it never blocks access.
//
// Codes look like MYTHIC-AB2CD-EF7GH (10 chars from an unambiguous 31-char
// alphabet ~= 5e15 combinations; rate limiting makes online brute force inert).
import { randomBytes, createHash } from "node:crypto";
import { mkdirSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";

const ALPHABET = "23456789ABCDEFGHJKMNPQRSTUVWXYZ"; // no 0/O, 1/I/L look-alikes
const CODE_PREFIX = "MYTHIC";
const ADMIN_KEY_FILE = "admin-key.txt";

export function sha256(text) {
  return createHash("sha256").update(String(text)).digest("hex");
}

export function normalizeCode(input) {
  const compact = String(input || "").toUpperCase().replace(/[\s-]+/g, "");
  if (!/^[A-Z0-9]{6,40}$/.test(compact)) return null;
  return compact;
}

function randomCodeChunk(length) {
  const bytes = randomBytes(length);
  let out = "";
  for (let i = 0; i < length; i += 1) out += ALPHABET[bytes[i] % ALPHABET.length];
  return out;
}

export function generateCode() {
  return `${CODE_PREFIX}-${randomCodeChunk(5)}-${randomCodeChunk(5)}`;
}

export function newDeviceSecret() {
  return randomBytes(24).toString("base64url");
}

export function ensureAdminKey(dataDir) {
  const file = join(dataDir, ADMIN_KEY_FILE);
  const fromEnv = (process.env.MYTHIC_ADMIN_KEY || "").trim();
  if (fromEnv) return fromEnv;
  if (!existsSync(file)) {
    mkdirSync(dataDir, { recursive: true });
    writeFileSync(file, randomBytes(24).toString("hex") + "\n", { encoding: "utf8" });
    console.log(`[store] generated admin key -> ${file} (set MYTHIC_ADMIN_KEY to override)`);
  }
  return readFileSync(file, "utf8").trim();
}

export function openStore(dataDir) {
  mkdirSync(dataDir, { recursive: true });
  const db = new DatabaseSync(join(dataDir, "licenses.db"));
  db.exec("PRAGMA journal_mode = WAL;");
  db.exec("PRAGMA busy_timeout = 5000;");
  db.exec(`
    CREATE TABLE IF NOT EXISTS licenses (
      code              TEXT PRIMARY KEY,
      code_key          TEXT NOT NULL UNIQUE,
      product_id        TEXT NOT NULL DEFAULT 'greek_goddess',
      note              TEXT NOT NULL DEFAULT '',
      created_at        TEXT NOT NULL,
      activated         INTEGER NOT NULL DEFAULT 0,
      activated_at      TEXT,
      device_hash       TEXT,
      fingerprint_hash  TEXT,
      fp_mismatches     INTEGER NOT NULL DEFAULT 0,
      score_calls       INTEGER NOT NULL DEFAULT 0,
      last_seen_at      TEXT
    );
  `);
  // Existing databases predate the product column: backfill with the default so
  // every already-sold code keeps working with no manual migration.
  const columns = db.prepare("PRAGMA table_info(licenses)").all();
  if (!columns.some((c) => c.name === "product_id")) {
    db.exec("ALTER TABLE licenses ADD COLUMN product_id TEXT NOT NULL DEFAULT 'greek_goddess';");
  }

  const now = () => new Date().toISOString();

  const findStmt = db.prepare("SELECT * FROM licenses WHERE code_key = ?");
  const insertStmt = db.prepare("INSERT INTO licenses (code, code_key, product_id, note, created_at) VALUES (?, ?, ?, ?, ?)");
  const activateStmt = db.prepare(`
    UPDATE licenses
       SET activated = 1, activated_at = ?, device_hash = ?, fingerprint_hash = ?, last_seen_at = ?
     WHERE code_key = ?
  `);
  const touchStmt = db.prepare("UPDATE licenses SET last_seen_at = ? WHERE code_key = ?");
  const mismatchStmt = db.prepare("UPDATE licenses SET fp_mismatches = fp_mismatches + 1 WHERE code_key = ?");
  const scoreStmt = db.prepare("UPDATE licenses SET score_calls = score_calls + 1, last_seen_at = ? WHERE code_key = ?");
  const resetStmt = db.prepare(`
    UPDATE licenses
       SET activated = 0, activated_at = NULL, device_hash = NULL,
           fingerprint_hash = NULL, fp_mismatches = 0, last_seen_at = NULL
     WHERE code_key = ?
  `);
  const listStmt = db.prepare("SELECT * FROM licenses ORDER BY created_at DESC, code");

  return {
    find(code) {
      return findStmt.get(code) || null;
    },
    createCodes(count, productId = "greek_goddess", note = "") {
      const made = [];
      for (let i = 0; i < count; i += 1) {
        for (let attempt = 0; attempt < 20; attempt += 1) {
          const code = generateCode();
          if (findStmt.get(normalizeCode(code))) continue;
          insertStmt.run(code, normalizeCode(code), String(productId), note, now());
          made.push(code);
          break;
        }
      }
      return made;
    },
    activate(code, deviceHash, fingerprintHash) {
      activateStmt.run(now(), deviceHash, fingerprintHash, now(), code);
    },
    touch(code) {
      touchStmt.run(now(), code);
    },
    countFingerprintMismatch(code) {
      mismatchStmt.run(code);
    },
    noteScore(code) {
      scoreStmt.run(now(), code);
    },
    resetBinding(code) {
      const row = findStmt.get(code);
      if (!row) return false;
      resetStmt.run(code);
      return true;
    },
    list() {
      return listStmt.all().map((row) => ({
        ...row,
        // Never expose a full device hash over the admin API; a prefix is enough
        // for a human to tell two bindings apart.
        device_hash: row.device_hash ? String(row.device_hash).slice(0, 12) : null,
        fingerprint_hash: row.fingerprint_hash ? String(row.fingerprint_hash).slice(0, 12) : null,
      }));
    },
    close() {
      db.close();
    },
  };
}

