    CREATE TABLE IF NOT EXISTS creator_kits (
      code         TEXT PRIMARY KEY,
      code_key     TEXT NOT NULL UNIQUE,
      credits      INTEGER NOT NULL,
      note         TEXT NOT NULL DEFAULT '',
      created_at   TEXT NOT NULL,
      redeemed     INTEGER NOT NULL DEFAULT 0,
      redeemed_by  TEXT
    );
