  const kitInsertStmt = db.prepare("INSERT INTO creator_kits (code, code_key, credits, note, created_at) VALUES (?, ?, ?, ?, ?)");
  const kitRedeemStmt = db.prepare("UPDATE creator_kits SET redeemed = 1, redeemed_by = ? WHERE code_key = ? AND redeemed = 0");
  const creatorInsertStmt = db.prepare("INSERT INTO creators (creator_id, key_hash, name, credits, created_at) VALUES (?, ?, ?, ?, ?)");
  const creatorByKeyStmt = db.prepare("SELECT * FROM creators WHERE key_hash = ?");
  const creatorByIdStmt = db.prepare("SELECT * FROM creators WHERE creator_id = ?");
  const creatorTouchStmt = db.prepare("UPDATE creators SET last_seen_at = ? WHERE creator_id = ?");
