  const ledgerInsertStmt = db.prepare("INSERT INTO creator_ledger (creator_id, delta, reason, ref, created_at) VALUES (?, ?, ?, ?, ?)");
  const ledgerByCreatorStmt = db.prepare("SELECT delta, reason, ref, created_at FROM creator_ledger WHERE creator_id = ? ORDER BY id DESC LIMIT ?");
