  const themes = manifest.theme_ids === "*"
    ? content.themes
    : content.themes.filter((t) => manifest.theme_ids.includes(t.id));
  if (manifest.theme_ids !== "*") {
    const found = new Set(themes.map((t) => t.id));
    const missing = manifest.theme_ids.filter((id) => !found.has(id));
    if (missing.length) throw new Error(`product ${productId} declares unknown themes: ${missing.join(", ")}`);
  }
  return themes;
}

export function productThemes(productId) {
  return themesOf(String(productId || ""), new Set());
}

// Does the product a code was minted for entitle the requested test product?
// Direct match, or the code's product is a bundle that includes it.
export function productEntitles(codeProductId, testId) {
  if (codeProductId === testId) return true;
  const def = registry.get(String(codeProductId || ""));
  if (!def || def.manifest.type !== "bundle") return false;
  return (def.manifest.includes || []).includes(testId);
}

