export function hostCreatorProduct({ mode, skeletonId, overrides, customContent, reloadRegistry }) {
  let content;
  if (mode === "skeleton") {
    // 骨架模式：loadSkeleton 由调用方传入（products.mjs 提供），这里只信任白名单产物
    if (!skeletonData) throw new Error("骨架不存在或已下架");
    content = {
      ...skeletonData,
      title: String(overrides?.title || skeletonData.title).trim(),
      subtitle: String(overrides?.subtitle || skeletonData.subtitle).trim(),
