    CREATE TABLE IF NOT EXISTS creator_ledger (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      creator_id  TEXT NOT NULL,
      delta       INTEGER NOT NULL,
      reason      TEXT NOT NULL,
      ref         TEXT NOT NULL DEFAULT '',
      created_at  TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS creator_products (
      creator_id  TEXT NOT NULL,
      product_id  TEXT NOT NULL UNIQUE,
      name        TEXT NOT NULL DEFAULT '',
      created_at  TEXT NOT NULL
    );
  `);

  const kitFindStmt = db.prepare("SELECT * FROM creator_kits WHERE code_key = ?");
  const kitInsertStmt = db.prepare("INSERT INTO creator_kits (code, code_key, credits, note, created_at) VALUES (?, ?, ?, ?, ?)");
  const kitRedeemStmt = db.prepare("UPDATE creator_kits SET redeemed = 1, redeemed_by = ? WHERE code_key = ? AND redeemed = 0");
  const creatorInsertStmt = db.prepare("INSERT INTO creators (creator_id, key_hash, name, credits, created_at) VALUES (?, ?, ?, ?, ?)");
  const creatorByKeyStmt = db.prepare("SELECT * FROM creators WHERE key_hash = ?");
  const creatorByIdStmt = db.prepare("SELECT * FROM creators WHERE creator_id = ?");
  const creatorTouchStmt = db.prepare("UPDATE creators SET last_seen_at = ? WHERE creator_id = ?");
  const creatorListStmt = db.prepare("SELECT creator_id, name, credits, created_at, last_seen_at FROM creators ORDER BY created_at DESC, creator_id");
  const ledgerInsertStmt = db.prepare("INSERT INTO creator_ledger (creator_id, delta, reason, ref, created_at) VALUES (?, ?, ?, ?, ?)");
  const ledgerByCreatorStmt = db.prepare("SELECT delta, reason, ref, created_at FROM creator_ledger WHERE creator_id = ? ORDER BY id DESC LIMIT ?");
  const ledgerApplyStmt = db.prepare("UPDATE creators SET credits = credits + ? WHERE creator_id = ?");
  const cpInsertStmt = db.prepare("INSERT INTO creator_products (creator_id, product_id, name, created_at) VALUES (?, ?, ?, ?)");
  const cpListStmt = db.prepare("SELECT product_id, name, created_at FROM creator_products WHERE creator_id = ? ORDER BY created_at DESC");
  const cpFindStmt = db.prepare("SELECT * FROM creator_products WHERE creator_id = ? AND product_id = ?");

  return {
    find(code) {
      return findStmt.get(code) || null;
    },
    createCodes(count, productId = "greek_goddess", note = "") {
      const made = [];
      for (let i = 0; i < count; i += 1) {
        for (let attempt = 0; attempt < 20; attempt += 1) {
          const code = generateCode();
          if (findStmt.get(normalizeCode(code))) continue;
          insertStmt.run(code, normalizeCode(code), String(productId), note, now());
          made.push(code);
          break;
        }
      }
      return made;
    },
    activate(code, deviceHash, fingerprintHash) {
      activateStmt.run(now(), deviceHash, fingerprintHash, now(), code);
    },
    touch(code) {
      touchStmt.run(now(), code);
    },
    countFingerprintMismatch(code) {
      mismatchStmt.run(code);
    },
    noteScore(code) {
      scoreStmt.run(now(), code);
    },
    resetBinding(code) {
      const row = findStmt.get(code);
      if (!row) return false;
      resetStmt.run(code);
      return true;
    },
    list() {
      return listStmt.all().map((row) => ({
        ...row,
        // Never expose a full device hash over the admin API; a prefix is enough
        // for a human to tell two bindings apart.
        device_hash: row.device_hash ? String(row.device_hash).slice(0, 12) : null,
        fingerprint_hash: row.fingerprint_hash ? String(row.fingerprint_hash).slice(0, 12) : null,
      }));
    },

    /* ------------------------------------------------- 创作者工坊 API ---- */
    createKits(count, credits, note = "") {
      const made = [];
      for (let i = 0; i < count; i += 1) {
        for (let attempt = 0; attempt < 20; attempt += 1) {
          const code = generateKitCode();
          if (kitFindStmt.get(normalizeCode(code))) continue;
          kitInsertStmt.run(code, normalizeCode(code), Math.max(0, Math.round(credits)), String(note).slice(0, 120), now());
          made.push(code);
          break;
        }
      }
      return made;
    },
    findKit(codeKey) {
      return kitFindStmt.get(codeKey) || null;
    },
    // 原子兑换：redeemed=0 才更新，防并发双花。成功返回 kit，失败返回 null。
    redeemKit(codeKey, creatorId) {
      const result = kitRedeemStmt.run(creatorId, codeKey);
      return result.changes > 0 ? kitFindStmt.get(codeKey) : null;
    },
    createCreator(creatorId, keyHash, credits, name = "") {
      creatorInsertStmt.run(creatorId, keyHash, String(name).slice(0, 60), credits, now());
    },
    creatorByKey(keyHash) {
      return creatorByKeyStmt.get(keyHash) || null;
    },
    creatorById(creatorId) {
      return creatorByIdStmt.get(creatorId) || null;
    },
    creatorTouch(creatorId) {
      creatorTouchStmt.run(now(), creatorId);
    },
    // 额度变动一律走这里：先记账后入账，拒绝把余额做负。
    applyCredits(creatorId, delta, reason, ref = "") {
      if (!Number.isInteger(delta) || delta === 0) throw new Error("ledger delta must be a non-zero integer");
      const creator = creatorByIdStmt.get(creatorId);
      if (!creator) throw new Error(`unknown creator ${creatorId}`);
      if (delta < 0 && creator.credits + delta < 0) return null;
      ledgerInsertStmt.run(creatorId, delta, String(reason).slice(0, 60), String(ref).slice(0, 120), now());
      ledgerApplyStmt.run(delta, creatorId);
      return creatorByIdStmt.get(creatorId).credits;
    },
    creatorLedger(creatorId, limit = 20) {
      return ledgerByCreatorStmt.all(creatorId, Math.min(Math.max(limit, 1), 100));
    },
    creatorProducts(creatorId) {
      return cpListStmt.all(creatorId);
    },
    setCreatorProduct(creatorId, productId, name) {
      cpInsertStmt.run(creatorId, productId, String(name).slice(0, 80), now());
    },
    creatorOwnsProduct(creatorId, productId) {
      return Boolean(productId) && Boolean(cpFindStmt.get(creatorId, productId));
    },
    creatorKitsList() {
      return db.prepare("SELECT code, credits, note, created_at, redeemed, redeemed_by FROM creator_kits ORDER BY created_at DESC, code").all();
    },
    close() {
      db.close();
    },
  };
}

