// License store — node:sqlite (built into Node >= 22.5), zero external deps.
//
// Schema notes:
//   licenses.code          canonical plaintext code, PRIMARY KEY (the DB file is
//                          private infrastructure; keep it out of any web root)
//   licenses.device_hash   sha256(device secret). The secret itself exists only
//                          in the buyer's browser; the server never stores it.
//   licenses.fingerprint_hash  sha256 of the auxiliary client fingerprint. Only
//                          used to *count* mismatches — it never blocks access.
//
// Codes look like MYTHIC-AB2CD-EF7GH (10 chars from an unambiguous 31-char
// alphabet ~= 5e15 combinations; rate limiting makes online brute force inert).
import { randomBytes, createHash } from "node:crypto";
import { mkdirSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";

const ALPHABET = "23456789ABCDEFGHJKMNPQRSTUVWXYZ"; // no 0/O, 1/I/L look-alikes
const CODE_PREFIX = "MYTHIC";
const ADMIN_KEY_FILE = "admin-key.txt";

export function sha256(text) {
  return createHash("sha256").update(String(text)).digest("hex");
}

export function normalizeCode(input) {
  const compact = String(input || "").toUpperCase().replace(/[\s-]+/g, "");
  if (!/^[A-Z0-9]{6,40}$/.test(compact)) return null;
  return compact;
}

function randomCodeChunk(length) {
  const bytes = randomBytes(length);
  let out = "";
  for (let i = 0; i < length; i += 1) out += ALPHABET[bytes[i] % ALPHABET.length];
  return out;
}

export function generateCode() {
  return `${CODE_PREFIX}-${randomCodeChunk(5)}-${randomCodeChunk(5)}`;
}

// 创作者工坊的码走独立前缀，绝不与产品兑换码混用。
const KIT_PREFIX = "CREATOR";
export function generateKitCode() {
  return `${KIT_PREFIX}-${randomCodeChunk(5)}-${randomCodeChunk(5)}`;
}

export function newCreatorKey() {
  return `crk_${randomBytes(24).toString("base64url")}`;
}

export function newDeviceSecret() {
  return randomBytes(24).toString("base64url");
}

export function ensureAdminKey(dataDir) {
  const file = join(dataDir, ADMIN_KEY_FILE);
  const fromEnv = (process.env.MYTHIC_ADMIN_KEY || "").trim();
  if (fromEnv) return fromEnv;
  if (!existsSync(file)) {
    mkdirSync(dataDir, { recursive: true });
    writeFileSync(file, randomBytes(24).toString("hex") + "\n", { encoding: "utf8" });
    console.log(`[store] generated admin key -> ${file} (set MYTHIC_ADMIN_KEY to override)`);
  }
  return readFileSync(file, "utf8").trim();
}

export function openStore(dataDir) {
  mkdirSync(dataDir, { recursive: true });
  const db = new DatabaseSync(join(dataDir, "licenses.db"));
  db.exec("PRAGMA journal_mode = WAL;");
  db.exec("PRAGMA busy_timeout = 5000;");
  db.exec(`
    CREATE TABLE IF NOT EXISTS licenses (
      code              TEXT PRIMARY KEY,
      code_key          TEXT NOT NULL UNIQUE,
      product_id        TEXT NOT NULL DEFAULT 'greek_goddess',
      note              TEXT NOT NULL DEFAULT '',
      created_at        TEXT NOT NULL,
      activated         INTEGER NOT NULL DEFAULT 0,
      activated_at      TEXT,
      device_hash       TEXT,
      fingerprint_hash  TEXT,
      fp_mismatches     INTEGER NOT NULL DEFAULT 0,
      score_calls       INTEGER NOT NULL DEFAULT 0,
      last_seen_at      TEXT
    );
  `);
  // Existing databases predate the product column: backfill with the default so
  // every already-sold code keeps working with no manual migration.
  const columns = db.prepare("PRAGMA table_info(licenses)").all();
  if (!columns.some((c) => c.name === "product_id")) {
    db.exec("ALTER TABLE licenses ADD COLUMN product_id TEXT NOT NULL DEFAULT 'greek_goddess';");
  }

  const now = () => new Date().toISOString();

  const findStmt = db.prepare("SELECT * FROM licenses WHERE code_key = ?");
  const insertStmt = db.prepare("INSERT INTO licenses (code, code_key, product_id, note, created_at) VALUES (?, ?, ?, ?, ?)");
  const activateStmt = db.prepare(`
    UPDATE licenses
       SET activated = 1, activated_at = ?, device_hash = ?, fingerprint_hash = ?, last_seen_at = ?
     WHERE code_key = ?
  `);
  const touchStmt = db.prepare("UPDATE licenses SET last_seen_at = ? WHERE code_key = ?");
  const mismatchStmt = db.prepare("UPDATE licenses SET fp_mismatches = fp_mismatches + 1 WHERE code_key = ?");
  const scoreStmt = db.prepare("UPDATE licenses SET score_calls = score_calls + 1, last_seen_at = ? WHERE code_key = ?");
  const resetStmt = db.prepare(`
    UPDATE licenses
       SET activated = 0, activated_at = NULL, device_hash = NULL,
           fingerprint_hash = NULL, fp_mismatches = 0, last_seen_at = NULL
     WHERE code_key = ?
  `);
  const listStmt = db.prepare("SELECT * FROM licenses ORDER BY created_at DESC, code");

  /* ----------------------------------------------------- 创作者工坊 ----
     creator_kits   待售的"创作额度包"码（老板在小红书卖出后手动发货），
                    redeem 前后都不含任何买家个人信息。
     creators       创作者账户：只存 key 的哈希（key 本体只在买家浏览器里），
                    credits 是可用额度，消费全部走 ledger 留痕。
     creator_ledger 每一笔额度增减的审计流水（铸包/兑换/托管发布/下载工具包）。 */
  db.exec(`
    CREATE TABLE IF NOT EXISTS creator_kits (
      code         TEXT PRIMARY KEY,
      code_key     TEXT NOT NULL UNIQUE,
      credits      INTEGER NOT NULL,
      note         TEXT NOT NULL DEFAULT '',
      created_at   TEXT NOT NULL,
      redeemed     INTEGER NOT NULL DEFAULT 0,
      redeemed_by  TEXT
    );
    CREATE TABLE IF NOT EXISTS creators (
      creator_id    TEXT PRIMARY KEY,
      key_hash      TEXT NOT NULL UNIQUE,
      name          TEXT NOT NULL DEFAULT '',
      credits       INTEGER NOT NULL DEFAULT 0,
      created_at    TEXT NOT NULL,
      last_seen_at  TEXT
    );
    CREATE TABLE IF NOT EXISTS creator_ledger (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      creator_id  TEXT NOT NULL,
      delta       INTEGER NOT NULL,
      reason      TEXT NOT NULL,
      ref         TEXT NOT NULL DEFAULT '',
      created_at  TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS creator_products (
      creator_id  TEXT NOT NULL,
      product_id  TEXT NOT NULL UNIQUE,
      name        TEXT NOT NULL DEFAULT '',
      created_at  TEXT NOT NULL
    );
  `);

  const kitFindStmt = db.prepare("SELECT * FROM creator_kits WHERE code_key = ?");
  const kitInsertStmt = db.prepare("INSERT INTO creator_kits (code, code_key, credits, note, created_at) VALUES (?, ?, ?, ?, ?)");
  const kitRedeemStmt = db.prepare("UPDATE creator_kits SET redeemed = 1, redeemed_by = ? WHERE code_key = ? AND redeemed = 0");
  const creatorInsertStmt = db.prepare("INSERT INTO creators (creator_id, key_hash, name, credits, created_at) VALUES (?, ?, ?, ?, ?)");
  const creatorByKeyStmt = db.prepare("SELECT * FROM creators WHERE key_hash = ?");
  const creatorByIdStmt = db.prepare("SELECT * FROM creators WHERE creator_id = ?");
  const creatorTouchStmt = db.prepare("UPDATE creators SET last_seen_at = ? WHERE creator_id = ?");
  const creatorListStmt = db.prepare("SELECT creator_id, name, credits, created_at, last_seen_at FROM creators ORDER BY created_at DESC, creator_id");
  const ledgerInsertStmt = db.prepare("INSERT INTO creator_ledger (creator_id, delta, reason, ref, created_at) VALUES (?, ?, ?, ?, ?)");
  const ledgerByCreatorStmt = db.prepare("SELECT delta, reason, ref, created_at FROM creator_ledger WHERE creator_id = ? ORDER BY id DESC LIMIT ?");
  const ledgerApplyStmt = db.prepare("UPDATE creators SET credits = credits + ? WHERE creator_id = ?");
  const cpInsertStmt = db.prepare("INSERT INTO creator_products (creator_id, product_id, name, created_at) VALUES (?, ?, ?, ?)");
  const cpListStmt = db.prepare("SELECT product_id, name, created_at FROM creator_products WHERE creator_id = ? ORDER BY created_at DESC");
  const cpFindStmt = db.prepare("SELECT * FROM creator_products WHERE creator_id = ? AND product_id = ?");

  return {
    find(code) {
      return findStmt.get(code) || null;
    },
    createCodes(count, productId = "greek_goddess", note = "") {
      const made = [];
      for (let i = 0; i < count; i += 1) {
        for (let attempt = 0; attempt < 20; attempt += 1) {
          const code = generateCode();
          if (findStmt.get(normalizeCode(code))) continue;
          insertStmt.run(code, normalizeCode(code), String(productId), note, now());
          made.push(code);
          break;
        }
      }
      return made;
    },
    activate(code, deviceHash, fingerprintHash) {
      activateStmt.run(now(), deviceHash, fingerprintHash, now(), code);
    },
    touch(code) {
      touchStmt.run(now(), code);
    },
    countFingerprintMismatch(code) {
      mismatchStmt.run(code);
    },
    noteScore(code) {
      scoreStmt.run(now(), code);
    },
    resetBinding(code) {
      const row = findStmt.get(code);
      if (!row) return false;
      resetStmt.run(code);
      return true;
    },
    list() {
      return listStmt.all().map((row) => ({
        ...row,
        // Never expose a full device hash over the admin API; a prefix is enough
        // for a human to tell two bindings apart.
        device_hash: row.device_hash ? String(row.device_hash).slice(0, 12) : null,
        fingerprint_hash: row.fingerprint_hash ? String(row.fingerprint_hash).slice(0, 12) : null,
      }));
    },

    /* ------------------------------------------------- 创作者工坊 API ---- */
    createKits(count, credits, note = "") {
      const made = [];
      for (let i = 0; i < count; i += 1) {
        for (let attempt = 0; attempt < 20; attempt += 1) {
          const code = generateKitCode();
          if (kitFindStmt.get(normalizeCode(code))) continue;
          kitInsertStmt.run(code, normalizeCode(code), Math.max(0, Math.round(credits)), String(note).slice(0, 120), now());
          made.push(code);
          break;
        }
      }
      return made;
    },
    findKit(codeKey) {
      return kitFindStmt.get(codeKey) || null;
    },
    // 原子兑换：redeemed=0 才更新，防并发双花。成功返回 kit，失败返回 null。
    redeemKit(codeKey, creatorId) {
      const result = kitRedeemStmt.run(creatorId, codeKey);
      return result.changes > 0 ? kitFindStmt.get(codeKey) : null;
    },
    createCreator(creatorId, keyHash, credits, name = "") {
      creatorInsertStmt.run(creatorId, keyHash, String(name).slice(0, 60), credits, now());
    },
    creatorByKey(keyHash) {
      return creatorByKeyStmt.get(keyHash) || null;
    },
    creatorById(creatorId) {
      return creatorByIdStmt.get(creatorId) || null;
    },
    creatorTouch(creatorId) {
      creatorTouchStmt.run(now(), creatorId);
    },
    // 额度变动一律走这里：先记账后入账，拒绝把余额做负。
    applyCredits(creatorId, delta, reason, ref = "") {
      if (!Number.isInteger(delta) || delta === 0) throw new Error("ledger delta must be a non-zero integer");
      const creator = creatorByIdStmt.get(creatorId);
      if (!creator) throw new Error(`unknown creator ${creatorId}`);
      if (delta < 0 && creator.credits + delta < 0) return null;
      ledgerInsertStmt.run(creatorId, delta, String(reason).slice(0, 60), String(ref).slice(0, 120), now());
      ledgerApplyStmt.run(delta, creatorId);
      return creatorByIdStmt.get(creatorId).credits;
    },
    creatorLedger(creatorId, limit = 20) {
      return ledgerByCreatorStmt.all(creatorId, Math.min(Math.max(limit, 1), 100));
    },
    creatorProducts(creatorId) {
      return cpListStmt.all(creatorId);
    },
    setCreatorProduct(creatorId, productId, name) {
      cpInsertStmt.run(creatorId, productId, String(name).slice(0, 80), now());
    },
    creatorOwnsProduct(creatorId, productId) {
      return Boolean(productId) && Boolean(cpFindStmt.get(creatorId, productId));
    },
    listCreators() {
      return creatorListStmt.all();
    },
    creatorKitsList() {
      return db.prepare("SELECT code, credits, note, created_at, redeemed, redeemed_by FROM creator_kits ORDER BY created_at DESC, code").all();
    },
    close() {
      db.close();
    },
  };
}

