readFileState.content:
// Admin CLI — direct DB access, no HTTP needed (stop the server or rely on WAL).
//
//   node server/admin.mjs codes greek_goddess 20 --note "xhs-0929-batch"
//   node server/admin.mjs codes 20                 # legacy order -> greek_goddess
//   node server/admin.mjs list
//   node server/admin.mjs status MYTHIC-AB2CD-EF7GH
//   node server/admin.mjs reset MYTHIC-AB2CD-EF7GH
//   node server/admin.mjs kits 10 --credits 10 --note "创作包批次"   # 创作者额度包
//   node server/admin.mjs creators                                   # 包 + 创作者清单
//   node server/admin.mjs credit c-1a2b3c4d +5 --note "补偿"
//
// `codes` prints one code per line — pipe to a file or straight into your
// 发货 sheet. `reset` clears the device binding so the buyer can re-activate
// on a new browser (clearing activation, device hash and mismatch counter).
import { openStore, normalizeCode } from "./store.mjs";
import { DEFAULT_PRODUCT_ID, getProduct, listProducts } from "./products.mjs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const DATA_DIR = process.env.MYTHIC_DATA_DIR || join(HERE, "data");
const store = openStore(DATA_DIR);

const [command, ...rest] = process.argv.slice(2);
const flag = (name) => {
  const i = rest.indexOf(name);
  return i === -1 ? null : rest[i + 1];
};

try {
  if (command === "codes") {
    // New form: codes <product_id> <count>; legacy form: codes <count> defaults
    // to greek_goddess so existing muscle memory and scripts keep working.
    let productId = DEFAULT_PRODUCT_ID;
    let countArg = rest[0];
    if (rest.length && !/^\d+$/.test(rest[0])) {
      productId = rest[0];
      countArg = rest[1];
    }
    if (!getProduct(productId)) {
      console.error(`[admin] unknown product ${productId} (known: ${listProducts().map((p) => p.product_id).join(", ")})`);
      process.exitCode = 1;
    } else {
      const count = Math.min(Math.max(Number(countArg) || 1, 1), 500);
      const note = flag("--note") || "";
      const codes = store.createCodes(count, productId, note);
      for (const code of codes) console.log(code);
      console.error(`[admin] created ${codes.length} code(s) for ${productId}, note=${JSON.stringify(note)}`);
    }
  } else if (command === "list") {
    const rows = store.list();
    console.log("code\tproduct\tactivated\tscore_calls\tfp_mismatch\tnote\tcreated");
    for (const r of rows) {
      console.log(`${r.code}\t${r.product_id}\t${r.activated ? "yes" : "no"}\t${r.score_calls}\t${r.fp_mismatches}\t${r.note}\t${r.created_at}`);
    }
    console.error(`[admin] ${rows.length} license(s)`);
  } else if (command === "status") {
    const code = normalizeCode(rest[0]);
    const row = code && store.find(code);
    if (!row) {
      console.error("[admin] code not found");
      process.exitCode = 1;
    } else {
      console.log(JSON.stringify({ ...row, device_hash: row.device_hash?.slice(0, 12), fingerprint_hash: row.fingerprint_hash?.slice(0, 12) }, null, 2));
    }
  } else if (command === "kits") {
    // 铸创作额度包码：node server/admin.mjs kits 10 --credits 10 --note "xhs-1109 批次"
    const count = Math.min(Math.max(Number(rest[0]) || 1, 1), 500);
    const credits = Number(flag("--credits")) || 10;
    const note = flag("--note") || "";
    const kits = store.createKits(count, credits, note);
    for (const code of kits) console.log(code);
    console.error(`[admin] created ${kits.length} creator kit(s), ${credits} credits each, note=${JSON.stringify(note)}`);
  } else if (command === "creators") {
    for (const k of store.creatorKitsList()) {
      console.log(`kit\t${k.code}\t${k.credits}\t${k.redeemed ? "redeemed" : "unsold"}\t${k.redeemed_by || "-"}\t${k.note}`);
    }
    for (const c of store.listCreators()) {
      console.log(`creator\t${c.creator_id}\tcredits=${c.credits}\t${c.name || "-"}\t${c.created_at}`);
    }
    console.error("[admin] kit/creator 清单如上");
  } else if (command === "credit") {
    // 手工调额度：node server/admin.mjs credit c-1a2b3c4d +5 --note "补偿"
    const [creatorId, deltaRaw] = rest;
    const delta = Number(deltaRaw);
    if (!creatorId || !Number.isInteger(delta) || delta === 0) {
      console.error("usage: credit <creator_id> <+N|-N> --note \"…\"");
      process.exitCode = 1;
    } else {
      const left = store.applyCredits(creatorId, delta, flag("--note") || "admin-adjust", "manual");
      console.error(left === null ? `[admin] 调整失败：额度不足（creator ${creatorId}）` : `[admin] ${creatorId} ${delta > 0 ? "+" : ""}${delta} -> ${left} credits`);
      process.exitCode = left === null ? 1 : 0;
    }
  } else if (command === "reset") {
    const code = normalizeCode(rest[0]);
    const ok = code && store.resetBinding(code);
    console.error(ok ? `[admin] binding reset for ${code}` : "[admin] code not found");
    process.exitCode = ok ? 0 : 1;
  } else {
    console.error("usage: node server/admin.mjs <codes|list|status|reset|kits|creators|credit> [args]");
    process.exitCode = 1;
  }
} finally {
  store.close();
}

