import("./server/creators.mjs").then(async ({ validateCreatorContent }) => {
  const { readFileSync } = await import("node:fs");
  for (const f of ["late-night-store", "recharge-station"]) {
    const data = JSON.parse(readFileSync(`server/content/skeletons/${f}.json`, "utf8"));
    const v = validateCreatorContent(data);
    console.log(v.ok ? `PASS  ${f}` : `FAIL  ${f}\n  ${v.errors.join("\n  ")}`);
