        <h2>① 挑主题，一键上线</h2>
        <div id="skeleton-list" class="skeleton-list"><p class="small">加载主题中…</p></div>
        <div id="skeleton-form"></div>
      </div>

      <div class="panel">
        <h2>② 我的测试</h2>
        <div id="my-products">${overview.products.length ? "" : '<p class="small">还没有发布，先去上面挑一个主题。</p>'}</div>
        <div class="mint-row">
          <select id="mint-product" aria-label="选择测试">${overview.products.map((p) => `<option value="${esc(p.product_id)}">${esc(p.name)}</option>`).join("")}</select>
          <input id="mint-count" class="gate-input mint-count" type="number" min="1" max="200" value="20" aria-label="铸码数量">
          <button class="secondary" id="mint-btn">铸码</button>
        </div>
        <div id="mint-result"></div>
      </div>

      <div class="panel">
        <h2>③ 进阶</h2>
        <button class="secondary" id="custom-toggle">提交自己的题库 JSON（定制模式）</button>
        <div id="custom-form"></div>
        <button class="secondary" id="kit-download">下载创作工具包（自助模式，扣 ${overview.pricing.COST_KIT_DOWNLOAD} 额度）</button>
      </div>

      <div class="panel">
        <h2>额度流水</h2>
        <ul class="ledger">${overview.ledger.map((e) => `<li><span>${e.delta > 0 ? "+" : ""}${e.delta}</span> ${esc(e.reason)} <small>${esc(e.created_at)}</small></li>`).join("") || '<li class="small">暂无流水</li>'}</ul>
        <button class="back" id="logout">退出登录（换一个码）</button>
      </div>
      <p class="notice">免责声明：平台提供制作与托管工具；售卖、宣传与收款由创作者自行完成并自行负责合规，请勿声称科学诊断或承诺收益。</p>
    `));

    document.querySelector("#logout").addEventListener("click", () => { clearKey(); redeemView(); });
    document.querySelector("#kit-download").addEventListener("click", downloadKit);
    document.querySelector("#custom-toggle").addEventListener("click", () => {
      const box = document.querySelector("#custom-form");
      box.innerHTML = box.innerHTML ? "" : customFormHtml();
      if (box.innerHTML) document.querySelector("#custom-submit").addEventListener("click", submitCustom);
    });
    document.querySelector("#mint-btn").addEventListener("click", mint);
    await loadSkeletons();
    renderProducts(overview.products);
  }

  function customFormHtml() {
    return `
      <textarea id="custom-json" class="custom-json" rows="10" placeholder='粘贴题库 JSON：{"title":…,"subtitle":…,"results":[…],"questions":[…]}，要求 12–16 题、6–8 个结果，评分只引用已声明结果 id（0–3 整数）。提交后服务端会做可达性与平衡校验。'></textarea>
      <button class="primary" id="custom-submit">校验并发布（扣 ${10} 额度）</button>`;
  }

  async function loadSkeletons() {
    const { data } = await api("/api/creator/skeletons");
    const list = document.querySelector("#skeleton-list");
    if (!data.ok || !data.skeletons.length) {
      list.innerHTML = '<p class="small">暂无可选主题，请联系平台方。</p>';
      return;
    }
    list.innerHTML = data.skeletons.map((s, i) => `
      <label class="skeleton-card">
        <input type="radio" name="skeleton" value="${esc(s.skeleton_id)}" ${i === 0 ? "checked" : ""}>
        <div><b>${esc(s.title)}</b><span class="small">${esc(s.subtitle)}</span><span class="small">${s.question_count} 题 · ${s.result_count} 个结果：${s.result_names.map(esc).join(" / ")}</span></div>
      </label>`).join("");
    document.querySelector("#skeleton-form").innerHTML = `
      <input id="host-title" class="gate-input" type="text" maxlength="40" placeholder="你的测试标题（可自定）" aria-label="测试标题">
      <input id="host-subtitle" class="gate-input" type="text" maxlength="80" placeholder="副标题（可自定）" aria-label="副标题">
      <button class="primary" id="host-btn">一键发布（扣额度）</button>
      <p class="gate-error" id="host-error" role="alert"></p>`;
    document.querySelector("#host-btn").addEventListener("click", hostSkeleton);
  }

  async function hostSkeleton() {
    const btn = document.querySelector("#host-btn");
    const error = document.querySelector("#host-error");
    const skeleton = document.querySelector('input[name="skeleton"]:checked')?.value;
    btn.disabled = true;
    const { status, data } = await api("/api/creator/host", {
      method: "POST",
      body: { mode: "skeleton", skeleton_id: skeleton, title: document.querySelector("#host-title").value, subtitle: document.querySelector("#host-subtitle").value },
    });
    btn.disabled = false;
    if (status === 200 && data.ok) {
      error.textContent = "";
      return dashboard(await refreshOverview());
    }
    error.textContent = data.error === "insufficient_credits"
      ? `额度不足，需要 ${data.required} 点，请购买创作额度包`
      : (data.errors?.[0] || data.error || "发布失败");
  }

  async function submitCustom() {
    const out = await api("/api/creator/host", { method: "POST", body: { mode: "custom", content: document.querySelector("#custom-json").value } });
    if (out.status === 200 && out.data.ok) return dashboard(await refreshOverview());
    const box = document.querySelector("#custom-form");
    box.insertAdjacentHTML("beforeend", `<p class="gate-error">${(out.data.errors || [out.data.error]).map(esc).join("；")}</p>`);
  }

  function renderProducts(products) {
    const box = document.querySelector("#my-products");
    box.innerHTML = products.map((p) => `
      <div class="product-row">
        <b>${esc(p.name)}</b>
        <a class="small" href="/t/${esc(p.product_id)}" target="_blank" rel="noopener">/t/${esc(p.product_id)}</a>
        <span class="small">${esc(p.created_at.slice(0, 10))}</span>
      </div>`).join("");
  }

  async function mint() {
    const product = document.querySelector("#mint-product")?.value;
    const count = Number(document.querySelector("#mint-count").value) || 1;
    const box = document.querySelector("#mint-result");
    if (!product) { box.innerHTML = '<p class="gate-error">先发布一个测试，再来铸码。</p>'; return; }
    const { status, data } = await api("/api/creator/mint", { method: "POST", body: { product_id: product, count } });
    if (status === 200 && data.ok) {
      box.innerHTML = `
        <p class="small">以下 ${data.codes.length} 个兑换码只显示一次，请立即复制保存：</p>
        <textarea class="custom-json" rows="${Math.min(data.codes.length, 8)}" readonly>${esc(data.codes.join("\n"))}</textarea>`;
      box.querySelector("textarea").select();
    } else {
      box.innerHTML = `<p class="gate-error">${{ not_your_product: "只能给自己的测试铸码" }[data.error] || data.error}</p>`;
    }
  }

  async function downloadKit() {
    const { status, data } = await api("/api/creator/kit", { method: "POST" });
    if (status === 200 && data.ok) {
      const blob = new Blob([data.kit], { type: "text/plain;charset=utf-8" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "MYTHIC-creator-kit.txt";
      a.click();
      URL.revokeObjectURL(a.href);
    } else {
      alert(data.error === "insufficient_credits" ? `额度不足，需要 ${data.required} 点` : data.error);
    }
  }

  boot();
})();

