// Content sanitizer — builds the public payload from the private full quiz file.
//
// What stays: theme metadata, question text, option text (the shop window).
// What is stripped before anything reaches the browser:
//   - option.scores (the answer weight vectors)
//   - the whole scoring block (normalization bounds, result order, tie-break data)
//   - full result records (readings, share lines, mythic traces) — only the id
//     stub survives, and the /api/score response carries the winner's record only
//   - editorial internals (editorial_review, source_status)

const PASS_THROUGH_THEME_FIELDS = [
  "id", "title", "subtitle", "description", "disclaimer",
  "theme_basis", "catalog_label", "dimensions",
];

export function sanitizeTheme(theme) {
  const out = {};
  for (const field of PASS_THROUGH_THEME_FIELDS) {
    if (theme[field] !== undefined) out[field] = theme[field];
  }
  out.questions = (theme.questions || []).map((q) => ({
    question: q.question,
    options: (q.options || []).map((o) => ({ text: o.text })),
  }));
  // Id stubs keep the client shape stable; no content leaks through them.
  out.results = (theme.results || []).map((r) => ({ id: r.id }));
  return out;
}

export function sanitizeContent(full) {
  return { themes: (full.themes || []).map(sanitizeTheme) };
}

