```js
function autoRedeemFromUrl() {
  try {
    const code = new URLSearchParams(location.search || "").get("code");
    if (!code) return;
    const input = document.querySelector("#gate-code, [id$='gate-code']");
    const submit = document.querySelector("#gate-submit, [id$='gate-submit']");
    if (!input || !submit) return;
    input.value = code;
    (submit.onclick ? submit.onclick() : submit.click());
  } catch { /* never block the gate */ }
