/* creator.js — 创作者工坊门户。只调 /api/creator/*，本地不存任何评分逻辑。 */
(() => {
  const KEY_STORE = "mythic.creator.v1";
  const view = document.querySelector("#view");

  const getKey = () => {
    try { return JSON.parse(localStorage.getItem(KEY_STORE) || "null"); } catch { return null; }
  };
  const saveKey = (creatorId, creatorKey) => localStorage.setItem(KEY_STORE, JSON.stringify({ creator_id: creatorId, creator_key: creatorKey }));
  const clearKey = () => localStorage.removeItem(KEY_STORE);

  async function api(path, { method = "GET", body } = {}) {
    const key = getKey();
    const headers = { "Content-Type": "application/json" };
    if (key?.creator_key) headers["x-creator-key"] = key.creator_key;
    const res = await fetch(path, { method, headers, body: body ? JSON.stringify(body) : undefined });
    return { status: res.status, data: await res.json() };
  }

  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  // 后端余额/价格单位一律是"分"
  const yuan = (fen) => (fen / 100).toFixed(2).replace(/\.00$/, "");

  function render(html) { view.innerHTML = html; }
  const shell = (inner) => `<section class="hero">${inner}</section>`;

  /* ------------------------------------------------------------- 入口 ---- */
  async function boot() {
    const key = getKey();
    if (key?.creator_key) {
      const { status, data } = await api("/api/creator/overview");
      if (status === 200 && data.ok) return dashboard(data);
      clearKey(); // key 失效（如换库）就回到兑换页
    }
    redeemView();
  }

  function redeemView(message = "") {
    render(shell(`
      <div class="eyebrow">Creator Studio</div>
      <h1>创作者工坊</h1>
      <p class="lead">不用学编程，不用自己部署。输入创作包兑换码，挑一套主题，几分钟上线一个属于你的付费测试——之后在你的店里卖码收钱。</p>
      <div class="gate-form">
        <input id="kit-code" class="gate-input" type="text" autocomplete="off" spellcheck="false"
               placeholder="CREATOR-XXXXX-XXXXX" aria-label="创作包兑换码">
        <button class="primary" id="kit-redeem">兑换</button>
      </div>
      <p class="gate-error" id="gate-error" role="alert">${esc(message)}</p>
      <p class="notice">还没有兑换码？在【店铺名】购买"创作额度包"即可获得。兑换即表示同意：售卖与收款由你自行完成，请勿在宣传中承诺收益或疗效。</p>
    `));
    document.querySelector("#kit-redeem").addEventListener("click", redeem);
    document.querySelector("#kit-code").addEventListener("keydown", (e) => { if (e.key === "Enter") redeem(); });
  }

  async function redeem() {
    const input = document.querySelector("#kit-code");
    const button = document.querySelector("#kit-redeem");
    const code = input.value.trim();
    if (!code) return;
    button.disabled = true;
    button.textContent = "兑换中…";
    const { status, data } = await api("/api/creator/redeem", { method: "POST", body: { code } });
    button.disabled = false;
    button.textContent = "兑换";
    if (status === 200 && data.ok) {
      saveKey(data.creator_id, data.creator_key);
      return dashboard(await refreshOverview());
    }
    const reason = { invalid_kit_code: "兑换码不存在，检查一下格式", kit_already_redeemed: "这个兑换码已经被用过" }[data.error] || `兑换失败（${data.error || status}）`;
    redeemView(reason);
  }

  async function refreshOverview() {
    const { data } = await api("/api/creator/overview");
    return data;
  }

  /* ----------------------------------------------------------- 工作台 ---- */
  async function dashboard(overview) {
    if (!overview?.ok) return redeemView("登录状态已过期，请重新兑换或联系卖家");
    const p = overview.pricing;
    render(shell(`
      <div class="eyebrow">${esc(overview.creator_id)}</div>
      <h1 class="credit-line">余额 <b>${yuan(overview.credits)}</b> 元</h1>
      <p class="lead">发布测试 ${yuan(p.COST_HOST)} 元/个 · 兑换码 ${yuan(p.PRICE_CODE)} 元/个（卖多少归你，码价就是平台抽成，先付后卖零对账）。</p>

      <div class="panel">
        <h2>充值</h2>
        <div class="mint-row">
          <input id="topup-code" class="gate-input" type="text" placeholder="CREATOR-XXXXX-XXXXX" aria-label="充值码">
          <button class="secondary" id="topup-btn">充值</button>
        </div>
        <p class="small">充值方式：转账后联系客服拿充值码，输入即到账。</p>
      </div>

      <div class="panel">
        <h2>① 挑主题，一键上线（${yuan(p.COST_HOST)} 元）</h2>
        <div id="skeleton-list" class="skeleton-list"><p class="small">加载主题中…</p></div>
        <div id="skeleton-form"></div>
      </div>

      <div class="panel">
        <h2>② 我的测试</h2>
        <div id="my-products">${overview.products.length ? "" : '<p class="small">还没有发布，先去上面挑一个主题。</p>'}</div>
        <div class="mint-row">
          <select id="mint-product" aria-label="选择测试">${overview.products.map((prod) => `<option value="${esc(prod.product_id)}">${esc(prod.name)}</option>`).join("")}</select>
          <input id="mint-count" class="gate-input mint-count" type="number" min="1" max="200" value="20" aria-label="拿码数量">
          <button class="secondary" id="mint-btn">拿码</button>
        </div>
        <p class="small" id="mint-cost"></p>
        <div id="mint-result"></div>
      </div>

      <div class="panel">
        <h2>③ 进阶</h2>
        <button class="secondary" id="custom-toggle">提交自己的题库 JSON（定制模式）</button>
        <div id="custom-form"></div>
        <button class="secondary" id="export-btn">导出我的测试（单文件 HTML，自己部署用）</button>
        <button class="secondary" id="kit-download">下载创作工具包（一次性 ${yuan(p.COST_KIT_DOWNLOAD)} 元）</button>
      </div>

      <div class="panel">
        <h2>余额流水</h2>
        <ul class="ledger">${overview.ledger.map((e) => `<li><span>${e.delta > 0 ? "+" : ""}${yuan(e.delta)}</span> ${esc(e.reason)} <small>${esc(e.created_at)}</small></li>`).join("") || '<li class="small">暂无流水</li>'}</ul>
        <button class="back" id="logout">退出登录（换一个码）</button>
      </div>
      <p class="notice">免责声明：平台提供制作与托管工具；售卖、宣传与收款由创作者自行完成并自行负责合规，请勿声称科学诊断或承诺收益。</p>
    `));

    document.querySelector("#logout").addEventListener("click", () => { clearKey(); redeemView(); });
    document.querySelector("#kit-download").addEventListener("click", downloadKit);
    document.querySelector("#topup-btn").addEventListener("click", topUp);
    document.querySelector("#export-btn").addEventListener("click", exportTest);
    document.querySelector("#custom-toggle").addEventListener("click", () => {
      const box = document.querySelector("#custom-form");
      box.innerHTML = box.innerHTML ? "" : customFormHtml();
      if (box.innerHTML) document.querySelector("#custom-submit").addEventListener("click", submitCustom);
    });
    document.querySelector("#mint-btn").addEventListener("click", mint);
    document.querySelector("#mint-count").addEventListener("input", updateMintCost);
    updateMintCost();
    await loadSkeletons();
    renderProducts(overview.products);
  }

  function updateMintCost() {
    const count = Number(document.querySelector("#mint-count")?.value) || 0;
    const box = document.querySelector("#mint-cost");
    if (box) box.textContent = count > 0 ? `预计扣款 ${yuan(count * window.__PRICE_CODE__)} 元` : "";
  }

  function customFormHtml() {
    return `
      <textarea id="custom-json" class="custom-json" rows="10" placeholder='粘贴题库 JSON：{"title":…,"subtitle":…,"results":[…],"questions":[…]}，要求 12–16 题、6–8 个结果，评分只引用已声明结果 id（0–3 整数）。提交后服务端会做可达性与平衡校验。'></textarea>
      <button class="primary" id="custom-submit">校验并发布</button>`;
  }

  async function loadSkeletons() {
    const { data } = await api("/api/creator/skeletons");
    const list = document.querySelector("#skeleton-list");
    if (!data.ok || !data.skeletons.length) {
      list.innerHTML = '<p class="small">暂无可选主题，请联系平台方。</p>';
      return;
    }
    list.innerHTML = data.skeletons.map((s, i) => `
      <label class="skeleton-card">
        <input type="radio" name="skeleton" value="${esc(s.skeleton_id)}" ${i === 0 ? "checked" : ""}>
        <div><b>${esc(s.title)}</b><span class="small">${esc(s.subtitle)}</span><span class="small">${s.question_count} 题 · ${s.result_count} 个结果：${s.result_names.map(esc).join(" / ")}</span></div>
      </label>`).join("");
    document.querySelector("#skeleton-form").innerHTML = `
      <input id="host-title" class="gate-input" type="text" maxlength="40" placeholder="你的测试标题（可自定）" aria-label="测试标题">
      <input id="host-subtitle" class="gate-input" type="text" maxlength="80" placeholder="副标题（可自定）" aria-label="副标题">
      <button class="primary" id="host-btn">一键发布（扣额度）</button>
      <p class="gate-error" id="host-error" role="alert"></p>`;
    document.querySelector("#host-btn").addEventListener("click", hostSkeleton);
  }

  async function hostSkeleton() {
    const btn = document.querySelector("#host-btn");
    const error = document.querySelector("#host-error");
    const skeleton = document.querySelector('input[name="skeleton"]:checked')?.value;
    btn.disabled = true;
    const { status, data } = await api("/api/creator/host", {
      method: "POST",
      body: { mode: "skeleton", skeleton_id: skeleton, title: document.querySelector("#host-title").value, subtitle: document.querySelector("#host-subtitle").value },
    });
    btn.disabled = false;
    if (status === 200 && data.ok) {
      error.textContent = "";
      return dashboard(await refreshOverview());
    }
    error.textContent = data.error === "insufficient_credits"
      ? `额度不足，需要 ${data.required} 点，请购买创作额度包`
      : (data.errors?.[0] || data.error || "发布失败");
  }

  async function submitCustom() {
    const out = await api("/api/creator/host", { method: "POST", body: { mode: "custom", content: document.querySelector("#custom-json").value } });
    if (out.status === 200 && out.data.ok) return dashboard(await refreshOverview());
    const box = document.querySelector("#custom-form");
    box.insertAdjacentHTML("beforeend", `<p class="gate-error">${(out.data.errors || [out.data.error]).map(esc).join("；")}</p>`);
  }

  function renderProducts(products) {
    const box = document.querySelector("#my-products");
    box.innerHTML = products.map((p) => `
      <div class="product-row">
        <b>${esc(p.name)}</b>
        <a class="small" href="/t/${esc(p.product_id)}" target="_blank" rel="noopener">/t/${esc(p.product_id)}</a>
        <span class="small">${esc(p.created_at.slice(0, 10))}</span>
      </div>`).join("");
  }

  async function mint() {
    const product = document.querySelector("#mint-product")?.value;
    const count = Number(document.querySelector("#mint-count").value) || 1;
    const box = document.querySelector("#mint-result");
    if (!product) { box.innerHTML = '<p class="gate-error">先发布一个测试，再来铸码。</p>'; return; }
    const { status, data } = await api("/api/creator/mint", { method: "POST", body: { product_id: product, count } });
    if (status === 200 && data.ok) {
      box.innerHTML = `
        <p class="small">以下 ${data.codes.length} 个兑换码只显示一次，请立即复制保存：</p>
        <textarea class="custom-json" rows="${Math.min(data.codes.length, 8)}" readonly>${esc(data.codes.join("\n"))}</textarea>`;
      box.querySelector("textarea").select();
    } else {
      box.innerHTML = `<p class="gate-error">${{ not_your_product: "只能给自己的测试铸码" }[data.error] || data.error}</p>`;
    }
  }

  async function downloadKit() {
    const { status, data } = await api("/api/creator/kit", { method: "POST" });
    if (status === 200 && data.ok) {
      const blob = new Blob([data.kit], { type: "text/plain;charset=utf-8" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "MYTHIC-creator-kit.txt";
      a.click();
      URL.revokeObjectURL(a.href);
    } else {
      alert(data.error === "insufficient_credits" ? `额度不足，需要 ${data.required} 点` : data.error);
    }
  }

  boot();
})();

