    box.insertAdjacentHTML("beforeend", `<p class="gate-error">${(out.data.errors || [out.data.error]).map(esc).join("；")}</p>`);
  }

  function renderProducts(products) {
    const box = document.querySelector("#my-products");
    box.innerHTML = products.map((p) => `
      <div class="product-row">
        <b>${esc(p.name)}</b>
        <a class="small" href="/t/${esc(p.product_id)}" target="_blank" rel="noopener">/t/${esc(p.product_id)}</a>
        <span class="small">${esc(p.created_at.slice(0, 10))}</span>
      </div>`).join("");
  }

