      box.innerHTML = `<p class="gate-error">${{
        not_your_product: "只能给自己的测试拿码",
        insufficient_credits: `余额不足：需 ${yuan(data.required)} 元，当前 ${yuan(data.balance)} 元，请先充值`,
      }[data.error] || data.error}</p>`;
    }
  }

  async function topUp() {
    const input = document.querySelector("#topup-code");
    const code = (input?.value || "").trim();
    if (!code) return;
    const { status, data } = await api("/api/creator/topup", { method: "POST", body: { code } });
    if (status === 200 && data.ok) return dashboard(await refreshOverview());
    alert({ invalid_kit_code: "充值码不存在", kit_already_redeemed: "这个充值码已被使用" }[data.error] || `充值失败（${data.error}）`);
  }

  async function exportTest() {
    const product = document.querySelector("#mint-product")?.value;
    if (!product) { alert("先发布一个测试，再导出。"); return; }
    const key = getKey();
    const res = await fetch("/api/creator/export", {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-creator-key": key?.creator_key || "" },
      body: JSON.stringify({ product_id: product }),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      alert({ not_your_product: "只能导出自己的测试", unknown_test: "测试不存在" }[err.error] || `导出失败（${err.error || res.status}）`);
      return;
    }
    const blob = new Blob([await res.text()], { type: "text/html;charset=utf-8" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `${product}.html`;
    a.click();
    URL.revokeObjectURL(a.href);
  }

  async function downloadKit() {
    const { status, data } = await api("/api/creator/kit", { method: "POST" });
    if (status === 200 && data.ok) {
      const blob = new Blob([data.kit], { type: "text/plain;charset=utf-8" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = "MYTHIC-creator-kit.txt";
      a.click();
      URL.revokeObjectURL(a.href);
    } else {
      alert(data.error === "insufficient_credits" ? `额度不足，需要 ${data.required} 点` : data.error);
    }
  }

  boot();
})();

