await check("导出文件独立可跑：新 DOM 桩直接从内嵌数据出结果", async () => {
  const { installDom } = await import("./lib/dom-stub.mjs");
  const { sleep } = await import("./lib/suite.mjs");
  const dom = installDom({ pathname: "/standalone.html" });
  const html = globalThis.__EXPORT;
  const themeJson = html.match(/window\.__THEME__ = ([\s\S]*?);\n<\/script>/)[1];
  globalThis.document.createElement = globalThis.document.createElement; // noop
  // 把内嵌数据装进桩环境并执行 RUNNER 的评分段：直接 eval 到 window
  globalThis.window.__THEME__ = JSON.parse(themeJson.replace(/\\u003c/g, "<"));
  const runnerSrc = html.match(/<script>([\s\S]*?function selectWinner[\s\S]*?)<\/script>/)[1];
  new Function(runnerSrc.replace(/window\.__THEME__/g, "window.__THEME__"))();
  await sleep(120);
  assert(dom.appEl.querySelector("#start"), "独立包应渲染开始页");
