server.stderr.on("data", (d) => process.stderr.write(`[server] ${d}`));
// server 启动会生成 admin-key.txt；测试用固定 MYTHIC_ADMIN_KEY 覆盖。

// 走真实 admin.mjs CLI（和运营铸码同一条路径）
function adminCli(args) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [join(ROOT, "server", "admin.mjs"), ...args], { env: ENV, stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    let err = "";
    child.stdout.on("data", (d) => { out += d; });
    child.stderr.on("data", (d) => { err += d; });
    child.on("close", (code) => (code === 0 ? resolve(out) : reject(new Error(`admin.mjs ${args.join(" ")} -> ${err || out}`))));
  });
}

async function api(path, { method = "GET", body, creatorKey, adminKey } = {}) {
  const headers = { "Content-Type": "application/json" };
  if (creatorKey) headers["x-creator-key"] = creatorKey;
  if (adminKey) headers["x-admin-key"] = adminKey;
  const res = await fetch(`${BASE}${path}`, { method, headers, body: body ? JSON.stringify(body) : undefined });
  const text = await res.text();
  let data = null;
  try { data = JSON.parse(text); } catch { data = { raw: text }; }
  return { status: res.status, data };
}

