// 创作者工坊 — 额度制自助生产/托管的核心逻辑。
//
// 商业语义（对应 factory/BUSINESS_MODES.md 的 C/D 层自助化）：
//   · 老板在小红书店铺卖"创作额度包"，手动发货一个 CREATOR-… 码（admin 铸造）；
//   · 买家在 /creator 门户兑换码成为创作者，获得额度（credits）；
//   · 托管模式：创作者提交题库 JSON → 服务端按 custom-lite 围栏 + 评分完整性
//     校验 → 注册为新产品（默认模板，无独立皮肤）→ 扣额度；之后创作者在门户
//     里给自己的产品铸兑换码，拿去自己的渠道卖——收款与合规由创作者自负；
//   · 自助模式：下载创作工具包（SELLABLE skill 全套文本）→ 自己拿去用
//     AI 编码工具跑，扣一次性额度。
//
// 铁律继承：评分矩阵不出服务器（新内容文件写进 server/content/，web 根之外）；
// 每个结果必须可达（上线路径就做 lean-run 硬校验）；不假造结果。
import { randomBytes } from "node:crypto";
import { writeFileSync, readFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { selectWinner } from "./scoring.mjs";
import { normalizeCode, newCreatorKey, sha256 } from "./store.mjs";
import { reloadRegistry, loadSkeleton, productThemes } from "./products.mjs";
import { buildStandaloneHtml } from "./standalone.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const PRODUCTS_DIR = join(HERE, "content", "products");

/* --------------------------------------------------------------- 定价 ----
   余额单位是"分"（整数），避免浮点账目错乱；门户展示时除以 100 显示为元。
   码价就是平台的抽成：创作者预付批发价拿码，卖多卖少是他自己的事。 */
export const PRICING = {
  COST_HOST: 990,          // 托管发布一个测试：9.9 元
  COST_KIT_DOWNLOAD: 500,  // 一次性下载创作工具包：5 元
  PRICE_CODE: 300,         // 每个兑换码批发价：3 元（= 每单抽成）
  MAX_CODES_PER_MINT: 200,
};

export const yuan = (fen) => (fen / 100).toFixed(2).replace(/\.00$/, "");

// 创作者产品一律挂在 c- 命名空间下：与内部产品物理隔离，永不冲突。
const RESULT_ID_RE = /^[a-z][a-z0-9_-]{2,23}$/;

const FIXED_DISCLAIMER = "This is a cultural character-style experience, not a scientific personality assessment.";

export function newCreatorId() {
  return `c-${randomBytes(4).toString("hex")}`;
}

/* ------------------------------------------------------------ 内容校验 ----
   返回 { ok: true, theme } 或 { ok: false, errors: [...] }。
   校验就是上线质量门：不过校验的内容不会出现在任何 URL 上。 */
export function validateCreatorContent(input) {
  const errors = [];
  const fence = { questionMin: 12, questionMax: 16, resultMin: 6, resultMax: 8 };

  const results = Array.isArray(input?.results) ? input.results : [];
  const questions = Array.isArray(input?.questions) ? input.questions : [];
  if (results.length < fence.resultMin || results.length > fence.resultMax) {
    errors.push(`结果数必须 ${fence.resultMin}–${fence.resultCount ?? fence.resultMax} 个，当前 ${results.length}`);
  }
  if (questions.length < fence.questionMin || questions.length > fence.questionMax) {
    errors.push(`题目数必须 ${fence.questionMin}–${fence.questionMax} 题，当前 ${questions.length}`);
  }
  if (errors.length) return { ok: false, errors };

  // —— 结果 ——
  const ids = new Set();
  for (const r of results) {
    const id = String(r?.id || "");
    if (!RESULT_ID_RE.test(id)) errors.push(`结果 id "${id}" 不合法（小写字母开头的 slug，3–24 位）`);
    if (ids.has(id)) errors.push(`结果 id "${id}" 重复`);
    ids.add(id);
    for (const [field, min, max] of [["name", 1, 24], ["subtitle", 4, 60], ["reading", 20, 160], ["share_line", 4, 40]]) {
      const v = String(r?.[field] ?? "");
      if (v.length < min || v.length > max) errors.push(`结果 "${id}" 的 ${field} 长度须 ${min}–${max}，当前 ${v.length}`);
    }
  }
  if (results.length && ids.size !== results.length) return { ok: false, errors };

  // —— 题目 ——
  questions.forEach((q, i) => {
    const text = String(q?.question ?? "").trim();
    if (text.length < 6 || text.length > 120) errors.push(`第 ${i + 1} 题题干长度须 6–120，当前 ${text.length}`);
    const options = Array.isArray(q?.options) ? q.options : [];
    if (options.length !== 3) errors.push(`第 ${i + 1} 题必须恰好 3 个选项，当前 ${options.length}`);
    options.forEach((o, j) => {
      const optText = String(o?.text ?? "").trim();
      if (optText.length < 2 || optText.length > 80) errors.push(`第 ${i + 1} 题选项 ${j + 1} 文本长度须 2–80`);
      const scores = o?.scores ?? {};
      const entries = Object.entries(scores);
      if (!entries.length) errors.push(`第 ${i + 1} 题选项 ${j + 1} 没有任何计分`);
      for (const [rid, pts] of entries) {
        if (!ids.has(rid)) errors.push(`第 ${i + 1} 题选项 ${j + 1} 给未声明的结果 "${rid}" 计分`);
        if (!Number.isInteger(pts) || pts < 0 || pts > 3) errors.push(`第 ${i + 1} 题选项 ${j + 1} 的 "${rid}" 分值须为 0–3 整数，当前 ${pts}`);
      }
    });
  });
  if (errors.length) return { ok: false, errors };

  // —— 评分可达性（上线路径就硬校验，和 tools/lib/reachability.mjs 同一逻辑）——
  // normalization_bounds 由服务端从矩阵本身推导，杜绝创作者手填错。
  const bounds = {};
  for (const id of ids) {
    let min = 0;
    let max = 0;
    for (const q of questions) {
      const values = q.options.map((o) => o.scores[id] || 0);
      min += Math.min(...values);
      max += Math.max(...values);
    }
    bounds[id] = { minimum: min, maximum: max };
  }
  const theme = {
    id: "__validation__",
    title: String(input.title || "").trim(),
    subtitle: String(input.subtitle || "").trim(),
    disclaimer: FIXED_DISCLAIMER,
    results,
    questions,
    scoring: { method: "range_normalized_sum", normalization_bounds: bounds },
  };
  if (theme.title.length < 2 || theme.title.length > 40) errors.push(`标题长度须 2–40，当前 ${theme.title.length}`);
  if (theme.subtitle.length < 4 || theme.subtitle.length > 80) errors.push(`副标题长度须 4–80，当前 ${theme.subtitle.length}`);

  // 每个结果：全题最偏它的确定性作答必须精确命中（不许靠平局裁决获胜）。
  for (const id of ids) {
    const full = questions.map((q) =>
      q.options.map((o, i) => ({ i, s: o.scores[id] || 0 })).sort((a, b) => b.s - a.s)[0].i);
    const verdict = selectWinner(theme, full);
    if (verdict.winnerId !== id) {
      errors.push(`结果 "${id}" 不可达：全力倾向作答会命中 "${verdict.winnerId}"（评分矩阵要改）`);
    }
  }

  // 随机作答不出现支配结果：均匀随机 300 局，每个结果至少赢 5 次。
  let seed = 20261108;
  const rand = () => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed / 0x7fffffff;
  };
  const wins = Object.fromEntries([...ids].map((id) => [id, 0]));
  for (let run = 0; run < 300; run += 1) {
    const answers = questions.map((q) => Math.floor(rand() * q.options.length));
    wins[selectWinner(theme, answers).winnerId] += 1;
  }
  for (const [id, n] of Object.entries(wins)) {
    if (n < 5) errors.push(`结果 "${id}" 随机作答 300 局仅胜 ${n} 次——疑似被支配结果，需要重新平衡`);
  }

  // 编码完整性：拒绝任何 U+FFFD（替换字符 = 已经烂掉的文本）。
  const scan = JSON.stringify({ results, questions, title: theme.title, subtitle: theme.subtitle });
  if (scan.includes("\uFFFD")) errors.push("内容里存在损坏字符（U+FFFD），请检查来源文件的编码");

  return errors.length ? { ok: false, errors } : { ok: true, theme };
}

/* ------------------------------------------------------------ 产品注册 ----
   两种发布模式，同一个出口：
   · 骨架模式（一键发布的主路径）：loadSkeleton(id) 取老板离线预产的题库，
     客户只能改标题/副标题——内容零改动，质量 100% 继承工厂质量门；
   · 定制模式：创作者自己提交完整题库 JSON，走上面的全部校验。
   注册 = 新增目录（server/content/products/c-…/），写两个文件：
   content.json（完整题库，web 根之外）+ product.json（清单）。
   写完调 reloadRegistry 让运行中的服务立即认识新产品。 */
export function hostCreatorProduct({ mode, skeleton, overrides, customContent, reloadRegistry }) {
  let content;
  if (mode === "skeleton") {
    // 骨架来自服务端白名单目录（products.loadSkeleton），不接受调用方提供的内容体；
    // 合并标题后仍过一遍同一质量门——骨架是预验证的，双保险不上线垃圾。
    if (!skeleton) return { ok: false, errors: ["骨架不存在或已下架"] };
    content = {
      ...skeleton,
      title: String(overrides?.title || skeleton.title).trim(),
      subtitle: String(overrides?.subtitle || skeleton.subtitle).trim(),
    };
    const verdict = validateCreatorContent(content);
    if (!verdict.ok) return { ok: false, errors: [`骨架内容未通过质量门（应不可能，请检查 skeletons/）：${verdict.errors[0]}`] };
    content = verdict.theme;
  } else if (mode === "custom") {
    const verdict = validateCreatorContent(customContent || {});
    if (!verdict.ok) return { ok: false, errors: verdict.errors };
    content = verdict.theme;
  } else {
    return { ok: false, errors: [`未知发布模式 "${mode}"（skeleton | custom）`] };
  }

  if (content.title.length < 2 || content.title.length > 40) return { ok: false, errors: ["标题长度须 2–40"] };
  if (content.subtitle.length < 4 || content.subtitle.length > 80) return { ok: false, errors: ["副标题长度须 4–80"] };

  const productId = newProductId();
  const dir = join(PRODUCTS_DIR, productId);
  mkdirSync(dir, { recursive: true });
  const productManifest = {
    product_id: productId,
    type: "single",
    name: content.title,
    content_file: "./content.json",
    theme_ids: [productId],
    created_via: mode === "skeleton" ? "creator-portal-skeleton" : "creator-portal-custom",
  };
  const theme = { ...content, id: productId };
  writeFileSync(join(dir, "content.json"), JSON.stringify({ collection_title: content.title, themes: [theme] }, null, 2) + "\n", "utf8");
  writeFileSync(join(dir, "product.json"), JSON.stringify(productManifest, null, 2) + "\n", "utf8");
  reloadRegistry();
  return { ok: true, productId, manifest: productManifest };
}

function newProductId() {
  for (;;) {
    const id = `c-${randomBytes(4).toString("hex")}`;
    if (!existsSync(join(PRODUCTS_DIR, id))) return id;
  }
}

/* --------------------------------------------------------- 门户编排层 ----
   store 由调用方（server.mjs / 测试）注入，本模块不持有全局状态。
   每个函数返回 { status, body }，直接映射成 HTTP 响应。 */

// 兑换创作包码 → 开户。key 只在本次响应里出现一次，之后只存哈希。
export function redeemKitForNewCreator(store, body) {
  const codeKey = normalizeCode(body?.code);
  if (!codeKey || !codeKey.startsWith("CREATOR")) {
    return { status: 400, body: { ok: false, error: "invalid_kit_code" } };
  }
  const kit = store.findKit(codeKey);
  if (!kit) return { status: 404, body: { ok: false, error: "invalid_kit_code" } };
  const creatorId = newCreatorId();
  const key = newCreatorKey();
  // redeemKit 是原子更新（redeemed=0 才成功），并发双花在这里被挡下
  const claimed = store.redeemKit(codeKey, creatorId);
  if (!claimed) return { status: 409, body: { ok: false, error: "kit_already_redeemed" } };
  // 建户余额为 0，入账一律走 ledger（单一事实来源，避免双记）
  store.createCreator(creatorId, sha256(key), 0);
  store.applyCredits(creatorId, claimed.credits, "kit-redeem", kit.code);
  return { status: 200, body: { ok: true, creator_id: creatorId, creator_key: key, credits: claimed.credits } };
}

// x-creator-key 鉴权；命中返回创作者行，否则返回要直接回给客户端的错误。
export function authCreator(store, req) {
  const key = String(req.headers["x-creator-key"] || "").trim();
  if (!key || key.length > 80) return { error: { status: 401, body: { ok: false, error: "creator_auth_required" } } };
  const creator = store.creatorByKey(sha256(key));
  if (!creator) return { error: { status: 401, body: { ok: false, error: "creator_auth_required" } } };
  store.creatorTouch(creator.creator_id);
  return { creator };
}

export function creatorOverview(store, creator) {
  return {
    status: 200,
    body: {
      ok: true,
      creator_id: creator.creator_id,
      name: creator.name,
      credits: creator.credits,
      pricing: PRICING,
      products: ownProducts(store, creator.creator_id),
      ledger: store.creatorLedger(creator.creator_id, 20),
    },
  };
}

function ownProducts(store, creatorId) {
  return store.creatorProducts(creatorId);
}

// 托管发布：骨架（一键）或定制（全量校验），扣额度，注册产品。
export function hostProduct(store, creator, body) {
  const mode = body?.mode === "custom" ? "custom" : "skeleton";
  let result;
  if (mode === "skeleton") {
    result = hostCreatorProduct({ mode, skeleton: loadSkeleton(body?.skeleton_id), overrides: { title: body?.title, subtitle: body?.subtitle }, reloadRegistry });
  } else {
    let custom = body?.content;
    if (typeof custom === "string") {
      try { custom = JSON.parse(custom); } catch { return { status: 400, body: { ok: false, error: "content_not_json" } }; }
    }
    result = hostCreatorProduct({ mode, customContent: custom, reloadRegistry });
  }
  if (!result.ok) return { status: 400, body: { ok: false, error: "content_rejected", errors: result.errors } };

  const debited = store.applyCredits(creator.creator_id, -PRICING.COST_HOST, "host-product", result.productId);
  if (debited === null) {
    // 额度不足：回滚刚写的目录，保持"扣不到款就没有产品"
    rmSync(join(PRODUCTS_DIR, result.productId), { recursive: true, force: true });
    reloadRegistry();
    return { status: 402, body: { ok: false, error: "insufficient_credits", required: PRICING.COST_HOST } };
  }
  store.setCreatorProduct(creator.creator_id, result.productId, result.manifest.name);
  return { status: 200, body: { ok: true, product_id: result.productId, name: result.manifest.name, credits_left: debited, test_url: `/t/${result.productId}` } };
}

// 给自己的产品铸兑换码：按批发价从余额扣（码价 = 平台每单抽成，预付制）。
export function mintCodes(store, creator, body) {
  const productId = String(body?.product_id || "");
  if (!store.creatorOwnsProduct(creator.creator_id, productId)) {
    return { status: 403, body: { ok: false, error: "not_your_product" } };
  }
  const count = Math.min(Math.max(Number(body?.count) || 1, 1), PRICING.MAX_CODES_PER_MINT);
  const cost = count * PRICING.PRICE_CODE;
  const left = store.applyCredits(creator.creator_id, -cost, "mint-codes", `${productId}×${count}`);
  if (left === null) {
    return { status: 402, body: { ok: false, error: "insufficient_credits", required: cost, balance: creator.credits } };
  }
  const codes = store.createCodes(count, productId, `creator:${creator.creator_id}`);
  return { status: 200, body: { ok: true, product_id: productId, codes, cost, credits_left: left } };
}

// 充值码自兑：已登录创作者把充值码变余额（新用户走 redeemKit 开户）。
export function topUp(store, creator, body) {
  const codeKey = normalizeCode(body?.code);
  if (!codeKey || !codeKey.startsWith("CREATOR")) {
    return { status: 400, body: { ok: false, error: "invalid_kit_code" } };
  }
  const kit = store.findKit(codeKey);
  if (!kit) return { status: 404, body: { ok: false, error: "invalid_kit_code" } };
  const claimed = store.redeemKit(codeKey, creator.creator_id);
  if (!claimed) return { status: 409, body: { ok: false, error: "kit_already_redeemed" } };
  const left = store.applyCredits(creator.creator_id, claimed.credits, "topup", kit.code);
  return { status: 200, body: { ok: true, added: claimed.credits, credits_left: left } };
}

// 路 2 交付物：导出自己测试的单文件 HTML（自包含，任何静态托管可跑）。
export function exportStandalone(store, creator, body, { getThemeFn }) {
  const productId = String(body?.product_id || "");
  if (!store.creatorOwnsProduct(creator.creator_id, productId)) {
    return { status: 403, body: { ok: false, error: "not_your_product" } };
  }
  const themes = getThemeFn(productId);
  if (!themes?.length) return { status: 404, body: { ok: false, error: "unknown_test" } };
  return { status: 200, html: buildStandaloneHtml(themes[0]), filename: `${productId}.html` };
}

// D 层工具包：一次性扣额度下载。
export function downloadKit(store, creator) {
  if (store.creatorLedger(creator.creator_id, 100).some((e) => e.reason === "kit-download")) {
    return { status: 200, body: { ok: true, kit: buildCreatorKit(), repeat: true } };
  }
  const debited = store.applyCredits(creator.creator_id, -PRICING.COST_KIT_DOWNLOAD, "kit-download", "self-serve");
  if (debited === null) {
    return { status: 402, body: { ok: false, error: "insufficient_credits", required: PRICING.COST_KIT_DOWNLOAD } };
  }
  return { status: 200, body: { ok: true, kit: buildCreatorKit() } };
}

/* ----------------------------------------------------------- 工具包下载 ----
   D 层交付物：SELLABLE_TEST_CREATOR.md + brief schema + 模板，
   拼成一个自包含文本包（零依赖，不做 zip；门户提供分段复制）。 */
export function buildCreatorKit() {
  const factory = join(HERE, "..", "factory");
  const parts = [
    ["MYTHIC 创作工具包 — 使用说明.txt", KIT_README],
    ["SELLABLE_TEST_CREATOR.md", readFile(join(factory, "skills", "SELLABLE_TEST_CREATOR.md"))],
    ["brief.schema.json", readFile(join(factory, "brief.schema.json"))],
    ["PROJECT_BRIEF.template.md", readFile(join(factory, "templates", "PROJECT_BRIEF.template.md"))],
    ["PRODUCTION_CHECKLIST.template.md", readFile(join(factory, "templates", "PRODUCTION_CHECKLIST.template.md"))],
    ["example-brief.json", readFile(join(factory, "examples", "example-brief.json"))],
  ];
  const banner = (name) => `\n${"=".repeat(72)}\n== 文件：${name}\n${"=".repeat(72)}\n`;
  return parts.map(([name, body]) => `${banner(name)}\n${body}`).join("\n");
}

function readFile(path) {
  return readFileSync(path, "utf8");
}

const KIT_README = `这份工具包是"测试生产方法本身"的完整交付物（对应工厂 D 层）。
你将得到：可售测试的完整生产 SOP（五阶段 + 质量门）、brief schema、生产清单模板。

怎么用：
1. 把 "== 文件：xxx ==" 分隔的各段拆存成同名文件；
2. 在你自己的电脑上装一个 AI 编码工具（Claude Code / Codex / GLM Coding 等）；
3. 开一个空目录，把所有文件放进去，按 SELLABLE_TEST_CREATOR.md 的开场白启动；
4. 题库做完后，回到 /creator 门户用"托管发布"提交 JSON，或完全自己运营。

红线（不可协商）：
- 不做医疗/心理诊断声称；结果 id 用稳定 slug；
- 不复制他人题目、译文、剧照；引文先核实来源；
- 工具包不包含我们的服务器凭据或任何私有数据。
`;

