  const creatorTheme = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", globalThis.__PRODUCT, "content.json"), "utf8")).themes[0];
  installApiStub({ productId: globalThis.__PRODUCT, productName: "测试", themes: [creatorTheme], code: globalThis.__BUYER_CODE2, secret: "[REDACTED:SECRET_ASSIGNMENT]" });
