  assert(dom.appEl.querySelector("#cover-start"), "专属链接应自动兑换直达封面");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1"));
  assert(stored && stored.code === globalThis.__BUYER_CODE2, `license 应存专属码: ${stored && stored.code}`);
