/* 创作者工坊 · 全流程 E2E。
 *
 * 真实 server.mjs（一次性数据目录、临时端口）+ 真实 admin.mjs CLI 驱动完整商业闭环：
 * 充值码开户 → 骨架一键发布（扣费）→ 自助拿码（按码价扣余额）→
 * 买家兑换拿到的码 → 评分走真实 scoring.mjs → 单文件导出 →
 * 定制模式校验拒绝 → 权限与余额边界 → 专属链接 ?code= 自动填码（DOM 桩）。
 *
 * Run: node tools/test-creator-portal.mjs
 */
import { spawn } from "node:child_process";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { setTimeout as sleep } from "node:timers/promises";
import { createServer as tcpProbe } from "node:net";
import { readdirSync, readFileSync } from "node:fs";
import { selectWinner } from "../server/scoring.mjs";
import { productThemes } from "../server/products.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const results = [];
const check = async (name, fn) => {
  try {
    const detail = await fn();
    results.push({ ok: true, name, d: detail || "" });
  } catch (e) {
    results.push({ ok: false, name, d: e.message });
  }
};
const assert = (c, m) => { if (!c) throw new Error(m); };

function freePort() {
  return new Promise((resolve, reject) => {
    const probe = (attempt) => {
      const candidate = 9300 + Math.floor(Math.random() * 300);
      const srv = tcpProbe();
      srv.once("error", () => { if (attempt < 20) probe(attempt + 1); else reject(new Error("no free port")); });
      srv.listen(candidate, () => srv.close(() => resolve(candidate)));
    };
    probe(0);
  });
}

const PORT = await freePort();
const DATA_DIR = mkdtempSync(join(tmpdir(), "mythic-creator-test-"));
const BASE = `http://127.0.0.1:${PORT}`;
const ENV = { ...process.env, MYTHIC_PORT: String(PORT), MYTHIC_DATA_DIR: DATA_DIR, MYTHIC_ADMIN_KEY: "[REDACTED:SECRET_ASSIGNMENT]", MYTHIC_HOST: "127.0.0.1", MYTHIC_RATE_LIMIT: "1000" };
const server = spawn(process.execPath, [join(ROOT, "server", "server.mjs")], { env: ENV, stdio: ["ignore", "ignore", "pipe"] });
server.stderr.on("data", (d) => process.stderr.write(`[server] ${d}`));
// server 启动会生成 admin-key.txt；测试用固定 MYTHIC_ADMIN_KEY 覆盖。

// 走真实 admin.mjs CLI（和运营铸码同一条路径）
function adminCli(args) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [join(ROOT, "server", "admin.mjs"), ...args], { env: ENV, stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    let err = "";
    child.stdout.on("data", (d) => { out += d; });
    child.stderr.on("data", (d) => { err += d; });
    child.on("close", (code) => (code === 0 ? resolve(out) : reject(new Error(`admin.mjs ${args.join(" ")} -> ${err || out}`))));
  });
}

async function api(path, { method = "GET", body, creatorKey, adminKey } = {}) {
  const headers = { "Content-Type": "application/json" };
  if (creatorKey) headers["x-creator-key"] = creatorKey;
  if (adminKey) headers["x-admin-key"] = adminKey;
  const res = await fetch(`${BASE}${path}`, { method, headers, body: body ? JSON.stringify(body) : undefined });
  const text = await res.text();
  let data = null;
  try { data = JSON.parse(text); } catch { data = { raw: text }; }
  return { status: res.status, data };
}

for (let i = 0; i < 40; i += 1) {
  try { await fetch(`${BASE}/t/greek_goddess`); break; } catch { await sleep(250); }
}

const ADMIN = "creator-test-admin";
const yuan = (fen) => (fen / 100).toFixed(2);

/* ------------------------------------------------ ① 充值码与开户 ---- */
await check("admin 铸充值码：100 元/枚", async () => {
  const out = await adminCli(["kits", "2", "--yuan", "100", "--note", "e2e-批次"]);
  const codes = out.trim().split("\n").filter((l) => l.startsWith("CREATOR-"));
  assert(codes.length === 2, `期望 2 枚充值码，实际 ${codes.length}`);
  globalThis.__KIT_A = codes[0];
  globalThis.__KIT_B = codes[1];
  return codes[0];
});

await check("错误充值码 → 404；正确充值码开户 → 200 + 余额 100 元", async () => {
  const bad = await api("/api/creator/redeem", { method: "POST", body: { code: "CREATOR-ZZZZZ-ZZZZZ" } });
  assert(bad.status === 404, `错误码应 404，实际 ${bad.status}`);
  const good = await api("/api/creator/redeem", { method: "POST", body: { code: globalThis.__KIT_A } });
  assert(good.status === 200 && good.data.ok, `开户失败: ${JSON.stringify(good.data)}`);
  assert(good.data.credits === 10000, `余额应为 10000 分，实际 ${good.data.credits}`);
  assert(String(good.data.creator_key).startsWith("crk_"), "creator_key 格式不对");
  globalThis.__CREATOR_KEY = good.data.creator_key;
  globalThis.__CREATOR_ID = good.data.creator_id;
  return `creator ${good.data.creator_id}`;
});

await check("同一充值码二次兑换 → 409（防双花）", async () => {
  const again = await api("/api/creator/redeem", { method: "POST", body: { code: globalThis.__KIT_A } });
  assert(again.status === 409, `应 409，实际 ${again.status}`);
  return "blocked";
});

await check("无凭证访问 overview → 401；有凭证 → 余额与流水", async () => {
  const anon = await api("/api/creator/overview");
  assert(anon.status === 401, `无凭证应 401，实际 ${anon.status}`);
  const authed = await api("/api/creator/overview", { creatorKey: globalThis.__CREATOR_KEY });
  assert(authed.status === 200 && authed.data.credits === 10000, `余额异常: ${JSON.stringify(authed.data)}`);
  assert(authed.data.ledger.some((e) => e.reason === "kit-redeem"), "流水缺 kit-redeem 记录");
  return "auth ok";
});

/* ------------------------------------------------ ② 骨架一键发布 ---- */
await check("骨架目录可见（2 套）且不泄漏评分矩阵", async () => {
  const { status, data } = await api("/api/creator/skeletons", { creatorKey: globalThis.__CREATOR_KEY });
  assert(status === 200 && data.skeletons.length === 2, `骨架应为 2 套，实际 ${data.skeletons?.length}`);
  const raw = JSON.stringify(data);
  assert(!raw.includes("scores"), "骨架目录泄漏了评分矩阵");
  return data.skeletons.map((s) => s.skeleton_id).join(", ");
});

await check("一键发布：扣 9.9 元，产品注册成功", async () => {
  const { status, data } = await api("/api/creator/host", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { mode: "skeleton", skeleton_id: "late-night-store", title: "深夜便利店 · 测试小张版", subtitle: "12 个深夜小抉择，看你是哪种客人。" },
  });
  assert(status === 200 && data.ok, `发布失败: ${JSON.stringify(data)}`);
  assert(String(data.product_id).startsWith("c-"), `产品 id 应在 c- 命名空间: ${data.product_id}`);
  assert(data.credits_left === 10000 - 990, `余额应为 ${10000 - 990}，实际 ${data.credits_left}`);
  globalThis.__PRODUCT = data.product_id;
  return `/t/${data.product_id}`;
});

await check("新产品立即可访问：/t/<id> 200，/api/content 已脱敏且用覆盖标题", async () => {
  const page = await fetch(`${BASE}/t/${globalThis.__PRODUCT}`);
  assert(page.status === 200, `页面 ${page.status}`);
  const content = await api(`/api/content?test_id=${globalThis.__PRODUCT}`);
  assert(content.status === 200, `content ${content.status}`);
  const theme = content.data.themes[0];
  assert(theme.title === "深夜便利店 · 测试小张版", `标题覆盖失败: ${theme.title}`);
  assert(!JSON.stringify(content.data).includes("normalization_bounds"), "content 泄漏评分边界");
  assert(theme.questions[0].options.every((o) => !("scores" in o)), "content 泄漏评分矩阵");
  return "sanitized";
});

await check("余额不足发布 → 402 且不落任何产品目录", async () => {
  // 把余额耗到 < 9.9：拿一批码
  await api("/api/creator/mint", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { product_id: globalThis.__PRODUCT, count: 20 } }); // -6000
  const before = await api("/api/creator/overview", { creatorKey: globalThis.__CREATOR_KEY });
  const balance = before.data.credits; // 10000-990-6000 = 3010
  assert(balance === 3010, `余额应为 3010，实际 ${balance}`);
  const { readdirSync } = await import("node:fs");
  const products = readdirSync(join(ROOT, "server", "content", "products")).length;
  const broke = await api("/api/creator/host", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { mode: "custom", content: { title: "穷", subtitle: "付不起", results: [], questions: [] } },
  });
  // 定制内容先校验后扣费：这份内容本身不合法，应 400 而不是 402 —— 换个合法但余额不足的场景
  assert(broke.status === 400, `不合法内容应 400，实际 ${broke.status}`);
  // 直接把余额扣光再试合法发布
  await api("/api/creator/mint", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { product_id: globalThis.__PRODUCT, count: 10 } }); // -3000 → 10 分
  const poor = await api("/api/creator/host", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { mode: "skeleton", skeleton_id: "recharge-station", title: "余额不足的发布", subtitle: "应当被 402 拒绝。" },
  });
  assert(poor.status === 402, `应 402，实际 ${poor.status}`);
  const after = readdirSync(join(ROOT, "server", "content", "products")).length;
  assert(after === products, "402 时不应注册新产品目录");
  await adminCli(["credit", globalThis.__CREATOR_ID, "+9.9", "--note", "e2e 补充"]);
  return "refunded";
});

/* ------------------------------------------------ ③ 拿码（抽成） ---- */
await check("拿码按码价扣余额；给别人的产品拿码 → 403", async () => {
  const { status, data } = await api("/api/creator/mint", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { product_id: globalThis.__PRODUCT, count: 3 },
  });
  assert(status === 200 && data.ok, `拿码失败: ${JSON.stringify(data)}`);
  assert(data.codes.length === 3, "应 3 个码");
  assert(data.cost === 900, `应扣 900 分（3 元 × 3），实际 ${data.cost}`);
  const foreign = await api("/api/creator/mint", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { product_id: "greek_goddess", count: 1 },
  });
  assert(foreign.status === 403, `拿别人的产品应 403，实际 ${foreign.status}`);
  globalThis.__BUYER_CODE = data.codes[0];
  globalThis.__BUYER_CODE2 = data.codes[1];
  return `cost ${data.cost} 分`;
});

await check("拿码数量钳制 200；余额不足 → 402 报缺口", async () => {
  // 999 个 → 服务端先钳到 200 → 200 × 300 = 60000 分，余额不够 → 402 并报出缺口
  const huge = await api("/api/creator/mint", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { product_id: globalThis.__PRODUCT, count: 999 } });
  assert(huge.status === 402 && huge.data.required === 60000, `应 402 报 60000 分（钳到 200 后的缺口），实际 ${JSON.stringify(huge.data)}`);
  return "capped + guarded";
});

/* ------------------------------------------------ ④ 买家全流程 ---- */
await check("买家兑换拿到的码 → 激活 → 评分命中声明结果", async () => {
  const redeem = await api("/api/redeem", { method: "POST", body: { code: globalThis.__BUYER_CODE } });
  assert(redeem.status === 200 && redeem.data.ok, `买家兑换失败: ${JSON.stringify(redeem.data)}`);
  assert(redeem.data.product_id === globalThis.__PRODUCT, "码应绑定创作者产品");
  // 测试进程的注册表是启动时快照，新产品在 server 进程注册 —— 直接读私有内容文件
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", globalThis.__PRODUCT, "content.json"), "utf8"));
  const theme = raw.themes[0];
  const target = theme.results[0].id;
  const answers = theme.questions.map((q) =>
    q.options.map((o, i) => ({ i, s: o.scores[target] || 0 })).sort((a, b) => b.s - a.s)[0].i);
  const score = await api("/api/score", {
    method: "POST",
    body: { test_id: globalThis.__PRODUCT, theme: globalThis.__PRODUCT, answers, code: globalThis.__BUYER_CODE, secret: redeem.data.secret },
  });
  assert(score.status === 200 && score.data.ok, `评分失败: ${JSON.stringify(score.data)}`);
  assert(score.data.winnerId === target, `期望 ${target}，实际 ${score.data.winnerId}`);
  assert(score.data.result.reading, "结果正文缺失");
  return `winner=${score.data.winnerId}`;
});

/* ------------------------------------------------ ⑤ 门户与导出 ---- */
await check("门户静态页可访问", async () => {
  const page = await fetch(`${BASE}/creator`);
  assert(page.status === 200, `/creator ${page.status}`);
  const html = await page.text();
  assert(html.includes("creator.js"), "门户应挂 creator.js");
  const js = await fetch(`${BASE}/creator.js`);
  assert(js.status === 200, `creator.js ${js.status}`);
  return "static ok";
});

await check("单文件导出：可独立运行的 HTML（内嵌矩阵与判定）", async () => {
  const res = await fetch(`${BASE}/api/creator/export`, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-creator-key": globalThis.__CREATOR_KEY },
    body: JSON.stringify({ product_id: globalThis.__PRODUCT }),
  });
  assert(res.status === 200, `导出 ${res.status}`);
  const html = await res.text();
  assert(html.startsWith("<!DOCTYPE html>"), "应是完整 HTML");
  assert(html.includes("深夜便利店 · 测试小张版"), "标题未内嵌");
  assert(html.includes("function selectWinner"), "评分判定未内嵌");
  assert(html.includes("normalization_bounds"), "归一化边界未内嵌");
  assert(!html.includes("crk_") && !html.includes("creator-test-admin"), "泄漏平台凭据");
  globalThis.__EXPORT = html;
  return `${(html.length / 1024).toFixed(0)} KB`;
});

await check("定制模式：未声明结果 id → 拒绝并列出错误", async () => {
  const bad = await api("/api/creator/host", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { mode: "custom", content: { title: "坏内容", subtitle: "引用了不存在的结果", results: [{ id: "abc", name: "A", subtitle: "副题在这里啊啊", reading: "正文正文正文正文正文正文正文正文正文" }], questions: [] } },
  });
  assert(bad.status === 400 && bad.data.error === "content_rejected", `应 400 content_rejected，实际 ${bad.status}`);
  assert((bad.data.errors || []).some((e) => e.includes("abc")), "错误信息应指出非法结果 id");
  return `${bad.data.errors.length} 条校验错误`;
});

await check("充值码自兑：topup 到账；重复使用被拒", async () => {
  const ok = await api("/api/creator/topup", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { code: globalThis.__KIT_B } });
  assert(ok.status === 200 && ok.data.ok, `充值失败: ${JSON.stringify(ok.data)}`);
  assert(ok.data.added === 10000, `应 +10000 分，实际 ${ok.data.added}`);
  const again = await api("/api/creator/topup", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { code: globalThis.__KIT_B } });
  assert(again.status === 409, "重复充值码应 409");
  return `+${yuan(ok.data.added)} 元`;
});

/* ---------------------- ⑥ 浏览器行为（DOM 桩，放最后：会替换全局 fetch） ---- */
await check("专属链接 ?code= 自动填码：DOM 桩直达封面", async () => {
  const { installDom } = await import("./lib/dom-stub.mjs");
  const { installApiStub } = await import("./lib/api-stub.mjs");
  const { bootApp, unbootSkinApp } = await import("./lib/boot-app.mjs");
  const { sleep } = await import("./lib/suite.mjs");
  const dom = installDom({ pathname: `/t/${globalThis.__PRODUCT}`, search: `?code=${globalThis.__BUYER_CODE2}` });
  const creatorTheme = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", globalThis.__PRODUCT, "content.json"), "utf8")).themes[0];
  installApiStub({ productId: globalThis.__PRODUCT, productName: "测试", themes: [creatorTheme], code: globalThis.__BUYER_CODE2, secret: "[REDACTED:SECRET_ASSIGNMENT]" });
  await bootApp();
  await sleep(300);
  assert(dom.appEl.querySelector("#cover-start"), "专属链接应自动兑换直达封面");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1"));
  assert(stored && stored.code === globalThis.__BUYER_CODE2, `license 应存专属码: ${stored && stored.code}`);
  unbootSkinApp();
  return "one-click";
});

await check("导出文件独立可跑：新 DOM 桩直接从内嵌数据渲染题目", async () => {
  const { installDom } = await import("./lib/dom-stub.mjs");
  const { sleep } = await import("./lib/suite.mjs");
  const dom = installDom({ pathname: "/standalone.html" });
  const html = globalThis.__EXPORT;
  const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => m[1]);
  const themeSrc = scripts.find((s) => s.includes("__THEME__"));
  const runnerSrc = scripts.find((s) => s.includes("function selectWinner"));
  assert(themeSrc && runnerSrc, "导出包缺内嵌脚本");
  new Function(themeSrc)(); // 设置 window.__THEME__
  new Function(runnerSrc)(); // 渲染 + 判定
  await sleep(120);
  assert(dom.appEl.querySelector("#start"), "独立包应渲染开始页");
  dom.appEl.querySelector("#start").click();
  await sleep(60);
  assert(dom.appEl.querySelectorAll(".option").length === 3, "独立包题目渲染异常");
  return "standalone ok";
});

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n创作者工坊 · 全流程 E2E\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
server.kill();
rmSync(DATA_DIR, { recursive: true, force: true });
process.exit(failures.length ? 1 : 0);

