await check("定制模式：引用未声明结果 id → 拒绝并指出 id", async () => {
  // 用合法骨架做底，把一个选项的计分改成未声明的 "ghost" —— 校验器必须抓住
  const skel = JSON.parse(readFileSync(join(ROOT, "server", "content", "skeletons", "late-night-store.json"), "utf8"));
  skel.questions[0].options[0].scores = { ghost: 3 };
  const bad = await api("/api/creator/host", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { mode: "custom", content: skel },
  });
  assert(bad.status === 400 && bad.data.error === "content_rejected", `应 400 content_rejected，实际 ${bad.status}`);
  assert((bad.data.errors || []).some((e) => e.includes("ghost")), `错误应指出 ghost: ${JSON.stringify(bad.data.errors)}`);
  return `${bad.data.errors.length} 条校验错误`;
});

