// 单文件测试包生成器 — 路 2 的交付物。
//
// 给创作者导出一个自包含的 HTML：题目、评分矩阵、结果正文全部内嵌，
// 评分逻辑与 server/scoring.mjs 的 selectWinner 逐字节同构（含三级平局裁决），
// 任何静态托管（GitHub Pages / Vercel / 虚拟主机）扔上去即可运行。
//
// 这是创作者自己的产品，评分矩阵放前端没有防抄问题； MYTHIC 的服务器设施
// （许可、防抄、评分服务）一概不进这个文件。
const DISCLAIMER = "This is a cultural character-style experience, not a scientific personality assessment.";

const RUNNER = `
function rawScores(quiz, answers) {
  const scores = {};
  (quiz.results || []).forEach((r) => { scores[r.id] = 0; });
  (quiz.questions || []).forEach((q, qi) => {
    const option = q.options[answers[qi]];
    if (!option || !option.scores) return;
    Object.entries(option.scores).forEach(([rid, pts]) => {
      if (Object.prototype.hasOwnProperty.call(scores, rid)) scores[rid] += pts;
    });
  });
  return scores;
}
function normalizeScore(raw, bound) {
  if (!bound) return raw;
  const minimum = Number(bound.minimum) || 0;
  const maximum = Number(bound.maximum);
  if (!Number.isFinite(maximum) || maximum === minimum) return raw;
  return (100 * (raw - minimum)) / (maximum - minimum);
}
function threePointTotals(quiz) {
  const totals = {};
  (quiz.results || []).forEach((r) => { totals[r.id] = 0; });
  (quiz.questions || []).forEach((q) => {
    (q.options || []).forEach((option) => {
      Object.entries(option.scores || {}).forEach(([rid, pts]) => {
        if (pts === 3 && Object.prototype.hasOwnProperty.call(totals, rid)) totals[rid] += 1;
      });
    });
  });
  return totals;
}
function selectedThreePointCounts(quiz, answers) {
  const selected = {};
  (quiz.results || []).forEach((r) => { selected[r.id] = 0; });
  (quiz.questions || []).forEach((q, qi) => {
    const option = q.options[answers[qi]];
    if (!option || !option.scores) return;
    Object.entries(option.scores).forEach(([rid, pts]) => {
      if (pts === 3 && Object.prototype.hasOwnProperty.call(selected, rid)) selected[rid] += 1;
    });
  });
  return selected;
}
function selectWinner(quiz, answers) {
  if (quiz.format === "index" && quiz.axis) {
    let raw = 0;
    (quiz.questions || []).forEach((q, qi) => {
      const option = q.options[answers[qi]];
      if (option && option.scores) raw += option.scores[quiz.axis] || 0;
    });
    const bounds = quiz.scoring && quiz.scoring.normalization_bounds;
    const value = normalizeScore(raw, bounds ? bounds[quiz.axis] : null);
    const safe = Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
    const bands = (quiz.results || []).slice()
      .sort((a, b) => ((a.range && a.range[0]) || 0) - ((b.range && b.range[0]) || 0));
    const band = bands.find((r) => Array.isArray(r.range) && safe >= r.range[0] && safe <= r.range[1])
      || bands[bands.length - 1]
      || null;
    return { winnerId: band ? band.id : null, ranked: bands.map((b) => b.id), scores: { [quiz.axis]: raw }, index: Math.round(safe) };
  }
  const raw = rawScores(quiz, answers);
  const ids = (quiz.results || []).map((r) => r.id);
  if (!ids.length) return { winnerId: null, ranked: [], scores: raw };
  if (!quiz.scoring || !quiz.scoring.normalization_bounds) {
    const winnerId = ids.slice().sort((a, b) => raw[b] - raw[a])[0];
    return { winnerId, ranked: ids.slice().sort((a, b) => raw[b] - raw[a]), scores: raw };
  }
  const bounds = quiz.scoring.normalization_bounds;
  const order = quiz.scoring.result_order && quiz.scoring.result_order.length ? quiz.scoring.result_order : ids;
  const totals = threePointTotals(quiz);
  const selected = selectedThreePointCounts(quiz, answers);
  const ranked = ids.slice().sort((a, b) => {
    const diff = normalizeScore(raw[b], bounds[b]) - normalizeScore(raw[a], bounds[a]);
    if (Math.abs(diff) > 1e-9) return diff;
    const shareA = totals[a] ? selected[a] / totals[a] : 0;
    const shareB = totals[b] ? selected[b] / totals[b] : 0;
    if (Math.abs(shareA - shareB) > 1e-12) return shareB - shareA;
    const orderA = order.indexOf(a);
    const orderB = order.indexOf(b);
    return (orderA === -1 ? ids.indexOf(a) : orderA) - (orderB === -1 ? ids.indexOf(b) : orderB);
  });
  return { winnerId: ranked[0], ranked, scores: raw };
}

/* --------------------------- UI --------------------------- */
const THEME = window.__THEME__;
const app = document.querySelector("#app");
let state = { index: 0, answers: [] };

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function renderIntro() {
  app.innerHTML =
    '<section class="hero">' +
    '<div class="eyebrow">' + esc(THEME.title) + '</div>' +
    '<h1>' + esc(THEME.title) + '</h1>' +
    '<p class="lead">' + esc(THEME.subtitle || "") + '</p>' +
    '<div class="cover-actions"><button class="primary" id="start">开始测试</button></div>' +
    '<p class="notice">' + esc(THEME.disclaimer || DISCLAIMER) + '</p>' +
    '</section>';
  document.querySelector("#start").addEventListener("click", () => { state = { index: 0, answers: [] }; renderQuestion(); });
}
function renderQuestion() {
  const q = THEME.questions[state.index];
  const progress = Math.round(((state.index) / THEME.questions.length) * 100);
  app.innerHTML =
    '<div class="progress" role="progressbar"><i style="width:' + progress + '%"></i></div>' +
    '<div class="question-number">QUESTION ' + String(state.index + 1).padStart(2, "0") + ' / ' + THEME.questions.length + '</div>' +
    '<div class="question">' + esc(q.question) + '</div>' +
    '<div class="options">' +
    q.options.map((o, i) =>
      '<button class="option" data-answer="' + i + '"><b>' + String.fromCharCode(65 + i) + '</b><span>' + esc(o.text) + '</span></button>'
    ).join("") +
    '</div>' +
    (state.index > 0 ? '<button class="back" id="prev">← 上一题</button>' : '');
  app.querySelectorAll("[data-answer]").forEach((el) => {
    el.addEventListener("click", () => {
      state.answers[state.index] = Number(el.dataset.answer);
      state.index += 1;
      state.index < THEME.questions.length ? renderQuestion() : renderResult();
    });
  });
  const prev = document.querySelector("#prev");
  if (prev) prev.addEventListener("click", () => { state.index -= 1; renderQuestion(); });
  window.scrollTo(0, 0);
}
function renderResult() {
  const verdict = selectWinner(THEME, state.answers);
  const result = (THEME.results || []).find((r) => r.id === verdict.winnerId) || {};
  app.innerHTML =
    '<section class="hero result-hero">' +
    '<div class="eyebrow">你的结果</div>' +
    '<article class="result-panel result-card result-' + esc(result.id) + '">' +
    '<h2>' + esc(result.name || "结果") + '</h2>' +
    (result.subtitle ? '<p class="result-subtitle">' + esc(result.subtitle) + '</p>' : "") +
    (result.reading ? '<p class="result-copy">' + esc(result.reading) + '</p>' : "") +
    (result.share_line ? '<blockquote class="quote">' + esc(result.share_line) + '</blockquote>' : "") +
    '</article>' +
    '<p class="small result-disclaimer">' + esc(THEME.disclaimer || DISCLAIMER) + '</p>' +
    '<div class="actions"><button class="secondary" id="again">再测一次</button></div>' +
    '</section>';
  document.querySelector("#again").addEventListener("click", renderIntro);
  window.scrollTo(0, 0);
}
renderIntro();
`;

