const DISCLAIMER = "This is a cultural character-style experience, not a scientific personality assessment.";

const RUNNER = `
function rawScores(quiz, answers) {
  const scores = {};
  (quiz.results || []).forEach((r) => { scores[r.id] = 0; });
  (quiz.questions || []).forEach((q, qi) => {
    const option = q.options[answers[qi]];
    if (!option || !option.scores) return;
    Object.entries(option.scores).forEach(([rid, pts]) => {
      if (Object.prototype.hasOwnProperty.call(scores, rid)) scores[rid] += pts;
    });
  });
  return scores;
}
function normalizeScore(raw, bound) {
  if (!bound) return raw;
  const minimum = Number(bound.minimum) || 0;
  const maximum = Number(bound.maximum);
  if (!Number.isFinite(maximum) || maximum === minimum) return raw;
  return (100 * (raw - minimum)) / (maximum - minimum);
}
function threePointTotals(quiz) {
  const totals = {};
  (quiz.results || []).forEach((r) => { totals[r.id] = 0; });
  (quiz.questions || []).forEach((q) => {
    (q.options || []).forEach((option) => {
      Object.entries(option.scores || {}).forEach(([rid, pts]) => {
        if (pts === 3 && Object.prototype.hasOwnProperty.call(totals, rid)) totals[rid] += 1;
      });
    });
  });
  return totals;
}
function selectedThreePointCounts(quiz, answers) {
  const selected = {};
  (quiz.results || []).forEach((r) => { selected[r.id] = 0; });
  (quiz.questions || []).forEach((q, qi) => {
    const option = q.options[answers[qi]];
    if (!option || !option.scores) return;
    Object.entries(option.scores).forEach(([rid, pts]) => {
      if (pts === 3 && Object.prototype.hasOwnProperty.call(selected, rid)) selected[rid] += 1;
    });
  });
  return selected;
}
function selectWinner(quiz, answers) {
  if (quiz.format === "index" && quiz.axis) {
    let raw = 0;
    (quiz.questions || []).forEach((q, qi) => {
      const option = q.options[answers[qi]];
      if (option && option.scores) raw += option.scores[quiz.axis] || 0;
    });
    const bounds = quiz.scoring && quiz.scoring.normalization_bounds;
    const value = normalizeScore(raw, bounds ? bounds[quiz.axis] : null);
    const safe = Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
    const bands = (quiz.results || []).slice()
      .sort((a, b) => ((a.range && a.range[0]) || 0) - ((b.range && b.range[0]) || 0));
    const band = bands.find((r) => Array.isArray(r.range) && safe >= r.range[0] && safe <= r.range[1])
      || bands[bands.length - 1]
      || null;
    return { winnerId: band ? band.id : null, ranked: bands.map((b) => b.id), scores: { [quiz.axis]: raw }, index: Math.round(safe) };
