  const result = (THEME.results || []).find((r) => r.id === verdict.winnerId) || {};
  const indexBadge = typeof verdict.index === "number"
    ? '<div class="index-badge">' + esc(THEME.title.replace(/^你的|指数$|快测$/g, "")) + '指数 <b>' + verdict.index + '</b></div>'
    : "";
