    '<h2>' + esc(result.name || "结果") + '</h2>' +
    (result.subtitle ? '<p class="result-subtitle">' + esc(result.subtitle) + '</p>' : "") +
    (result.reading ? '<p class="result-copy">' + esc(result.reading) + '</p>' : "") +
    (result.share_line ? '<blockquote class="quote">' + esc(result.share_line) + '</blockquote>' : "") +
    '</article>' +
    '<p class="small result-disclaimer">' + esc(THEME.disclaimer || DISCLAIMER) + '</p>' +
    '<div class="actions"><button class="secondary" id="again">再测一次</button></div>' +
    '</section>';
  document.querySelector("#again").addEventListener("click", renderIntro);
  window.scrollTo(0, 0);
}
renderIntro();
`;

