  globalThis.__C2 = host.data.product_id;
  return `winner=${score.data.winnerId}`;
});

await check("新形态② index 指数：发布 + 评分响应带 0–100 指数分", async () => {
  const host = await api("/api/creator/host", {
    method: "POST",
    creatorKey: globalThis.__CREATOR_KEY,
    body: { mode: "skeleton", skeleton_id: "neihao-index", title: "内耗指数 · 测试版", subtitle: "12 个日常小瞬间。" },
  });
  assert(host.status === 200 && host.data.ok, `index 发布失败: ${JSON.stringify(host.data)}`);
  const mint = await api("/api/creator/mint", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { product_id: host.data.product_id, count: 1 } });
  assert(mint.status === 200, `拿码失败: ${JSON.stringify(mint.data)}`);
  const code = mint.data.codes[0];
  const redeem = await api("/api/redeem", { method: "POST", body: { code } });
  assert(redeem.status === 200, `买家兑换 ${redeem.status}`);
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", host.data.product_id, "content.json"), "utf8")).themes[0];
  const answers = raw.questions.map((q) => 1); // 全选内耗项 → 指数应接近 100
  const score = await api("/api/score", { method: "POST", body: { test_id: host.data.product_id, theme: host.data.product_id, answers, code, secret: redeem.data.secret } });
  assert(score.status === 200 && score.data.ok, `index 评分失败: ${JSON.stringify(score.data)}`);
  assert(typeof score.data.index === "number" && score.data.index >= 0 && score.data.index <= 100, `指数缺失: ${JSON.stringify(score.data)}`);
  assert(score.data.index >= 90, `全选内耗项指数应 ≥90，实际 ${score.data.index}`);
  const low = await api("/api/score", { method: "POST", body: { test_id: host.data.product_id, theme: host.data.product_id, answers: raw.questions.map(() => 0), code, secret: redeem.data.secret } });
  assert(low.data.index <= 10, `全选松弛项指数应 ≤10，实际 ${low.data.index}`);
  return `index=${score.data.index}/${low.data.index}`;
});

await check("index 校验：缺 range 的档位 → 拒绝", async () => {
  const skel = JSON.parse(readFileSync(join(ROOT, "server", "content", "skeletons", "neihao-index.json"), "utf8"));
  delete skel.results[1].range;
  const bad = await api("/api/creator/host", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { mode: "custom", content: skel } });
  assert(bad.status === 400 && (bad.data.errors || []).some((e) => e.includes("range")), `应报 range 错误: ${JSON.stringify(bad.data)}`);
  return "rejected";
});

/* ---------------------- ⑥ 浏览器行为（DOM 桩，放最后：会替换全局 fetch） ---- */
await check("专属链接 ?code= 自动填码：DOM 桩直达封面", async () => {
  const { installDom } = await import("./lib/dom-stub.mjs");
  const { installApiStub } = await import("./lib/api-stub.mjs");
  const { bootApp, unbootSkinApp } = await import("./lib/boot-app.mjs");
  const { sleep } = await import("./lib/suite.mjs");
  const dom = installDom({ pathname: `/t/${globalThis.__PRODUCT}`, search: `?code=${globalThis.__BUYER_CODE2}` });
  const creatorTheme = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", globalThis.__PRODUCT, "content.json"), "utf8")).themes[0];
  installApiStub({ productId: globalThis.__PRODUCT, productName: "测试", themes: [creatorTheme], code: globalThis.__BUYER_CODE2, secret: "[REDACTED:SECRET_ASSIGNMENT]" });
  await bootApp();
  await sleep(300);
  assert(dom.appEl.querySelector("#cover-start"), "专属链接应自动兑换直达封面");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1"));
  assert(stored && stored.code === globalThis.__BUYER_CODE2, `license 应存专属码: ${stored && stored.code}`);
  unbootSkinApp();
  return "one-click";
});

await check("导出文件独立可跑：新 DOM 桩直接从内嵌数据渲染题目", async () => {
  const { installDom } = await import("./lib/dom-stub.mjs");
  const { sleep } = await import("./lib/suite.mjs");
  const dom = installDom({ pathname: "/standalone.html" });
  const html = globalThis.__EXPORT;
  const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/g)].map((m) => m[1]);
  const themeSrc = scripts.find((s) => s.includes("__THEME__"));
  const runnerSrc = scripts.find((s) => s.includes("function selectWinner"));
  assert(themeSrc && runnerSrc, "导出包缺内嵌脚本");
  new Function(themeSrc)(); // 设置 window.__THEME__
  new Function(runnerSrc)(); // 渲染 + 判定
  await sleep(120);
  assert(dom.appEl.querySelector("#start"), "独立包应渲染开始页");
  dom.appEl.querySelector("#start").click();
  await sleep(60);
  assert(dom.appEl.querySelectorAll(".option").length === 3, "独立包题目渲染异常");
  return "standalone ok";
});

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n创作者工坊 · 全流程 E2E\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
server.kill();
rmSync(DATA_DIR, { recursive: true, force: true });
process.exit(failures.length ? 1 : 0);

