#!/usr/bin/env node
// build-format-demos.mjs — 三种产品形态的可玩 demo 生成器。
//
// 读取真实骨架包（server/content/skeletons/），生成 preview/format-demos/index.html：
// 一个自包含页面，三个可交互 demo（archetype / choice2 / index），
// 每个形态一套独立设计语言，结果页按竖版截图友好（390px）设计。
//
// Run: node tools/build-format-demos.mjs
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const OUT = join(ROOT, "preview", "format-demos");
const skeleton = (id) => JSON.parse(readFileSync(join(ROOT, "server", "content", "skeletons", `${id}.json`), "utf8"));

const ARCH = skeleton("late-night-store");
const C2 = skeleton("night-animals");
const IX = skeleton("neihao-index");

// 结果页强调色（每原型/档位一色，模仿"内在色彩人格"的视觉系玩法）
ARCH.resultColors = {
  "hot-meal": "#F2A65A", "instant-noodle": "#EFD26A", "ice-cream": "#F2B8C6",
  "black-coffee": "#8A6A52", "rice-ball": "#D8CBB2", "soda": "#7FD1C0",
};
C2.resultColors = { owl: "#A78BFA", fox: "#F59E5B", raccoon: "#7FA6C9", moth: "#6EE7C8" };
IX.bandColors = { calm: "#7FD1C0", drift: "#8FB7E8", swirl: "#B78BE8", storm: "#E86FA8" };

const esc = JSON.stringify;

const RUNNER = `
const FORMATS = window.__FORMATS__;
const app = document.querySelector("#stage");
let current = null;
let state = null;

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function rawScores(quiz, answers) {
  const scores = {};
  (quiz.results || []).forEach((r) => { scores[r.id] = 0; });
  (quiz.questions || []).forEach((q, qi) => {
    const option = q.options[answers[qi]];
    if (option && option.scores) Object.entries(option.scores).forEach(([rid, pts]) => {
      if (rid in scores) scores[rid] += pts;
    });
  });
  return scores;
}
function normalizeScore(raw, bound) {
  if (!bound) return raw;
  const min = Number(bound.minimum) || 0;
  const max = Number(bound.maximum);
  if (!Number.isFinite(max) || max === min) return raw;
  return (100 * (raw - min)) / (max - min);
}
function selectWinner(quiz, answers) {
  if (quiz.format === "index" && quiz.axis) {
    let raw = 0;
    (quiz.questions || []).forEach((q, qi) => {
      const o = q.options[answers[qi]];
      if (o && o.scores) raw += o.scores[quiz.axis] || 0;
    });
    const bounds = quiz.scoring && quiz.scoring.normalization_bounds;
    const value = normalizeScore(raw, bounds ? bounds[quiz.axis] : null);
    const safe = Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
    const bands = (quiz.results || []).slice().sort((a, b) => (a.range?.[0] || 0) - (b.range?.[0] || 0));
    const band = bands.find((r) => safe >= r.range[0] && safe <= r.range[1]) || bands[bands.length - 1];
    return { winnerId: band.id, scores: {}, index: Math.round(safe) };
  }
  const raw = rawScores(quiz, answers);
  const bounds = quiz.scoring.normalization_bounds;
  const order = quiz.scoring.result_order || (quiz.results || []).map((r) => r.id);
  const ranked = (quiz.results || []).map((r) => r.id).slice().sort((a, b) => {
    const diff = normalizeScore(raw[b], bounds[b]) - normalizeScore(raw[a], bounds[a]);
    if (Math.abs(diff) > 1e-9) return diff;
    const shareA = (quiz.__three?.[a] || 0);
    const shareB = (quiz.__three?.[b] || 0);
    return shareB - shareA || order.indexOf(a) - order.indexOf(b);
  });
  return { winnerId: ranked[0], ranked };
}

function start(formatId) {
  current = FORMATS[formatId];
  state = { index: 0, answers: [] };
  render();
}
function render() {
  const q = current.questions[state.index];
  if (q) renderQuestion(q); else renderResult();
}
function renderQuestion(q) {
  const two = q.options.length === 2;
  app.className = "stage f-" + current.format;
  app.innerHTML =
    '<div class="q-head"><span class="q-count">' + String(state.index + 1).padStart(2, "0") + ' / ' + current.questions.length + '</span><span class="q-brand">' + esc(current.brand) + '</span></div>' +
    '<div class="q-bar"><i style="width:' + Math.round((state.index / current.questions.length) * 100) + '%"></i></div>' +
    '<div class="q-text">' + esc(q.question) + '</div>' +
    '<div class="' + (two ? "opts2" : "opts3") + '">' +
    q.options.map((o, i) =>
      '<button class="opt" data-i="' + i + '"><span class="opt-key">' + String.fromCharCode(65 + i) + '</span><span class="opt-text">' + esc(o.text) + '</span></button>'
    ).join("") +
    '</div>';
  app.querySelectorAll(".opt").forEach((el) => el.addEventListener("click", () => {
    state.answers[state.index] = Number(el.dataset.i);
    state.index += 1;
    render();
  }));
}
function countUp(el, target) {
  let n = 0;
  const step = Math.max(1, Math.round(target / 28));
  const timer = setInterval(() => {
    n = Math.min(target, n + step);
    el.textContent = n;
    if (n >= target) clearInterval(timer);
  }, 34);
}
function renderResult() {
  const verdict = selectWinner(current, state.answers);
  const result = current.results.find((r) => r.id === verdict.winnerId);
  const color = (current.resultColors || current.bandColors || {})[result.id] || "#EFD26A";
  const keywords = (result.keywords || []).map((k) => '<span class="chip">' + esc(k) + '</span>').join("");
  let body = "";
  if (current.format === "index") {
    body =
      '<div class="ix-wrap" style="--rc:' + color + '">' +
      '<div class="ix-label">' + esc(current.indexLabel) + '</div>' +
      '<div class="ix-number" id="ixnum">0</div>' +
      '<div class="ix-meter"><i style="width:' + verdict.index + '%;background:' + color + '"></i></div>' +
      '</div>' +
      '<div class="card" style="--rc:' + color + '"><h2>' + esc(result.name) + '</h2>' +
      '<p class="sub">' + esc(result.subtitle) + '</p>' +
      '<p class="reading">' + esc(result.reading) + '</p></div>';
  } else {
    body =
      '<div class="card hero-card" style="--rc:' + color + '">' +
      '<div class="card-glyph">' + esc(current.glyphs?.[result.id] || result.name.slice(0, 1)) + '</div>' +
      '<h2>' + esc(result.name) + '</h2>' +
      '<p class="sub">' + esc(result.subtitle) + '</p>' +
      '<div class="chips">' + keywords + '</div>' +
      '<p class="reading">' + esc(result.reading) + '</p>' +
      '<div class="quote">“' + esc(result.share_line) + '”</div>' +
      '</div>';
  }
  app.className = "stage f-" + current.format + " is-result";
  app.style.setProperty("--rc", color);
  app.innerHTML =
    '<div class="q-head"><span class="q-count">RESULT</span><span class="q-brand">' + esc(current.brand) + '</span></div>' +
    body +
    '<div class="byline">由 <b>' + esc(current.author) + '</b> 出品 · MYTHIC 工坊</div>' +
    '<button class="replay" id="replay">再测一次</button>';
  app.querySelector("#replay").addEventListener("click", () => start(current.id));
  if (current.format === "index") countUp(app.querySelector("#ixnum"), verdict.index);
}

document.querySelectorAll("[data-tab]").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll("[data-tab]").forEach((b) => b.classList.toggle("on", b === btn));
    start(btn.dataset.tab);
  });
});
start("archetype");
`;

