const html = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>MYTHIC 工坊 · 三种产品形态 Demo</title>
<style>${CSS}</style>
</head>
<body>
<header>
  <div class="k">Mythic Factory · Format Demos</div>
  <h1>三种产品形态，都能长成什么样</h1>
