const TABS = [
  { id: "archetype", label: "原型加权 · 深夜便利店" },
  { id: "choice2", label: "30 秒二选一 · 夜行动物" },
  { id: "index", label: "指数分档 · 内耗指数" },
];

const CONFIG = {
  archetype: {
    ...ARCH, brand: "MYTHIC 便利店 · 深夜营业中", author: "@小张",
    indexLabel: "",
  },
  choice2: {
    ...C2, brand: "MYTHIC 快测 · 30 秒", author: "@小张",
    glyphs: { owl: "🦉", fox: "🦊", raccoon: "🦝", moth: "🌙" },
