export function validateAnswers(quiz, answers) {
  const questions = quiz.questions || [];
  const rounds = quiz.pair ? 2 : 1; // 合盘形态：answers = 我的一轮 + 对方的一轮
  if (!Array.isArray(answers)) return "answers must be an array of option indices";
  if (answers.length !== questions.length * rounds) {
    return `answers length ${answers.length} does not match ${questions.length} questions × ${rounds} round(s)`;
  }
  for (let i = 0; i < answers.length; i += 1) {
    const a = answers[i];
    if (!Number.isInteger(a) || a < 0 || a >= questions[i % questions.length].options.length) {
      return `answers[${i}] is not a valid option index`;
    }
  }
  return null;
}

