// Mythic H5 — monolithic licensing + static server. Node >= 22.5, zero deps.
//
//   node server/server.mjs                 (PORT=8765, serves deploy-ready/)
//   MYTHIC_PORT=... MYTHIC_DATA_DIR=... MYTHIC_ADMIN_KEY=... node server/server.mjs
//
// Endpoints:
//   POST /api/redeem            {code, secret?, fingerprint?}        bind or re-enter
//   POST /api/verify-license    {code, secret, fingerprint?}         silent boot check
//   POST /api/score             {test_id?, theme, answers, code, secret} server-side scoring
//   GET  /api/content?test_id=  sanitized quiz content for one product
//   POST /api/admin/create-codes   x-admin-key: {product_id?, count, note}
//   POST /api/admin/reset-binding  x-admin-key: {code}
//   GET  /api/admin/list            x-admin-key
//
// test_id defaults to greek_goddess, so the existing frontend — which sends no
// test_id — keeps working unchanged. The full quiz files (weights + result
// texts) live under server/content/, OUTSIDE the web root; the static handler
// also refuses those filenames anywhere.
import { createServer } from "node:http";
import { createHash, timingSafeEqual } from "node:crypto";
import { readFileSync, existsSync } from "node:fs";
import { join, dirname, extname, normalize } from "node:path";
import { fileURLToPath } from "node:url";

import { openStore, ensureAdminKey, sha256, normalizeCode, newDeviceSecret } from "./store.mjs";
import { sanitizeTheme } from "./sanitize.mjs";
import { selectWinner, validateAnswers } from "./scoring.mjs";
import { DEFAULT_PRODUCT_ID, getProduct, productThemes, productEntitles, listSkeletons } from "./products.mjs";
import { PRICING, redeemKitForNewCreator, authCreator, creatorOverview, hostProduct, mintCodes, topUp, downloadKit, exportStandalone } from "./creators.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const WEB_ROOT = join(HERE, "..", "deploy-ready");
const DATA_DIR = process.env.MYTHIC_DATA_DIR || join(HERE, "data");
const PORT = Number(process.env.MYTHIC_PORT || process.env.PORT || 8765);
// 生产环境置 MYTHIC_HOST=127.0.0.1（systemd unit 默认值），仅 Caddy 可达。
const HOST = process.env.MYTHIC_HOST || "0.0.0.0";

// ---------------------------------------------------------------- content ----
// Sanitized payloads are cached per product id.
const sanitizedCache = new Map();
function sanitizedFor(testId) {
  if (!sanitizedCache.has(testId)) {
    const themes = productThemes(testId);
    if (!themes) return null;
    const product = getProduct(testId);
    sanitizedCache.set(testId, JSON.stringify({
      product: { product_id: testId, name: product.name || testId },
      themes: themes.map(sanitizeTheme),
    }));
  }
  return sanitizedCache.get(testId);
}

// ------------------------------------------------------------------ store ----
const store = openStore(DATA_DIR);
const ADMIN_KEY = ensureAdminKey(DATA_DIR);

const adminKeyOk = (req) => {
  const given = String(req.headers["x-admin-key"] || "");
  if (!given || given.length !== ADMIN_KEY.length) return false;
  return timingSafeEqual(Buffer.from(given), Buffer.from(ADMIN_KEY));
};

// ------------------------------------------------------------- rate limit ----
// In-memory per-IP limiter on the code-guessing surface only. Codes have ~5e15
// combinations; this just stops scripted spraying from wasting cycles.
// MYTHIC_RATE_LIMIT 供测试/内网环境放宽（默认 12 次/分钟）。
const WINDOW_MS = 60_000;
const REDEEM_LIMIT = Number(process.env.MYTHIC_RATE_LIMIT) || 12;
const hits = new Map();
function rateLimited(ip) {
  const now = Date.now();
  const entry = hits.get(ip);
  if (!entry || now - entry.t0 > WINDOW_MS) {
    hits.set(ip, { t0: now, n: 1 });
    return false;
  }
  entry.n += 1;
  return entry.n > REDEEM_LIMIT;
}
setInterval(() => {
  const now = Date.now();
  for (const [ip, entry] of hits) if (now - entry.t0 > WINDOW_MS * 2) hits.delete(ip);
}, WINDOW_MS).unref();

// ---------------------------------------------------------------- helpers ----
const sha = (s) => sha256(s);

function json(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Cache-Control": "no-store",
  });
  res.end(payload);
}

async function readBody(req, limit = 64 * 1024) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw new Error("body too large");
    chunks.push(chunk);
  }
  if (!chunks.length) return {};
  return JSON.parse(Buffer.concat(chunks).toString("utf8"));
}

const productName = (id) => (getProduct(id) || {}).name || id;

// License gate shared by /api/score: returns { failure: null, row } when allowed,
// else { failure: [status, body] }. The row carries product_id for entitlement checks.''
function licenseFailure(body, { requireActivated = true } = {}) {
  const code = normalizeCode(body.code);
  if (!code) return { failure: [400, { ok: false, error: "invalid_code" }] };
  const row = store.find(code);
  if (!row) return { failure: [404, { ok: false, error: "invalid_code" }] };
  if (requireActivated) {
    if (!row.activated) return { failure: [403, { ok: false, error: "not_activated" }] };
    const presented = typeof body.secret === "string" ? sha(body.secret) : null;
    if (!presented || presented !== row.device_hash) {
      return { failure: [403, { ok: false, error: "already_bound" }] };
    }
  }
  // Auxiliary fingerprint: count mismatches, never block (req: 只做辅助校验).
  if (body.fingerprint && row.activated) {
    if (row.fingerprint_hash && sha(body.fingerprint) !== row.fingerprint_hash) {
      store.countFingerprintMismatch(code);
    }
  }
  store.touch(code);
  return { failure: null, row };
}

// ------------------------------------------------------------------ admin ----
function handleAdmin(req, res, url, body) {
  if (!adminKeyOk(req)) return json(res, 403, { ok: false, error: "bad_admin_key" });
  if (url.pathname === "/api/admin/create-codes" && req.method === "POST") {
    const productId = String(body.product_id || body.test_id || DEFAULT_PRODUCT_ID);
    if (!getProduct(productId)) return json(res, 404, { ok: false, error: "unknown_product" });
    const count = Math.min(Math.max(Number(body.count) || 1, 1), 500);
    const codes = store.createCodes(count, productId, String(body.note || "").slice(0, 120));
    return json(res, 200, { ok: true, product_id: productId, codes });
  }
  if (url.pathname === "/api/admin/reset-binding" && req.method === "POST") {
    const code = normalizeCode(body.code);
    if (!code) return json(res, 400, { ok: false, error: "invalid_code" });
    const ok = store.resetBinding(code);
    return json(res, ok ? 200 : 404, { ok, error: ok ? undefined : "invalid_code" });
  }
  if (url.pathname === "/api/admin/list" && req.method === "GET") {
    return json(res, 200, { ok: true, licenses: store.list() });
  }
  return json(res, 404, { ok: false, error: "unknown_admin_route" });
}

// ------------------------------------------------------------------ router ---
async function handleApi(req, res) {
  const url = new URL(req.url, "http://localhost");
  const isPost = req.method === "POST";
  let body = {};
  if (isPost && !url.pathname.startsWith("/api/admin")) {
    try {
      body = await readBody(req);
    } catch {
      return json(res, 400, { ok: false, error: "bad_body" });
    }
  } else if (isPost) {
    try {
      body = await readBody(req);
    } catch {
      return json(res, 400, { ok: false, error: "bad_body" });
    }
  }

  if (url.pathname.startsWith("/api/admin")) return handleAdmin(req, res, url, body);

  // ---------------------------------------------------- 创作者工坊 ----
  if (url.pathname.startsWith("/api/creator/")) {
    const limited = rateLimited(req.socket.remoteAddress || "?");
    if (url.pathname === "/api/creator/redeem" && isPost) {
      if (limited) return json(res, 429, { ok: false, error: "rate_limited" });
      const out = redeemKitForNewCreator(store, body);
      return json(res, out.status, out.body);
    }
    const auth = authCreator(store, req);
    if (auth.error) return json(res, auth.error.status, auth.error.body);
    const { creator } = auth;

    if (url.pathname === "/api/creator/overview" && req.method === "GET") {
      const out = creatorOverview(store, creator);
      return json(res, out.status, out.body);
    }
    if (url.pathname === "/api/creator/host" && isPost) {
      if (limited) return json(res, 429, { ok: false, error: "rate_limited" });
      const out = hostProduct(store, creator, body);
      return json(res, out.status, out.body);
    }
    if (url.pathname === "/api/creator/topup" && isPost) {
      if (limited) return json(res, 429, { ok: false, error: "rate_limited" });
      const out = topUp(store, creator, body);
      return json(res, out.status, out.body);
    }
    if (url.pathname === "/api/creator/mint" && isPost) {
      if (limited) return json(res, 429, { ok: false, error: "rate_limited" });
      const out = mintCodes(store, creator, body);
      return json(res, out.status, out.body);
    }
    if (url.pathname === "/api/creator/export" && isPost) {
      const out = exportStandalone(store, creator, body, { getThemeFn: productThemes });
      if (out.body) return json(res, out.status, out.body);
      res.writeHead(200, {
        "Content-Type": "text/html; charset=utf-8",
        "Content-Disposition": `attachment; filename="${out.filename}"`,
        "Cache-Control": "no-store",
      });
      return res.end(out.html);
    }
    if (url.pathname === "/api/creator/kit" && isPost) {
      const out = downloadKit(store, creator);
      return json(res, out.status, out.body);
    }
    if (url.pathname === "/api/creator/skeletons" && req.method === "GET") {
      // 骨架目录只暴露元数据（选题/结果名/题量），矩阵本体不出服务器
      return json(res, 200, { ok: true, skeletons: listSkeletons() });
    }
    return json(res, 404, { ok: false, error: "unknown_creator_route" });
  }

  if (url.pathname === "/api/content") {
    if (req.method !== "GET") return json(res, 405, { ok: false, error: "method" });
    const testId = url.searchParams.get("test_id") || url.searchParams.get("product_id") || DEFAULT_PRODUCT_ID;
    const payload = sanitizedFor(testId);
    if (payload === null) return json(res, 404, { ok: false, error: "unknown_test" });
    res.writeHead(200, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
    return res.end(payload);
  }

  if (url.pathname === "/api/redeem" && isPost) {
    const ip = req.socket.remoteAddress || "?";
    if (rateLimited(ip)) return json(res, 429, { ok: false, error: "rate_limited" });
    const code = normalizeCode(body.code);
    if (!code) return json(res, 400, { ok: false, error: "invalid_code" });
    const row = store.find(code);
    if (!row) return json(res, 404, { ok: false, error: "invalid_code" });

    if (!row.activated) {
      // First successful redemption: mint the device secret, keep only its hash.
      const secret = newDeviceSecret();
      store.activate(code, sha(secret), body.fingerprint ? sha(body.fingerprint) : null);
      return json(res, 200, {
        ok: true, secret, firstUse: true,
        product_id: row.product_id, product_name: productName(row.product_id),
      });
    }
    const presented = typeof body.secret === "string" ? sha(body.secret) : null;
    if (presented && presented === row.device_hash) {
      if (body.fingerprint && row.fingerprint_hash && sha(body.fingerprint) !== row.fingerprint_hash) {
        store.countFingerprintMismatch(code);
      }
      store.touch(code);
      return json(res, 200, {
        ok: true, secret: body.secret, firstUse: false,
        product_id: row.product_id, product_name: productName(row.product_id),
      });
    }
    return json(res, 403, { ok: false, error: "already_bound" });
  }

  if (url.pathname === "/api/verify-license" && isPost) {
    const { failure, row } = licenseFailure(body);
    if (failure) return json(res, failure[0], failure[1]);
    return json(res, 200, { ok: true, product_id: row.product_id, product_name: productName(row.product_id) });
  }

  if (url.pathname === "/api/score" && isPost) {
    const { failure, row } = licenseFailure(body);
    if (failure) return json(res, failure[0], failure[1]);

    const testId = String(body.test_id || body.product_id || DEFAULT_PRODUCT_ID);
    const themes = productThemes(testId);
    if (!themes) return json(res, 404, { ok: false, error: "unknown_test" });
    // The code's product must entitle the requested test (direct match, or a
    // bundle that includes it). Old greek_goddess codes pass trivially.
    if (!productEntitles(row.product_id, testId)) {
      return json(res, 403, { ok: false, error: "not_entitled", detail: `code is for ${row.product_id}` });
    }
    const theme = themes.find((t) => t.id === String(body.theme || ""));
    if (!theme) return json(res, 404, { ok: false, error: "invalid_theme" });
    const invalid = validateAnswers(theme, body.answers);
    if (invalid) return json(res, 400, { ok: false, error: "invalid_answers", detail: invalid });

    // 抽签形态：无题目，按兑换码+日期确定性抽签（同人同日同签，换日换签）。
    if (theme.format === "draw") {
      const digest = createHash("sha256").update(`${normalizeCode(body.code) || "?"}:${new Date().toISOString().slice(0, 10)}`).digest();
      const picks = theme.results || [];
      if (!picks.length) return json(res, 500, { ok: false, error: "winner_missing" });
      const pick = picks[digest[0] % picks.length];
      return json(res, 200, { ok: true, winnerId: pick.id, result: pick });
    }

    let verdict = selectWinner(theme, body.answers);
    let partnerId = null;
    let partnerResult = null;
    if (theme.format === "pair") {
      // 合盘：answers 前半是我的作答，后半是对方的
      const half = Math.floor(body.answers.length / 2);
      const partner = selectWinner(theme, body.answers.slice(half));
      partnerId = partner.winnerId;
      partnerResult = (theme.results || []).find((r) => r.id === partnerId) || null;
    }
    const result = (theme.results || []).find((r) => r.id === verdict.winnerId);
    if (!result) return json(res, 500, { ok: false, error: "winner_missing" });
    store.noteScore(normalizeCode(body.code));
    // Only the winner's record ever leaves the server.
    const payload = { ok: true, winnerId: verdict.winnerId, result };
    if (typeof verdict.index === "number") payload.index = verdict.index; // index 形态附带 0–100 指数分
    if (partnerResult) { payload.partnerId = partnerId; payload.partnerResult = partnerResult; }
    return json(res, 200, payload);
  }

  return json(res, 404, { ok: false, error: "unknown_api_route" });
}

// ----------------------------------------------------------------- static ----
const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".webp": "image/webp",
  ".png": "image/png",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
};

// The private content file must never be servable, no matter where a copy of it
// happens to land under the web root.
const BLOCKED_FILENAMES = new Set(["quiz_content_upgrade.json"]);

function serveStatic(req, res) {
  const url = new URL(req.url, "http://localhost");
  if (req.method !== "GET" && req.method !== "HEAD") {
    return json(res, 405, { ok: false, error: "method" });
  }
  // One test, one URL: the root hands you the default product's address, and
  // every /t/<product_id> serves the app shell — the page itself figures out
  // which product it is and gates access accordingly (URL confers nothing).
  if (url.pathname === "/" || url.pathname === "/t" || url.pathname === "/t/") {
    res.writeHead(302, { Location: `/t/${DEFAULT_PRODUCT_ID}` });
    return res.end();
  }
  if (url.pathname.startsWith("/t/")) {
    const testId = decodeURIComponent(url.pathname.slice(3).split("/")[0]);
    if (!getProduct(testId)) {
      res.writeHead(302, { Location: `/t/${DEFAULT_PRODUCT_ID}` });
      return res.end();
    }
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-cache" });
    return res.end(readFileSync(join(WEB_ROOT, "index.html")));
  }
  if (url.pathname === "/creator") {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-cache" });
    return res.end(readFileSync(join(WEB_ROOT, "creator.html")));
  }
  const relative = decodeURIComponent(url.pathname);
  if (BLOCKED_FILENAMES.has(relative.split("/").pop())) {
    return json(res, 404, { ok: false, error: "not_found" });
  }
  let filePath = normalize(join(WEB_ROOT, relative === "/" ? "index.html" : relative));
  if (!filePath.startsWith(normalize(WEB_ROOT))) {
    return json(res, 404, { ok: false, error: "not_found" });
  }
  if (!existsSync(filePath) || !filePath.startsWith(normalize(WEB_ROOT))) {
    return json(res, 404, { ok: false, error: "not_found" });
  }
  const type = MIME[extname(filePath)] || "application/octet-stream";
  res.writeHead(200, { "Content-Type": type, "Cache-Control": "no-cache" });
  res.end(readFileSync(filePath));
}

createServer(async (req, res) => {
  try {
    if (req.url.startsWith("/api/")) return await handleApi(req, res);
    return serveStatic(req, res);
  } catch (error) {
    console.error("[server]", req.method, req.url, error);
    return json(res, 500, { ok: false, error: "internal" });
  }
}).listen(PORT, HOST, () => {
  console.log(`[server] mythic H5 + license API on http://${HOST}:${PORT}`);
  console.log(`[server] web root: ${WEB_ROOT}`);
  console.log(`[server] data dir: ${DATA_DIR}`);
});

