#!/usr/bin/env node
// build-format-demos.mjs — 八种产品形态 demo（宁缺毋滥版）。
// 遵守仓库根 DESIGN.md：无 eyebrow、无装饰编号、无营销文案；
// 唯一主时刻 = 结果揭晓；每屏只有题面/结果/一个动作。
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const OUT = join(ROOT, "preview", "format-demos");
const skeleton = (id) => JSON.parse(readFileSync(join(ROOT, "server", "content", "skeletons", `${id}.json`), "utf8"));

const ARCH = { ...skeleton("late-night-store"), format: "archetype" };
const C2 = skeleton("night-animals");
const IX = skeleton("neihao-index");
const VC = skeleton("soul-color");
const SC = skeleton("deep-office");
const A4 = skeleton("mind-map");
const PR = skeleton("buddy-pair");
const DR = skeleton("night-lottery");

// 每结果的强调色（视觉系玩法的灵魂）
ARCH.resultColors = {
  "hot-meal": "#F2A65A", "instant-noodle": "#EFD26A", "ice-cream": "#F2B8C6",
  "black-coffee": "#8A6A52", "rice-ball": "#D8CBB2", "soda": "#7FD1C0",
};
C2.resultColors = { owl: "#A78BFA", fox: "#F59E5B", raccoon: "#7FA6C9", moth: "#6EE7C8" };
IX.bandColors = { calm: "#7FD1C0", drift: "#8FB7E8", swirl: "#B78BE8", storm: "#E86FA8" };
VC.resultColors = { sun: "#E8944A", deep: "#3D5A9E", grow: "#3FA88E", bloom: "#D4547A" };
SC.resultColors = { firefighter: "#E8734A", wizard: "#8F7AE8", listkeeper: "#5BA8A0", windowwatcher: "#8A93B8", keykeeper: "#C9A15B" };
A4.resultColors = { "sd-lp": "#8A93B8", "sd-la": "#5BA8A0", "sd-ep": "#C9A15B", "sd-ea": "#E8734A", "si-lp": "#8FB7E8", "si-la": "#E8A5C0", "si-ep": "#B78BE8", "si-ea": "#7FD1C0", "td-lp": "#5B9BD5", "td-la": "#E8B04A", "td-ep": "#D4547A", "td-ea": "#6EE7C8", "ti-lp": "#9E8FE8", "ti-la": "#F29E5B", "ti-ep": "#8FD5B8", "ti-ea": "#F2D06B" };
PR.resultColors = { rice: "#E8A54A", chatter: "#E86FA8", quiet: "#8FB7E8", rescue: "#5BA8A0", player: "#B78BE8", radio: "#6E7BB8" };
DR.resultColors = {};

// 轴显示标签（axis4）
A4.axisLabels = { charge: ["独处", "同频"], intake: ["细节", "直觉"], decide: ["逻辑", "共情"], pace: ["定盘", "应变"] };
A4.axisOrder = ["charge", "intake", "decide", "pace"];

const esc = JSON.stringify;

const RUNNER = `
const FORMATS = window.__FORMATS__;
const app = document.querySelector("#stage");
let current = null;
let state = null;

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function rawScores(quiz, answers) {
  const scores = {};
  (quiz.results || []).forEach((r) => { scores[r.id] = 0; });
  (quiz.questions || []).forEach((q, qi) => {
    const option = q.options[answers[qi]];
    if (option && option.scores) Object.entries(option.scores).forEach(([rid, pts]) => {
      if (rid in scores) scores[rid] += pts;
    });
  });
  return scores;
}
function normalizeScore(raw, bound) {
  if (!bound) return raw;
  const min = Number(bound.minimum) || 0;
  const max = Number(bound.maximum);
  if (!Number.isFinite(max) || max === min) return raw;
  return (100 * (raw - min)) / (max - min);
}
function deriveBounds(quiz) {
  const out = {};
  (quiz.results || []).forEach((r) => {
    let min = 0; let max = 0;
    (quiz.questions || []).forEach((q) => {
      const values = q.options.map((o) => o.scores[r.id] || 0);
      min += Math.min(...values); max += Math.max(...values);
    });
    out[r.id] = { minimum: min, maximum: max };
  });
  return out;
}
function selectWinner(quiz, answers) {
  if (quiz.format === "axis4" && Array.isArray(quiz.axes)) {
    const sums = {};
    quiz.axes.forEach((a) => { sums[a] = 0; });
    (quiz.questions || []).forEach((q, qi) => {
      const o = q.options[answers[qi]];
      if (o && o.scores && q.axis in sums) sums[q.axis] += o.scores[q.axis];
    });
    const combo = quiz.axes.map((a) => (sums[a] > 0 ? 1 : -1));
    const match = (quiz.results || []).find((r) => r.combo && r.combo.length === combo.length && r.combo.every((v, i) => v === combo[i]));
    return { winnerId: match ? match.id : null, sums };
  }
  if (quiz.format === "index" && quiz.axis) {
    let raw = 0;
    (quiz.questions || []).forEach((q, qi) => {
      const o = q.options[answers[qi]];
      if (o && o.scores) raw += o.scores[quiz.axis] || 0;
    });
    const bounds = (quiz.scoring && quiz.scoring.normalization_bounds) || deriveBounds(quiz);
    const value = normalizeScore(raw, bounds[quiz.axis]);
    const safe = Number.isFinite(value) ? Math.max(0, Math.min(100, value)) : 0;
    const bands = (quiz.results || []).slice().sort((a, b) => (a.range?.[0] || 0) - (b.range?.[0] || 0));
    const band = bands.find((r) => safe >= r.range[0] && safe <= r.range[1]) || bands[bands.length - 1];
    return { winnerId: band.id, index: Math.round(safe) };
  }
  const raw = rawScores(quiz, answers);
  const bounds = (quiz.scoring && quiz.scoring.normalization_bounds) || deriveBounds(quiz);
  const order = quiz.scoring && quiz.scoring.result_order || (quiz.results || []).map((r) => r.id);
  const ranked = (quiz.results || []).map((r) => r.id).slice().sort((a, b) => {
    const diff = normalizeScore(raw[b], bounds[b]) - normalizeScore(raw[a], bounds[a]);
    if (Math.abs(diff) > 1e-9) return diff;
    return order.indexOf(a) - order.indexOf(b);
  });
  return { winnerId: ranked[0] };
}

// 字形锚点：取结果名去掉"型/档/签"等尾字，按字数自适应字号（修"浣"字无意义问题）
function glyphOf(name) {
  return name.replace(/(型|档|签|系|王|精|魂|人|派|师)$/u, "") || name.slice(0, 1);
}
function glyphSize(name) {
  const core = glyphOf(name).length;
  return core === 1 ? "clamp(96px, 30vw, 130px)" : core === 2 ? "76px" : "56px";
}

function start(formatId) {
  current = FORMATS[formatId];
  state = current.format === "draw"
    ? { phase: "card" }
    : { index: 0, answers: [], round: current.pair ? 1 : 0 };
  render();
}
function render() {
  if (current.format === "draw") return renderDraw();
  const qi = state.index % current.questions.length;
  if (state.index < current.questions.length * (current.pair ? 2 : 1)) {
    renderQuestion(current.questions[qi]);
  } else {
    renderResult();
  }
}
function renderQuestion(q) {
  const two = q.options.length === 2;
  const isVisual = current.format === "visual";
  app.className = "stage f-" + current.format;
  const roundTag = current.pair
    ? '<div class="round-tag">' + (state.round === 1 ? "第一轮 · 你" : "第二轮 · 对方") + '</div>'
    : "";
  const scene = q.scene ? '<div class="scene">' + esc(q.scene) + '</div>' : "";
  app.innerHTML =
    roundTag +
    '<div class="head"><span class="count">' + String(qi + 1).padStart(2, "0") + '</span><span class="total">/ ' + current.questions.length + '</span></div>' +
    '<div class="bar"><i style="width:' + Math.round((qi / current.questions.length) * 100) + '%"></i></div>' +
    scene +
    '<div class="q">' + esc(q.question) + '</div>' +
    '<div class="' + (two ? "opts2" : isVisual ? "swatches" : "opts3") + '">' +
    q.options.map((o, i) => isVisual
      ? '<button class="swatch" style="--sw:' + o.swatch + '"><i></i><span>' + esc(o.text) + '</span></button>'
      : '<button class="opt"><span>' + esc(o.text) + '</span></button>').join("") +
    '</div>';
  app.querySelectorAll(".opt, .swatch").forEach((el, i) => el.addEventListener("click", () => {
    state.answers[state.index] = i;
    state.index += 1;
    if (current.pair && state.index === current.questions.length && state.round === 1) {
      state.round = 2; // 进入对方轮
    }
    render();
  }));
}
function countUp(el, target) {
  let n = 0;
  const step = Math.max(1, Math.round(target / 28));
  const timer = setInterval(() => {
    n = Math.min(target, n + step);
    el.textContent = n;
    if (n >= target) clearInterval(timer);
  }, 34);
}
function renderDraw() {
  app.className = "stage f-draw";
  app.innerHTML =
    '<div class="draw-hint">' + esc(current.title) + '</div>' +
    '<button class="draw-card" id="drawcard"><span>' + "今夜一签" + '</span><small>点击揭开</small></button>';
