cd ~/小红书 && python3 - <<'EOF'
p = "tools/test-creator-portal.mjs"
s = open(p).read()

s = s.replace('await check("骨架目录可见（4 套）且不泄漏评分矩阵", async () => {\n  const { status, data } = await api("/api/creator/skeletons", { creatorKey: globalThis.__CREATOR_KEY });\n  assert(status === 200 && data.skeletons.length === 4, `骨架应为 4 套，实际 ${data.skeletons?.length}`);',
              'await check("骨架目录可见（9 套）且不泄漏评分矩阵", async () => {\n  const { status, data } = await api("/api/creator/skeletons", { creatorKey: globalThis.__CREATOR_KEY });\n  assert(status === 200 && data.skeletons.length === 9, `骨架应为 9 套，实际 ${data.skeletons?.length}`);')

new_checks = '''
await check("新形态③④⑤⑥⑦：visual/scenario/axis4/pair/draw 全链路", async () => {
  const outcomes = [];
  const cases = [
    { skeleton: "soul-color", title: "灵魂底色 · 测试版", subtitle: "凭直觉选色。", expect: { format: "visual" } },
    { skeleton: "deep-office", title: "办公室图鉴 · 测试版", subtitle: "8 个深夜场景。", expect: { format: "scenario" } },
    { skeleton: "mind-map", title: "决策图谱 · 测试版", subtitle: "四条轴，一个指纹。", expect: { format: "axis4", minResults: 16 } },
    { skeleton: "buddy-pair", title: "搭子组合 · 测试版", subtitle: "两个人各答一轮。", expect: { format: "pair", pair: true } },
    { skeleton: "night-lottery", title: "今夜一签 · 测试版", subtitle: "每天一签。", expect: { format: "draw" } },
  ];
  for (const c of cases) {
    const host = await api("/api/creator/host", {
      method: "POST", creatorKey: globalThis.__CREATOR_KEY,
      body: { mode: "skeleton", skeleton_id: c.skeleton, title: c.title, subtitle: c.subtitle },
    });
    assert(host.status === 200 && host.data.ok, `${c.skeleton} 发布失败: ${JSON.stringify(host.data)}`);
    const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", host.data.product_id, "content.json"), "utf8")).themes[0];
    assert(raw.format === c.expect.format, `${c.skeleton} format 应为 ${c.expect.format}`);
    if (c.expect.minResults) assert((theme_results(raw) || []).length >= c.expect.minResults, `${c.skeleton} 结果数不足`);
    if (c.expect.pair) assert(raw.pair === true, "pair 标志丢失");
    const mint = await api("/api/creator/mint", { method: "POST", creatorKey: globalThis.__CREATOR_KEY, body: { product_id: host.data.product_id, count: 1 } });
    assert(mint.status === 200, `${c.skeleton} 拿码失败: ${JSON.stringify(mint.data)}`);
    const code = mint.data.codes[0];
    const redeem = await api("/api/redeem", { method: "POST", body: { code } });
    assert(redeem.status === 200, `${c.skeleton} 买家兑换失败`);
    const rounds = raw.pair ? 2 : 1;
    const answers = [];
    for (let i = 0; i < raw.questions.length * rounds; i += 1) answers.push(i % (raw.questions[i % raw.questions.length].options.length));
    const score = await api("/api/score", { method: "POST", body: { test_id: host.data.product_id, theme: host.data.product_id, answers, code, secret: redeem.data.secret } });
    assert(score.status === 200 && score.data.ok, `${c.skeleton} 评分失败: ${JSON.stringify(score.data)}`);
    assert((raw.results || []).some((r) => r.id === score.data.winnerId), `${c.skeleton} 命中未声明结果`);
    if (c.expect.format === "pair") {
      assert(score.data.partnerId && score.data.partnerResult, "pair 响应缺 partnerId/partnerResult");
    }
    if (c.expect.format === "draw") {
      const again = await api("/api/score", { method: "POST", body: { test_id: host.data.product_id, theme: host.data.product_id, answers: [], code, secret: redeem.data.secret } });
      assert(again.data.winnerId === score.data.winnerId, "draw 同人同日应同签");
    }
    outcomes.push(`${c.skeleton}:${score.data.winnerId}`);
  }
  function theme_results(raw) { return raw.results; }
  return outcomes.join(" | ");
});

function theme_results(raw) { return raw.results; }
'''
anchor = "await check(\"充值码自兑：topup 到账；重复使用被拒\""
s = s.replace(anchor, new_checks + "\n" + anchor)
open(p, "w").write(s)
print("patched")
